window.CarnetExerciseCatalog = [
  {"id":"56","name":"Stabilisation abdominale sur rouleau","description":"Allongé dans le sens de la longueur sur un rouleau de massage, maintenez l'équilibre et engagez la sangle abdominale profonde pour stabiliser le tronc.","region":"core","setup":["Rouleau de massage (Foam roller)","Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["Abdominal Stabilization","abdominal-stabilization"],"sourceLicense":"CC-BY-SA-3.0","sourceAuthor":"andikeller","translationLicense":"CC-BY-SA-3.0","translationAuthor":"andikeller"},
  {"id":"57","name":"Marche de l'ours","description":"Position de départ :\nMettez-vous à quatre pattes, les mains sous les épaules et les genoux sous les hanches. Décollez les genoux du sol de quelques centimètres en gardant le dos bien plat et la sangle abdominale engagée.\n\nExécution :\n1. Avancez simultanément la main droite et le pied gauche.\n2. Enchaînez en avançant la main gauche et le pied droit dans un mouvement controlatéral coordonné.\n3. Progressez à un rythme régulier sur une distance définie ou pendant un temps imparti.\n\nConseils :\nGardez le bassin bas et parallèle au sol, sans vous balancer excessivement de gauche à droite.","region":"full_body","setup":[],"muscles":["Quadriceps","Tronc / Sangle abdominale"],"search":["Bear Walk","bear-walk-2","Marche de l'ours 2"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"nate303303","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"112","name":"Body-Ups","description":"Placez-vous en position de planche au sol. Vous devez supporter le poids de votre corps sur les orteils et les avant-bras, en gardant le torse droit. Vos avant-bras doivent être écartés à la largeur des épaules. Ce sera votre position de départ.\nEn appuyant fermement les paumes contre le sol, tendez les coudes pour soulever votre corps du sol. Gardez le torse rigide pendant le mouvement.\nAbaissez lentement les avant-bras vers le sol en laissant les coudes se fléchir.\nRépétez autant de fois que nécessaire.","region":"upper_body","setup":["Tapis de sol"],"muscles":["Triceps"],"search":["Body-Ups","body-ups"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"cal.zabel","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"132","name":"Burpees avec pompes","description":"Position de départ :\nTenez-vous droit, les pieds écartés de la largeur des hanches.\nÉtapes :\n\nAccroupissez-vous et prenez appui sur le sol avec les mains entre les genoux et devant les pieds, le dos droit.\nEn gardant les mains sur le sol, lancez vos jambes vers l'arrière en position de planche haute.\nEffectuez une pompe.\nRemettez vos pieds vers l'avant pour revenir à la position de squat.\nRépétez.","region":"full_body","setup":[],"muscles":["Poitrine","Quadriceps"],"search":["Burpees","burpees"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"er0355","translationLicense":"CC-BY-SA-4.0","translationAuthor":"er0355"},
  {"id":"152","name":"Traction en supination","description":"La traction en supination est un exercice de musculation. On le pratique fréquemment dans le but de renforcer des muscles comme le grand dorsal et les biceps, qui assurent respectivement l'extension de l'épaule et la flexion du coude. Dans ce mouvement, les paumes sont tournées vers le corps. Il s'agit d'une forme de traction dont l'amplitude de mouvement est définie par rapport au menton de la personne.","region":"upper_body","setup":["Barre de traction"],"muscles":["Biceps","Dos"],"search":["Chin Up","chin-up"],"sourceLicense":"CC0-1.0","sourceAuthor":"BFad07","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"165","name":"Crunch sur ballon de gymnastique","description":"Les pieds posés sur un ballon de gymnastique ou calés dans des sangles TRX, mains au sol en planche, fléchissez les genoux pour amener le ballon vers la poitrine en enroulant le bassin.","region":"core","setup":["Ballon de gymnastique (Swiss ball)"],"muscles":["Tronc / Sangle abdominale"],"search":["Swiss Ball Knee Tuck","ball-crunches"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Konsumopfer","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Konsumopfer"},
  {"id":"167","name":"Abdominaux","description":"Position de départ :\nAllongez-vous sur le dos sur un tapis de sol, les genoux pliés à 90 degrés et les pieds à plat sur le sol à largeur de hanches. Placez les mains derrière la tête ou croisées sur la poitrine.\n\nExécution :\n1. Enroulez la colonne vertébrale en décollant les épaules et le haut du dos du sol, en rapprochant les côtes du bassin.\n2. Contractez fortement les abdominaux au sommet du mouvement pendant une seconde.\n3. Redescendez lentement et sous contrôle sans relâcher complètement la tension abdominale, puis répétez.\n\nConseils :\nNe tirez pas sur la nuque avec les mains et gardez le bas du dos bien plaqué contre le sol.","region":"core","setup":["Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["Crunch","crunches"],"sourceLicense":"CC-BY-SA-3.0","sourceAuthor":"wger.de","translationLicense":"CC-BY-SA-3.0","translationAuthor":"wger.de"},
  {"id":"171","name":"Crunchs sur banc incliné","description":"Allongez-vous sur le dos sur un banc incliné, les pieds à une extrémité du banc. Demandez à un partenaire ou utilisez un autre moyen (une barre, etc.) pour les maintenir en place, vos mains derrière la tête. À partir de cette position, relevez le haut du corps jusqu'à ce que votre tête ou vos coudes touchent vos genoux. Effectuez ce mouvement en enroulant le dos.","region":"core","setup":["Banc incliné"],"muscles":["Tronc / Sangle abdominale"],"search":["Decline Crunch","incline-crunches"],"sourceLicense":"CC-BY-SA-3.0","sourceAuthor":"wger.de","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"174","name":"Crunchs jambes en l'air","description":"Allongé sur le dos, les jambes tendues à la verticale, tendez les mains vers vos orteils et décollez les omoplates du sol avant de les reposer.","region":"core","setup":["Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["Vertical Leg Crunch","crunches-with-legs-up"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"krisbbb","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"178","name":"Deadbug","description":"Allongez-vous sur le dos, les hanches et les genoux fléchis à 90°. Levez les deux bras vers le plafond. Plaquez le bas de votre dos contre le sol pour supprimer tout espace. Commencez en tendant une jambe et en touchant le sol avec le talon. À mesure que vous tendez une jambe, expirez autant que possible en gardant le bas du dos collé au sol. Lorsque vous ne pouvez plus expirer, ramenez votre genou vers la position de départ. Rendez l'exercice plus difficile en tenant un poids dans les mains, ou en abaissant simultanément le bras et la jambe opposés.","region":"core","setup":["Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["Deadbug","deadbug"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Metin","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"182","name":"Suspension à la barre (Deadhang)","description":"Suspension passive ou active à la barre fixe ou sur une réglette, à deux mains, permettant de décompresser la colonne et de renforcer le grip.","region":"upper_body","setup":["Barre de traction"],"muscles":["Avant-bras"],"search":["Deadhang","deadhang"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"2dPREtEZP221u68Akf0JImv5L48","translationLicense":"CC-BY-SA-4.0","translationAuthor":"2dPREtEZP221u68Akf0JImv5L48"},
  {"id":"194","name":"Dips","description":"Le dip est un exercice de musculation pour le haut du corps. Les dips à prise serrée, à largeur d'épaules, sollicitent principalement les triceps, les principaux muscles synergistes étant le deltoïde antérieur, les muscles pectoraux (sternal, claviculaire et petit pectoral) et les rhomboïdes du dos (dans cet ordre).[1] Un entraînement bras écartés met davantage l'accent sur les pectoraux, de la même manière qu'un développé couché à prise large sollicite davantage les pectoraux et moins les triceps.","region":"upper_body","setup":["Barres parallèles à dips"],"muscles":["Poitrine","Triceps"],"search":["Dips","dips"],"sourceLicense":"CC0-1.0","sourceAuthor":"BFad07","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"197","name":"Dips entre deux bancs","description":"Disposez deux bancs suffisamment éloignés l'un de l'autre pour que vous puissiez vous appuyer sur l'un avec les mains tout en parvenant tout juste à atteindre l'autre avec les pieds. Les jambes restent complètement tendues pendant l'exercice. Les coudes orientés vers l'arrière, fléchissez-les autant que possible. Repoussez-vous vers le haut, mais sans tendre complètement les bras.","region":"upper_body","setup":["Banc plat"],"muscles":["Triceps"],"search":["Dips Between Two Benches","dips-between-two-benches"],"sourceLicense":"CC-BY-SA-3.0","sourceAuthor":"wger.de","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"235","name":"Battements de jambes","description":"-Allongé sur le dos, décollez vos jambes tendues du sol selon un angle de 45 degrés.\n-Lorsque votre pied gauche descend et frôle presque le sol, votre pied droit doit chercher à atteindre un angle de 90 degrés, ou s'en approcher le plus possible.\n-Abaissez votre pied droit jusqu'à ce qu'il frôle presque le sol, puis relevez votre pied gauche. Maintenez les jambes rigides pendant tout l'exercice. Votre tête doit rester décollée du sol, soutenue par le haut des abdominaux contracté.\n-(gauche en haut droit en bas, gauche en bas droit en haut, x2)  ^v, v^, ^v, v^ = 1 répétition\n-Sollicite principalement le grand droit de l'abdomen, les fléchisseurs de la hanche et le bas du dos. Sollicite secondairement les obliques. L'accent est mis sur la partie inférieure des abdominaux.","region":"core","setup":["Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["Flutter Kicks","flutter-kicks"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"nate303303","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"260","name":"Sit-outs complets","description":"(A) Mettez-vous en position de planche haute, sur les mains et la pointe des pieds.(B) Reportez votre poids sur votre main gauche en tournant votre corps vers la droite ; fléchissez votre jambe droite derrière vous et tendez votre bras droit vers le haut. Revenez au centre et répétez de l'autre côté. Continuez en alternant les côtés.Pour faciliter : ne levez pas le bras après avoir fléchi la jambe derrière vous.Pour intensifier : tenez en équilibre, bras et jambe tendus, pendant deux temps.","region":"core","setup":["Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["Full Sit-Out","full-sit-outs"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"http://www.realsimple.com/health/fitness-exercise/","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"265","name":"Pont fessier","description":"Allongez-vous sur le dos, les hanches et les genoux fléchis, les pieds au sol. À partir de cette position, soulevez les fessiers du sol jusqu'à ce que votre corps forme une ligne droite des genoux aux épaules. Pour rendre l'exercice plus intense, vous pouvez ajouter du poids en laissant reposer une barre sur vos hanches pendant que vous effectuez le mouvement, ou vous pouvez poser vos pieds sur une surface légèrement plus haute, comme une marche ou un banc.","region":"lower_body","setup":["Tapis de sol"],"muscles":["Fessiers"],"search":["Glute Bridge","glute-bridge"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"tdprice12","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"282","name":"Pompe en équilibre sur les mains","description":"La pompe en équilibre sur les mains, également appelée pompe verticale ou pompe inversée, est un type d'exercice de pompe où le corps est positionné en équilibre sur les mains. Pour un véritable équilibre, l'exercice est réalisé en autonomie, en suspension dans l'air. Afin de développer la force jusqu'à acquérir un équilibre suffisant, les pieds sont souvent placés contre un mur, tenus par un partenaire ou maintenus d'une autre façon pour éviter la chute. Les pompes en équilibre sur les mains exigent une force considérable, ainsi que de l'équilibre et du contrôle si elles sont exécutées en autonomie.","region":"upper_body","setup":["Mur"],"muscles":["Triceps","Épaules"],"search":["Handstand Pushup","handstand-pushup"],"sourceLicense":"CC0-1.0","sourceAuthor":"BFad07","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"283","name":"Relevés de jambes suspendu","description":"Suspendu à la barre de traction, levez les jambes tendues ou légèrement fléchies vers le haut jusqu'à ce que les pieds atteignent la hauteur du bassin ou de la barre en enroulant le bassin.","region":"core","setup":["Barre de traction"],"muscles":["Tronc / Sangle abdominale"],"search":["Hanging Leg Raise","hanging-leg-raises"],"sourceLicense":"CC-BY-SA-3.0","sourceAuthor":"robhoyt","translationLicense":"CC-BY-SA-3.0","translationAuthor":"robhoyt"},
  {"id":"285","name":"Sauts genoux hauts","description":"Commencez avec les jambes légèrement plus écartées que la largeur des épaules\nDescendez en squat au poids du corps\nArrivé au point bas du squat, propulsez-vous explosivement vers le haut en sautant tout en ramenant simultanément les genoux vers la poitrine en plein vol. Gardez les genoux ramenés jusqu'au sommet de votre saut.\nRéceptionnez-vous sur les deux pieds, en veillant à ne pas verrouiller les genoux afin d'éviter une tension excessive sur vos articulations. Enchaînez sur la répétition suivante aussi rapidement que possible, mais toujours avec contrôle.","region":"full_body","setup":[],"muscles":["Fessiers","Quadriceps","Tronc / Sangle abdominale"],"search":["High Knee Jumps","high-knee-jumps"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"nate303303","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"291","name":"Squats hindous","description":"Commencez les pieds à la largeur des épaules et les bras légèrement derrière le dos.\nÀ mesure que vous descendez vers le sol, décollez vos talons du sol tout en gardant le dos aussi vertical que possible.\nUne fois la position basse atteinte, touchez vos talons avec vos mains.\nRelevez-vous ensuite en terminant les talons au sol, les bras tendus devant la poitrine, puis ramenez-les en tirant vers la position de départ.","region":"lower_body","setup":[],"muscles":["Quadriceps"],"search":["Hindu Squats","hindu-squats"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Vilhelmo","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"292","name":"Pont fessier au sol","description":"Allongé sur le dos, les pieds bien à plat sur le sol. Soulevez les hanches de façon régulière aussi haut que possible et maintenez la position aussi longtemps que vous le pouvez.","region":"lower_body","setup":["Tapis de sol"],"muscles":["Fessiers"],"search":["Lying Hip Raise","hip-raise-lying","Relevé de bassin"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"James Mackay","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"297","name":"Hollow hold","description":"Installez-vous sur un tapis et allongez-vous sur le dos. Contractez les abdominaux, tendez les bras et les jambes et levez-les (votre tête et vos épaules sont également relevées). Veillez à ce que le bas de votre dos reste en contact avec le tapis.","region":"core","setup":["Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["Hollow Hold","hollow-hold"],"sourceLicense":"CC0-1.0","sourceAuthor":"Behrooz","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"301","name":"Extensions lombaires (hyperextensions)","description":"Allongez-vous sur le coussin du banc à lombaires, le nombril au niveau du bord avant, en laissant le haut du corps pendre librement. Contractez tous les muscles de votre dos et relevez le buste jusqu'à l'horizontale, mais pas plus haut. Redescendez lentement, en maintenant une contraction musculaire régulière et continue.","region":"core","setup":["Chaise romaine / Banc à lombaires"],"muscles":["Bas du dos"],"search":["Hyperextensions","hyperextensions","Extension lombaire"],"sourceLicense":"CC-BY-SA-3.0","sourceAuthor":"wger.de","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"312","name":"Planche inclinée avec touche du sol alternée","description":"Réalisez la planche jambes surélevées, les pieds sur un gym ball. Une fois stabilisé, déplacez lentement un pied sur le côté pour le sortir de la balle, faites-le toucher le sol, puis revenez à la position de départ. Alternez avec l'autre pied.\nC'est un exercice de gainage.","region":"core","setup":["Ballon de gymnastique (Swiss ball)","Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["Decline Swiss Ball Plank with Alternating Toe Tap","incline-plank-with-alternate-floor-touch"],"sourceLicense":"CC-BY-SA-3.0","sourceAuthor":"Mahoney","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"314","name":"Essuie-glaces isométriques","description":"Placez-vous en position de pompe, les mains légèrement plus écartées que la largeur des épaules.\nDéplacez le poids de votre corps aussi loin que possible vers un côté, en laissant le coude de ce côté se fléchir.\nInversez le mouvement en passant entièrement de l'autre côté.\nRevenez à la position de départ et répétez le nombre de répétitions souhaité.","region":"upper_body","setup":[],"muscles":["Poitrine"],"search":["Isometric Wipers","isometric-wipers"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"cal.zabel","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"319","name":"Jogging","description":"Course à pied à allure modérée et régulière, idéale pour le travail de l'endurance aérobie de base.","region":"lower_body","setup":[],"muscles":["Mollets","Quadriceps"],"search":["Jogging","jogging"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Papazit","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Papazit"},
  {"id":"320","name":"Sauts en étoile","description":"Debout, pieds joints et bras le long du corps\nSauter jusqu'à une position où les jambes sont écartées et les mains se touchent au-dessus de la tête.\nRépétez","region":"lower_body","setup":[],"muscles":["Mollets","Quadriceps"],"search":["Jumping Jacks","jumping-jacks"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"student1234","translationLicense":"CC-BY-SA-4.0","translationAuthor":"student1234"},
  {"id":"376","name":"Levées de jambe","description":"Position de départ :\nAllongez-vous sur le dos, les pieds joints et les bras le long du corps.\n\nÉtapes :\n1. Fléchissez légèrement les genoux puis tendez les jambes vers le haut.\n2. Gardez les jambes tendues et descendez-les ensemble de manière contrôlée sans toucher le sol. Plus la descente est basse, plus l'effort est intense.\n3. Remontez les deux jambes ensemble jusqu'à la verticale.\n4. Répétez à partir de l'étape 2.","region":"core","setup":["Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["Lying Leg Raise","leg-raise"],"sourceLicense":"CC0-1.0","sourceAuthor":"BFad07","translationLicense":"CC0-1.0","translationAuthor":"BFad07"},
  {"id":"377","name":"Relevés de jambes, allongé","description":"Allongez-vous sur un banc et tenez-vous au dossier avec les mains pour rester stable. Gardez vos jambes tendues et levez-les jusqu'à ce qu'elles forment un angle d'environ 45°. Marquez une courte pause d'une seconde et redescendez lentement à la position initiale. Pour augmenter l'intensité, vous pouvez marquer une pause plus longue de 7 secondes toutes les 5 répétitions.","region":"core","setup":["Banc plat"],"muscles":["Tronc / Sangle abdominale"],"search":["Lying Leg Raise","leg-raises-lying"],"sourceLicense":"CC-BY-SA-3.0","sourceAuthor":"wger.de","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"378","name":"Relevés de jambes, debout","description":"Placez vos avant-bras sur les coussinets de la machine à relevés de jambes, le corps est suspendu librement. Levez maintenant vos jambes par un mouvement rapide aussi haut que possible, marquez une courte pause d'une seconde en haut, puis redescendez-les. Assurez-vous que votre corps ne se balance pas pendant l'exercice, seules les jambes doivent bouger.","region":"core","setup":["Barres parallèles à dips"],"muscles":["Tronc / Sangle abdominale"],"search":["Dip Station Leg Raise","leg-raises-standing"],"sourceLicense":"CC-BY-SA-3.0","sourceAuthor":"wger.de","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"382","name":"Maintien en L (L-Hold)","description":"Suspendez-vous à une barre de traction et levez les jambes tendues jusqu'à former un angle de 90° entre les cuisses et le buste (position en L). Maintenez la position de manière statique en gainant fermement le tronc.","region":"core","setup":["Barre de traction"],"muscles":["Tronc / Sangle abdominale"],"search":["Hanging L-Sit Hold","l-hold"],"sourceLicense":"CC-BY-SA-3.0","sourceAuthor":"bizyguy","translationLicense":"CC-BY-SA-3.0","translationAuthor":"bizyguy"},
  {"id":"386","name":"Pompes diamant","description":"Départ : mettez-vous en position de planche. Placez les mains rapprochées sous votre poitrine de sorte que les pouces et les index forment un losange.\nDescente : pliez les coudes pour abaisser votre poitrine vers vos mains. Gardez le corps droit.\nPoussée : repoussez vers le haut jusqu'à ce que les bras soient complètement tendus.\nRemarque : gardez les coudes près du corps et la sangle abdominale gainée.","region":"upper_body","setup":[],"muscles":["Poitrine","Triceps"],"search":["Diamond Push-Up","diamond-push-ups"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"notdefine","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"423","name":"Muscle-up","description":"Le corps est ensuite tiré explosivement vers le haut par les bras dans une traction radiale, avec plus de vitesse qu'une traction classique. Lorsque la barre approche du haut de la poitrine, les poignets sont rapidement fléchis pour amener les avant-bras au-dessus de la barre. Le corps est penché vers l'avant et les coudes sont tendus en activant les triceps. Le mouvement est considéré comme terminé lorsque la barre est au niveau de la taille et que les bras sont complètement tendus.\nPour redescendre, les bras sont fléchis au niveau du coude et le corps est ramené vers le sol ; l'exercice peut alors être répété.\nComme il s'agit d'un exercice relativement avancé, les muscle-ups s'apprennent généralement d'abord avec un élan d'aide (kip). Les jambes se balancent (kip) vers le haut et fournissent l'élan nécessaire pour aider à la force explosive ascendante requise pour passer au-dessus de la barre. Les athlètes plus avancés peuvent réaliser une variante stricte du muscle-up, exécutée lentement et sans aucun élan. Cette variante débute en suspension complète et immobile et utilise une contraction musculaire isométrique pour passer au-dessus de la barre de manière lente et contrôlée.","region":"upper_body","setup":["Barre de traction"],"muscles":["Dos","Poitrine"],"search":["Muscle-Up","muscle-up"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"arson","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"427","name":"Crunchs négatifs","description":"Asseyez-vous sur le banc décliné et bloquez vos jambes. Croisez les bras sur la poitrine et relevez le haut du corps par un mouvement d'enroulement, puis redescendez sans pause et par un mouvement lent. Ne laissez pas votre tête bouger pendant l'exercice.","region":"core","setup":["Banc décliné"],"muscles":["Tronc / Sangle abdominale"],"search":["Decline Crunch","negative-crunches"],"sourceLicense":"CC-BY-SA-3.0","sourceAuthor":"wger.de","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"454","name":"Pompes piquées (Pike push-up)","description":"En position de V inversé (fesses hautes et jambes droites), fléchissez les coudes pour descendre le sommet du crâne vers le sol puis repoussez fermement avec les épaules.","region":"upper_body","setup":[],"muscles":["Épaules"],"search":["Pike Push-Up","pike-push-ups"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Nash","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Nash"},
  {"id":"456","name":"Pistol squats gauches","description":"Tenez-vous debout sur une jambe, l'autre jambe droite et légèrement en avant\nPliez lentement un genou, descendez en position accroupie et gardez votre dos et votre autre jambe droits\nSoulevez-vous lentement du squat, en redressant le genou plié et en gardant l'autre jambe droite\nRépéter","region":"lower_body","setup":[],"muscles":["Fessiers","Quadriceps"],"search":["Pistol Squat","pistol-squat"],"sourceLicense":"CC-BY-SA-3.0","sourceAuthor":"minifigmaster125","translationLicense":"CC-BY-SA-3.0","translationAuthor":"minifigmaster125"},
  {"id":"458","name":"Planche pour les avant-bras","description":"Position de départ :\n\nCommencez à quatre pattes.Les bras doivent être pliés à angle droit, les épaules au-dessus des coudes.Le dos doit être droit, le corps entier en ligne droite.\n\nÉtapes :\n\nMaintenez cette position.","region":"core","setup":["Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["Plank","plank"],"sourceLicense":"CC-BY-SA-3.0","sourceAuthor":"YYCfit / BFad07","translationLicense":"CC-BY-SA-3.0","translationAuthor":"YYCfit / BFad07"},
  {"id":"468","name":"Rétraction des omoplates à plat ventre - bras le long du corps","description":"Allongé sur le ventre, la tête posée sur une serviette.\nTendez les bras bien droit sur les côtés.\nLevez lentement les bras en rapprochant les omoplates l'une de l'autre, et maintenez la position pendant 3 secondes.","region":"upper_body","setup":["Tapis de sol"],"muscles":["Dos"],"search":["Prone Scapular Retraction - Arms at Side","prone-scapular-retraction-arms-at-side"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"donaddon","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"475","name":"Tractions","description":"Prenez la barre de traction avec les deux mains écartées. En gardant la poitrine en avant, tirez avec vos bras jusqu’à ce que votre mentons atteigne la barre. Controlez le mouvement lors de la montée et de la descente.","region":"upper_body","setup":["Barre de traction"],"muscles":["Dos"],"search":["Pull-Up","pull-ups"],"sourceLicense":"CC-BY-SA-3.0","sourceAuthor":"wger.de","translationLicense":"CC-BY-SA-3.0","translationAuthor":"wger.de"},
  {"id":"500","name":"Planche inversée (Reverse plank)","description":"Assis au sol, mains posées derrière le bassin, soulevez les hanches vers le haut jusqu'à aligner le torse et les jambes, la poitrine ouverte vers le plafond.","region":"full_body","setup":["Tapis de sol"],"muscles":["Bas du dos","Fessiers"],"search":["Reverse Plank","reverse-plank"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"spacetowaste","translationLicense":"CC-BY-SA-4.0","translationAuthor":"spacetowaste"},
  {"id":"501","name":"Dips aux anneaux","description":"En appui sur des anneaux de gymnastique, descendez en fléchissant les coudes jusqu'à 90 degrés tout en stabilisant les anneaux, puis repoussez pour remonter.","region":"upper_body","setup":[],"muscles":["Poitrine","Triceps"],"search":["Ring Dips","ring-dips"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Nash","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Nash"},
  {"id":"505","name":"Crunch sur banc à lombaires (roman chair)","description":"Crunchs sur banc à lombaires (roman chair). Gardez le buste droit et les abdominaux contractés ; ne remontez pas complètement à la verticale et ne vous allongez pas non plus à plat, afin de maintenir une tension constante sur vos abdominaux.","region":"core","setup":["Chaise romaine / Banc à lombaires"],"muscles":["Tronc / Sangle abdominale"],"search":["Roman Chair Crunch","roman-chair-crunch"],"sourceLicense":"CC-BY-SA-3.0","sourceAuthor":"MaddieBeasley","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"516","name":"Bûcheron frontal (Wood Chop)","description":"Debout, tenez les bras tendus au-dessus de la tête. Effectuez une extension du tronc vers le haut et l'arrière en levant alternativement une jambe vers l'arrière pour contracter les muscles érecteurs du rachis et les fessiers. Revenez en position initiale avec contrôle.","region":"core","setup":[],"muscles":["Bas du dos"],"search":["Front Wood Chop","front-wood-chop"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Konsumopfer","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Konsumopfer"},
  {"id":"527","name":"Course à pied","description":"Course à pied en extérieur (piste, route ou parc) à un rythme soutenu pour développer la capacité cardiovasculaire.","region":"lower_body","setup":[],"muscles":["Mollets","Quadriceps"],"search":["Run","run"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"BeLikeWater","translationLicense":"CC-BY-SA-4.0","translationAuthor":"BeLikeWater"},
  {"id":"529","name":"Course fractionnée (Intervalles)","description":"Entraînement de course fractionnée alternant des phases d'effort intense (accélérations, côtes) et des phases de récupération active.","region":"lower_body","setup":[],"muscles":["Mollets","Quadriceps"],"search":["Run - Interval Training","run-interval-training"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"BeLikeWater","translationLicense":"CC-BY-SA-4.0","translationAuthor":"BeLikeWater"},
  {"id":"545","name":"Ciseaux","description":"Les ciseaux sont un exercice abdominal qui renforce le transverse de l'abdomen, ce qui aide à aplatir le ventre et à renforcer toute la sangle abdominale. Les ciseaux ne sont pas seulement un mouvement de renforcement du tronc, c'est aussi un excellent étirement pour vos ischio-jambiers et votre bas du dos. Tout le monde cherche de nouvelles façons de travailler le tronc, d'aplatir le ventre et d'améliorer la souplesse. Si vous apprenez à faire les ciseaux, vous obtiendrez tout cela réuni en un seul mouvement.","region":"core","setup":["Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["Scissors","scissors"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"vkylamba","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"556","name":"Flexion latérale à la machine","description":"Positionné sur la machine, effectuez une flexion latérale du buste en contractant les obliques du côté opposé, puis revenez à la position de départ de manière contrôlée.","region":"core","setup":["Chaise romaine / Banc à lombaires"],"muscles":["Bas du dos","Tronc / Sangle abdominale"],"search":["Roman Chair Side Bends","side-bends-on-machine"],"sourceLicense":"CC-BY-SA-3.0","sourceAuthor":"klabautermann","translationLicense":"CC-BY-SA-3.0","translationAuthor":"klabautermann"},
  {"id":"570","name":"Haussement d'épaules","description":"Debout avec une barre ou des haltères le long du corps, haussez les épaules vers les oreilles en contractant puissamment le haut des trapèzes, puis redescendez avec contrôle.","region":"upper_body","setup":[],"muscles":["Dos"],"search":["Shoulder Shrug","shoulder-shrug"],"sourceLicense":"CC0-1.0","sourceAuthor":"BFad07","translationLicense":"CC0-1.0","translationAuthor":"BFad07"},
  {"id":"580","name":"Planche latérale","description":"Allongez-vous sur le côté, le coude inférieur à angle droit, le bras dépassant\nSoulevez votre bassin du sol en soulevant votre épaule inférieure, en gardant l'avant-bras sur le sol ; votre tête, votre bassin et vos pieds doivent être en ligne droite\nMaintenez cette position","region":"core","setup":["Tapis de sol"],"muscles":["Bas du dos","Tronc / Sangle abdominale"],"search":["Side Plank","side-plank","Planche latérale gauche","Gainage latéral"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"http://www.bodybuilding.com/","translationLicense":"CC-BY-SA-4.0","translationAuthor":"http://www.bodybuilding.com/"},
  {"id":"583","name":"Pompes d'un côté à l'autre","description":"commencez en position de pompe\n\n\ndéplacez le poids du corps vers le côté droit, et effectuez une pompe avec la poitrine au-dessus de la main droite\n\n\nrevenez à la position centrée\n\n\nà la 2e répétition, penchez-vous vers le côté gauche","region":"upper_body","setup":[],"muscles":["Poitrine"],"search":["Side to Side Push Ups","side-to-side-push-ups"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"nate303303","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"591","name":"Relevés de buste avec jambes sur banc","description":"Asseyez-vous sur un tapis, les mollets reposant sur un banc, les genoux formant un angle droit. Tenez vos mains derrière la nuque. Montez maintenant par un mouvement d'enroulement du dos, vous devriez sentir comment les vertèbres se décollent une à une du tapis. Au point le plus haut, contractez vos abdominaux autant que possible et maintenez 2 secondes. Redescendez maintenant en déroulant le dos.","region":"core","setup":["Banc plat","Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["Bench-Elevated Sit-up","sit-ups","Relevés de buste"],"sourceLicense":"CC-BY-SA-3.0","sourceAuthor":"wger.de","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"607","name":"Relevés de buste croisés","description":"Allongez-vous sur le dos, jambes tendues et bras le long du corps, en gardant les coudes pliés à 90 degrés. En vous redressant, faites pivoter le haut du corps vers la droite et amenez votre genou gauche vers votre coude droit pendant que vous ramenez votre bras gauche vers l'arrière. Redescendez votre corps à la position de départ, et répétez vers la droite. Cela fait 1 répétition.","region":"core","setup":["Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["Sprinter Sit-up","splinter-sit-ups","Sprinter Sit-up"],"sourceLicense":"CC-BY-SA-3.0","sourceAuthor":"djblitzd","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"614","name":"Squats sautés (Jump squats)","description":"Effectuez un squat complet puis propulsez-vous dans un saut vertical explosif en amortissant la réception souplement sur l'avant des pieds.","region":"lower_body","setup":[],"muscles":["Fessiers","Quadriceps"],"search":["Squat Jumps","squat-jumps"],"sourceLicense":"CC-BY-SA-3.0","sourceAuthor":"OGhTebfCxhexZXuf35mUxV9C--A","translationLicense":"CC-BY-SA-3.0","translationAuthor":"OGhTebfCxhexZXuf35mUxV9C--A"},
  {"id":"616","name":"Poussées de squat (Squat thrust)","description":"Depuis la position debout, posez les mains au sol, projetez les pieds en arrière en planche, ramenez immédiatement les pieds vers les mains et redressez-vous.","region":"lower_body","setup":[],"muscles":["Fessiers","Quadriceps"],"search":["Squat Thrust","squat-thrust"],"sourceLicense":"CC0-1.0","sourceAuthor":"BFad07","translationLicense":"CC0-1.0","translationAuthor":"BFad07"},
  {"id":"632","name":"Squats sumo","description":"Pieds largement écartés au-delà de la largeur des épaules et pointes ouvertes à 45 degrés, descendez en squat pour cibler l'intérieur des cuisses et les fessiers.","region":"lower_body","setup":[],"muscles":["Adducteurs","Fessiers","Quadriceps"],"search":["Sumo Squats","sumo-squats"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"sophialj","translationLicense":"CC-BY-SA-4.0","translationAuthor":"sophialj"},
  {"id":"636","name":"Superman","description":"Allongez-vous à plat ventre sur le sol, les jambes tendues et les bras tendus devant vous au-dessus de la tête.\nSoulevez simultanément les bras, la poitrine et les cuisses à quelques centimètres du sol en contractant les lombaires et les fessiers.\nMaintenez cette position de contraction pendant 2 à 5 secondes en respirant calmement, puis redescendez lentement avec contrôle.","region":"full_body","setup":["Tapis de sol"],"muscles":["Bas du dos","Fessiers"],"search":["Superman","superman"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"baldurmen","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"688","name":"Gainage pour obliques externes","description":"En position de gainage oblique ou au sol, effectuez une contraction ciblée de la partie supérieure des muscles obliques externes pour verrouiller la sangle abdominale.","region":"core","setup":["Barre de traction"],"muscles":["Tronc / Sangle abdominale"],"search":["Upper External Oblique","upper-external-oblique"],"sourceLicense":"CC-BY-SA-3.0","sourceAuthor":"http://www.carinatum.com/","translationLicense":"CC-BY-SA-3.0","translationAuthor":"http://www.carinatum.com/"},
  {"id":"702","name":"Élévation des mollets sur une jambe","description":"- Placez l'avant d'un pied sur le bord d'une marche ou d'un bloc surélevé, l'autre jambe fléchie sans contact avec le sol.\n- Prenez appui avec une main contre un mur ou une rampe pour stabiliser votre équilibre.\n- Laissez descendre le talon aussi bas que possible pour bien étirer le mollet.\n- Poussez fermement sur l'avant du pied pour hisser le corps au point le plus haut en extension complète.\n- Marquez une pause au sommet, redescendez lentement et répétez avant de changer de jambe.","region":"lower_body","setup":[],"muscles":["Mollets"],"search":["Single-Leg Calf Raise","calf-raises-one-legged","Lever du mollet gauche"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"McMarcel13","translationLicense":"CC-BY-SA-4.0","translationAuthor":"McMarcel13"},
  {"id":"711","name":"Équilibre contre le mur (Handstand)","description":"En équilibre sur les mains face ou dos au mur pour sécuriser l'appui, maintenez l'alignement vertical du corps en repoussant le sol activement avec les épaules.","region":"upper_body","setup":["Mur"],"muscles":["Dos","Épaules"],"search":["Wall Handstand","wall-handstand"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Nash","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Nash"},
  {"id":"713","name":"Pompes contre le mur","description":"Face à un mur, posez les mains à largeur d'épaules, fléchissez les bras pour approcher le torse de la paroi, puis repoussez fermement le mur en maintenant le corps droit.","region":"upper_body","setup":["Mur"],"muscles":["Poitrine"],"search":["Wall Pushup","wall-pushup"],"sourceLicense":"CC-BY-SA-3.0","sourceAuthor":"Dexter","translationLicense":"CC-BY-SA-3.0","translationAuthor":"Dexter"},
  {"id":"716","name":"Glissements muraux (Wall Slides)","description":"- Tenez-vous debout le dos contre un mur, talons, fessiers, haut du dos et arrière de la tête en contact léger avec le mur.\n- Placez vos bras en 'W' avec les coudes pliés à 90 degrés, les coudes et le dos des mains collés au mur.\n- Faites glisser les bras vers le haut le long du mur en forme de 'Y', sans cambrer le bas du dos ni décoller les bras.\n- Redescendez lentement à la position de départ en abaissant activement les omoplates.","region":"upper_body","setup":["Mur"],"muscles":["Dos","Poitrine"],"search":["Wall Slides","wall-slides","Glissements muraux"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Whythebigpaws","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"718","name":"Chaise contre le mur","description":"- Appuyez le dos à plat contre un mur, pieds fermement ancrés au sol à largeur d'épaules et avancés d'environ 60 cm par rapport au mur.\n- Glissez le long du mur jusqu'à ce que vos cuisses soient parallèles au sol (genoux pliés à 90 degrés, directement au-dessus des chevilles).\n- Maintenez cette position isométrique le temps imparti en respirant régulièrement, le dos bien plaqué contre la paroi.","region":"lower_body","setup":["Mur"],"muscles":["Quadriceps"],"search":["Wall Sit","wall-squat","Assis dos au mur"],"sourceLicense":"CC0-1.0","sourceAuthor":"Blablabla","translationLicense":"CC0-1.0","translationAuthor":"Blablabla"},
  {"id":"804","name":"Suspension sur prises fuyantes (Slopers)","description":"Suspension statique bras tendus sur les prises plates et fuyantes (slopers) d'une poutre d'entraînement d'escalade.","region":"upper_body","setup":[],"muscles":["Avant-bras"],"search":["Fingerboard Sloper Hang","sloper-hanging"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"marcelbader","translationLicense":"CC-BY-SA-4.0","translationAuthor":"marcelbader"},
  {"id":"820","name":"Suspension sur réglette de 20 mm (Poutre)","description":"Suspension chronométrée sur une réglette de 20 mm d'une poutre de suspension pour développer la force de préhension des doigts.","region":"upper_body","setup":[],"muscles":["Avant-bras"],"search":["Fingerboard 20 mm Edge Hang","fingerboard-20-mm-edge"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"marcelbader","translationLicense":"CC-BY-SA-4.0","translationAuthor":"marcelbader"},
  {"id":"821","name":"Traction sur poutre d'escalade","description":"Traction des doigts en suspension sur une réglette ou une prise d'une poutre d'escalade, développant la force de préhension et la traction du dos.","region":"upper_body","setup":["Barre de traction"],"muscles":["Avant-bras","Dos"],"search":["Fingerboard Pull-Up","pullup-on-fingerboard"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"marcelbader","translationLicense":"CC-BY-SA-4.0","translationAuthor":"marcelbader"},
  {"id":"908","name":"Course à pied en zone 2","description":"Course d'endurance fondamentale en zone 2, à une allure où vous êtes capable de tenir une conversation continue sans essoufflement marqué.","region":"lower_body","setup":[],"muscles":["Mollets","Quadriceps"],"search":["Zone 2 Running","zone-2-running"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"karly","translationLicense":"CC-BY-SA-4.0","translationAuthor":"karly"},
  {"id":"909","name":"Reverse Nordic curl","description":"À genoux au sol avec le torse et les cuisses alignés, inclinez lentement le buste vers l'arrière à partir des genoux en retenant la descente avec les quadriceps, puis remontez.","region":"lower_body","setup":["Tapis de sol"],"muscles":["Quadriceps"],"search":["Reverse Nordic Curl","reverse-nordic-curl"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"karly","translationLicense":"CC-BY-SA-4.0","translationAuthor":"karly"},
  {"id":"910","name":"Nordic Curl","description":"- Mettez-vous à genoux sur un tapis protecteur avec les chevilles solidement bloquées sous une barre fixe ou tenues par un partenaire.\n- Alignez parfaitement le tronc et les cuisses en gainant les abdominaux et les fessiers.\n- Inclinez le corps vers l'avant le plus lentement possible en retenant la chute exclusivement avec la force des ischio-jambiers.\n- Réceptionnez-vous doucement avec les mains au sol et poussez légèrement pour aider les ischio-jambiers à remonter en position initiale.","region":"lower_body","setup":["Tapis de sol"],"muscles":["Ischio-jambiers"],"search":["Nordic Curl","nordic-curl"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"karly","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"957","name":"Élévation bras et jambe à quatre pattes","description":"Dans cet exercice, les muscles du dos ainsi que les muscles de l'arrière de la jambe et de l'arrière du bras sont activés en levant simultanément le bras et la jambe opposés en position à quatre pattes. Il améliore aussi l'équilibre et la proprioception. Le mouvement s'effectue de façon symétrique.\n\nMettez-vous en position à quatre pattes.\nRentrez le ventre, puis levez votre jambe droite et votre bras gauche.\nVous devez garder le ventre rentré pendant 8 secondes.\nAu bout de 8 secondes, abaissez lentement votre bras et votre jambe.\nPuis relâchez vos muscles.","region":"full_body","setup":["Tapis de sol"],"muscles":["Bas du dos","Fessiers"],"search":["Quadruped Arm and Leg Raise (Bird Dog)","quadriped-arm-and-leg-raise"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"utkb","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"961","name":"Sprints de natation 50 m","description":"Séries de sprints de 50 mètres en natation avec temps de repos chronométré d'une minute entre chaque intervalle.","region":"upper_body","setup":[],"muscles":["Dos","Épaules"],"search":["50m Swim Sprints","swimming-50m-sprints"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"abuono","translationLicense":"CC-BY-SA-4.0","translationAuthor":"abuono"},
  {"id":"978","name":"Relevés de genoux suspendu","description":"Suspendu à la barre de traction, montez les genoux fléchis vers la poitrine en basculant le bassin vers l'avant pour solliciter intensément les abdominaux.","region":"core","setup":["Barre de traction"],"muscles":["Tronc / Sangle abdominale"],"search":["Hanging Knee Raise","knee-raises"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"clafal","translationLicense":"CC-BY-SA-4.0","translationAuthor":"clafal"},
  {"id":"979","name":"Relevés de jambes à la barre de traction","description":"Prise solide sur la barre de traction, montez les jambes tendues à l'horizontale ou plus haut sans balancement parasite en contrôlant la descente.","region":"core","setup":["Barre de traction"],"muscles":["Tronc / Sangle abdominale"],"search":["Hanging Leg Raise","leg-raises-pull-up-bar"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"clafal","translationLicense":"CC-BY-SA-4.0","translationAuthor":"clafal"},
  {"id":"980","name":"Tractions commando","description":"Variante de la traction, elle s'exécute avec une main en supination et une main en pronation. Ne tordez pas le torse pour revenir de face : la tête passe une fois d'un côté, une fois de l'autre.","region":"upper_body","setup":["Barre de traction"],"muscles":["Biceps","Dos"],"search":["Commando Pull-Up","commando-pull-ups"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"clafal","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"981","name":"Marches","description":"Tenez-vous debout face à une chaise\nMontez sur la chaise\nDescendez de la chaise\nRépétez","region":"lower_body","setup":["Chaise / Surface surélevée"],"muscles":["Fessiers","Quadriceps"],"search":["Step-Up","step-ups"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":null},
  {"id":"983","name":"Genoux hauts","description":"Courez sur place, en plaçant les genoux aussi haut que possible et en changeant de jambe à un rythme rapide","region":"full_body","setup":[],"muscles":["Quadriceps","Tronc / Sangle abdominale"],"search":["High Knees","high-knees"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":null},
  {"id":"984","name":"Fentes","description":"Tenez-vous debout, le dos droit\nFaites un grand pas en avant avec votre jambe gauche\nDescendez votre bassin jusqu'à ce que votre genou droit touche presque le sol.\nRemontez votre bassin\nRevenez à la position debout en faisant un pas en arrière\nRépétez l'opération en changeant de jambe à chaque fois","region":"lower_body","setup":[],"muscles":["Fessiers","Quadriceps"],"search":["Bodyweight Lunge","lunges"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":null},
  {"id":"985","name":"Pompes avec rotation","description":"Faites une pompe standard :\n\n1.a Allongez-vous sur le ventre1.b Placez vos mains près de vos oreilles1.c Utilisez vos bras pour soulever votre ventre jusqu'à ce que les bras soient droits, en gardant le dos droit1.d Pliez les bras jusqu'à ce que la poitrine touche presque le sol, en vous assurant que le dos est droit1.e Soulevez à nouveau votre ventre et revenez à l'étape 1.c\n\nFaites pivoter votre corps sur le côté pour que le dos soit droit, que la main inférieure soutenant le corps soit complètement étendue et que seuls la main et le pied inférieurs touchent le sol\nRépétez, en changeant de côté à chaque fois","region":"upper_body","setup":[],"muscles":["Poitrine"],"search":["Push-up with Rotation","push-up-rotations"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":null},
  {"id":"986","name":"Fentes latérales gauches","description":"Tenez-vous droit et faites une large foulée latérale, juste supérieure à la largeur des épaules\nPliez un genou jusqu'à ce que votre cuisse soit parallèle au sol. Le genou plié doit être aligné avec le pied\nRevenez à la position de départ et répétez.","region":"lower_body","setup":[],"muscles":["Fessiers","Quadriceps"],"search":["Side Lunge (Left)","side-split-squats-left"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":null},
  {"id":"987","name":"Fentes latérales droites","description":"Tenez-vous droit et faites une large foulée latérale, juste supérieure à la largeur des épaules\nPliez un genou jusqu'à ce que votre cuisse soit parallèle au sol. Le genou plié doit être aligné avec le pied\nRevenez à la position de départ et répétez.","region":"lower_body","setup":[],"muscles":["Fessiers","Quadriceps"],"search":["Side Lunge (Right)","side-split-squats-right"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":null},
  {"id":"988","name":"Squats bulgares gauches","description":"Tenez-vous droit devant une chaise et faites un grand pas. Placez la partie supérieure de l'un de vos pieds sur la chaise\nPliez le genou avant, en équilibre avec les bras jusqu'à ce que le genou arrière touche presque le sol\nRevenez à la position de départ et répétez.","region":"lower_body","setup":["Chaise / Surface surélevée"],"muscles":["Fessiers","Quadriceps"],"search":["Bulgarian Split Squat (Left)","bulgarian-split-squats-left"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":null},
  {"id":"989","name":"Squats bulgares droites","description":"Tenez-vous droit devant une chaise et faites un grand pas. Placez la partie supérieure de l'un de vos pieds sur la chaise\nPliez le genou avant, en équilibre avec les bras jusqu'à ce que le genou arrière touche presque le sol\nRevenez à la position de départ et répétez.","region":"lower_body","setup":["Chaise / Surface surélevée"],"muscles":["Fessiers","Quadriceps"],"search":["Bulgarian Split Squat (Right)","bulgarian-split-squats-right"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":null},
  {"id":"990","name":"Extensions de la hanche","description":"Mettez-vous à quatre pattes\nPoussez un pied en arrière jusqu'à ce qu'il soit complètement étendu, en vous concentrant sur les muscles fessiers\nRestez une seconde, puis revenez à la position initiale\nRépétez, en alternant les pieds","region":"lower_body","setup":["Tapis de sol"],"muscles":["Fessiers"],"search":["Kneeling Glute Kickback","kneeling-kickbacks"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":null},
  {"id":"991","name":"Fentes avant gauches","description":"Tenez-vous debout avec le dos droit\nFaites un grand pas en avant avec votre jambe gauche\nAbaissez votre bassin jusqu'à ce que vous touchiez presque le sol avec votre genou droit\nRamenez votre bassin vers le haut\nRépétez à partir de l'étape 3.","region":"lower_body","setup":[],"muscles":["Fessiers","Quadriceps"],"search":["Split Squat (Left)","split-squats-left"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":null},
  {"id":"992","name":"Fentes avant droites","description":"Tenez-vous debout avec le dos droit\nFaites un grand pas en avant avec votre jambe droite\nAbaissez votre bassin jusqu'à ce que vous touchiez presque le sol avec votre genou gauche\nRamenez votre bassin vers le haut\nRépétez à partir de l'étape 3.","region":"lower_body","setup":[],"muscles":["Fessiers","Quadriceps"],"search":["Split Squat (Right)","split-squats-right"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":null},
  {"id":"994","name":"Cercles avant des bras","description":"Tenez-vous debout, le dos bien droit.\nGardez vos bras droits, amenez les devant vous, puis vers le bas, puis derrière votre dos, puis au dessus de votre tête, puis ramenez les en position initiale, devant vous.\nContinuez à faire des cercles avec vos bras comme décrit à l'étape 2.","region":"upper_body","setup":[],"muscles":["Épaules"],"search":["Forward Arm Circles","forward-arm-circles"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":null},
  {"id":"995","name":"Cercle arrière des bras","description":"Tenez-vous debout, le dos droit.\nGardez vos bras tendus, amenez-les devant vous, levez-les au-dessus de votre tête, puis continuez le mouvement derrière votre dos jusqu'à revenir en position initiale.\nContinuez à faire des cercles comme décrit à l'étape 2.","region":"upper_body","setup":[],"muscles":["Épaules"],"search":["Backward Arm Circles","backward-arm-circles"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":null},
  {"id":"996","name":"Escaladeurs de montagne","description":"Position de départ :\nCommencez par la position debout des pompes ou de la planche haute.Les mains doivent se trouver directement sous vos épaules.Gardez la tête dans le prolongement du dos, face au sol.Les pieds doivent être écartés d'environ la largeur des hanches.\nÉtapes :\n\nDéplacez un genou vers le centre de votre corps, vers vos coudes, en gardant l'autre jambe tendue.\nDans un mouvement de saut rapide, redressez la jambe pliée et tirez l'autre genou vers votre corps.\nRépétez l'étape 2 en alternant les jambes.\n\nRemarques :\nTout au long de l'exercice, votre dos doit rester aussi droit que possible – évitez d'avoir une bosse ou un dos affaissé.","region":"core","setup":["Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["Mountain Climbers","mountain-climbers"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":null},
  {"id":"997","name":"Burpees (4 phases)","description":"Position de départ :\nTenez-vous droit, les pieds écartés de la largeur des hanches.\nÉtapes :\n\nAccroupissez-vous et prenez appui sur le sol avec les mains entre les genoux et devant les pieds, le dos droit.\nEn gardant les mains sur le sol, sautez vos jambes vers l'arrière en position de planche haute.\nSautez vers l'avant pour revenir à la position de squat.\nRépétez l'exercice.","region":"full_body","setup":[],"muscles":["Quadriceps","Tronc / Sangle abdominale"],"search":["4-Count Burpees","4-count-burpees"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":null},
  {"id":"998","name":"Burpees sans saut","description":"Position de départ :\nSe tenir droit, les pieds écartés de la largeur des hanches.\nÉtapes:\n\nAccroupissez-vous et appuyez-vous sur le sol avec vos mains entre les genoux et devant vos pieds, le dos droit.\nEn gardant les mains au sol, donnez une impulsion pour envoyer vos jambes vers l'arrière en position de planche haute.\nDonnez une nouvelle impulsion pour revenir à la position accroupie.\nSautez.\nRépétez.","region":"lower_body","setup":[],"muscles":["Mollets","Quadriceps"],"search":["No-Push-Up Burpees","no-push-up-burpees"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":null},
  {"id":"999","name":"Fentes arrière","description":"Position de départ :\nTenez-vous droit, les pieds écartés à la largeur des hanches.\nÉtapes :\n\nFaites un pas en arrière avec une jambe afin qu'elle puisse se fléchir confortablement à un angle de 90 degrés.\nFléchissez lentement les deux genoux pour former des angles de 90 degrés.\nRevenez à la position de départ.\nRépétez en alternant les jambes.","region":"lower_body","setup":[],"muscles":["Fessiers","Quadriceps"],"search":["Reverse Lunge","reverse-lunges"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1000","name":"Dips au sol","description":"Position de départ :\nAsseyez-vous, les bras derrière vous pour soutenir le dos. Vos doigts doivent pointer vers l'avant. Vos genoux doivent être fléchis, les pieds joints.\nÉtapes :\n\nSoulevez les hanches du sol en tendant les bras.\nFléchissez les coudes en abaissant les hanches.\nTendez les bras pour revenir à la position précédente.\nRépétez les étapes 2 et 3.\n\nNotes :\nLa difficulté de l'exercice dépend de la hauteur à laquelle vous montez les hanches.","region":"upper_body","setup":[],"muscles":["Triceps"],"search":["Floor Dips","floor-dips"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1001","name":"Planche haute","description":"Position de départ :\nPlacez-vous en position de planche haute : les mains au sol directement sous les épaules et les orteils en appui. Les pieds sont joints et les bras tendus.\n\nÉtapes :\n1. Maintenez le corps parfaitement aligné de la tête aux talons en contractant les abdominaux et les fessiers.\n2. Respirez régulièrement sans laisser le bassin s'affaisser ni monter.\n3. Conservez la position pendant la durée prévue.","region":"core","setup":["Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["High Plank","high-plank"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":null},
  {"id":"1002","name":"Position de l'enfant (Child's pose)","description":"À genoux sur les talons, penchez le torse vers l'avant jusqu'à poser le front au sol et étirez les bras loin devant vous pour allonger le dos et relâcher les tensions.","region":"full_body","setup":["Tapis de sol"],"muscles":["Bas du dos","Dos"],"search":["Child's Pose","child-s-pose"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":null},
  {"id":"1004","name":"Rotation de l'épaule vers l'avant","description":"Debout le dos droit, effectuez des cercles amples et réguliers avec les épaules vers l'avant pour mobiliser l'articulation gléno-humérale.","region":"upper_body","setup":[],"muscles":["Épaules"],"search":["Forward Shoulder Rotation","forward-shoulder-rotation"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":null},
  {"id":"1005","name":"Rotation de l'épaule vers l'arrière","description":"Debout le dos droit, effectuez des cercles amples et réguliers avec les épaules vers l'arrière en ouvrant la cage thoracique et en serrant les omoplates.","region":"upper_body","setup":[],"muscles":["Épaules"],"search":["Backward Shoulder Rotation","backward-shoulder-rotation"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":null},
  {"id":"1006","name":"Rentré de menton","description":"Position de départ :\nAsseyez-vous ou tenez-vous debout, le dos droit.\nÉtapes :\n\nÀ l'aide des doigts posés sur le menton, rentrez lentement le menton en ramenant la tête vers l'arrière pour l'aligner avec la colonne vertébrale.\nMaintenez pendant 5 secondes.\nRevenez à la position normale de la tête et répétez.","region":"upper_body","setup":[],"muscles":["Cou"],"search":["Chin Tuck","chin-tuck"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1007","name":"Tour de tête","description":"Position de départ :\nAsseyez-vous ou tenez-vous debout, le dos droit et les épaules basses.\nÉtapes :\n\nAsseyez-vous ou tenez-vous debout, le dos droit. Épaules baissées.\nTournez la tête vers la gauche aussi loin que possible. Arrêtez-vous lorsque vous rencontrez un obstacle et maintenez cette position pendant 5 secondes.\nRevenez à la position centrale.\nRépétez en changeant de côté.","region":"upper_body","setup":[],"muscles":["Cou"],"search":["Head Turns","head-turns"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":null},
  {"id":"1008","name":"Étirement du cou à gauche","description":"Position de départ :\nAssis ou debout, le dos bien droit.\n\nÉtapes :\n1. Inclinez lentement la tête vers la gauche en rapprochant l'oreille gauche de l'épaule gauche.\n2. Vous pouvez poser délicatement la main gauche sur la tête pour accentuer légèrement l'étirement sans tirer.\n3. Maintenez la position quelques secondes en respirant profondément.","region":"upper_body","setup":[],"muscles":["Cou"],"search":["Neck Stretch (Left)","left-neck-stretch"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":null},
  {"id":"1009","name":"Étirement du cou à droite","description":"Position de départ :\nAssis ou debout, le dos bien droit.\n\nÉtapes :\n1. Inclinez lentement la tête vers la droite en rapprochant l'oreille droite de l'épaule droite.\n2. Vous pouvez poser délicatement la main droite sur la tête pour accentuer légèrement l'étirement sans tirer.\n3. Maintenez la position quelques secondes en respirant profondément.","region":"upper_body","setup":[],"muscles":["Cou"],"search":["Neck Stretch (Right)","right-neck-stretch"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":null},
  {"id":"1010","name":"Flexion du cou","description":"Position de départ :\nAsseyez-vous bien droit sur une chaise ou au sol.\n\nÉtapes :\n1. Placez délicatement les mains derrière la tête.\n2. Inclinez lentement la tête vers l'avant, le menton vers la poitrine, en exerçant une légère pression avec les mains.\n3. Maintenez l'étirement à l'arrière du cou pendant plusieurs secondes sans forcer.","region":"upper_body","setup":[],"muscles":["Cou","Dos"],"search":["Back Neck Stretch","back-neck-stretch"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":null},
  {"id":"1011","name":"Étirement du cou en avant","description":"Assis ou debout le dos droit, inclinez doucement la tête vers l'arrière pour étirer la face antérieure du cou et de la gorge, sans forcer sur les cervicales.","region":"upper_body","setup":[],"muscles":["Cou"],"search":["Front Neck Stretch","front-neck-stretch"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":null},
  {"id":"1013","name":"Étirement de l'élévateur de la scapula gauche","description":"Position de départ :\nAsseyez-vous ou tenez-vous debout le dos droit. Tournez la tête d'environ 45 degrés vers la gauche. Placez la main droite dans le bas du dos ou sous la cuisse pour abaisser l'épaule droite. Posez la main gauche sur l'arrière de la tête.\n\nÉtapes :\n1. Inclinez doucement le menton vers le bas en direction de l'aisselle gauche jusqu'à ressentir un étirement confortable à l'arrière du cou et vers l'omoplate.\n2. Maintenez une légère traction avec la main gauche sans forcer.\n3. Conservez la posture pendant 20 à 30 secondes en respirant calmement, puis relâchez lentement.","region":"upper_body","setup":[],"muscles":["Cou","Dos"],"search":["Left Levator Scapulae Stretch","left-levator-scapulae-stretch","Étirement de l'angulaire de l'omoplate gauche"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1014","name":"Étirement de l'élévateur de la scapula droit","description":"Position de départ :\nAsseyez-vous ou tenez-vous debout le dos droit. Tournez la tête d'environ 45 degrés vers la droite. Placez la main gauche dans le bas du dos ou sous la cuisse pour abaisser l'épaule gauche. Posez la main droite sur l'arrière de la tête.\n\nÉtapes :\n1. Inclinez doucement le menton vers le bas en direction de l'aisselle droite jusqu'à ressentir un étirement confortable à l'arrière du cou et vers l'omoplate.\n2. Maintenez une légère traction avec la main droite sans forcer.\n3. Conservez la posture pendant 20 à 30 secondes en respirant calmement, puis relâchez lentement.","region":"upper_body","setup":[],"muscles":["Cou","Dos"],"search":["Right Levator Scapulae Stretch","right-levator-scapulae-stretch","Étirement de l'angulaire de l'omoplate droit"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1015","name":"Cercles du cou dans le sens horaire","description":"Position de départ :\nAsseyez-vous ou tenez-vous debout avec le dos bien droit et les épaules relâchées vers le bas. Abaissez doucement le menton vers la poitrine.\n\nÉtapes :\n1. Décrivez un cercle lent et fluide dans le sens des aiguilles d'une montre : inclinez la tête vers l'épaule droite, passez doucement vers l'arrière, inclinez vers l'épaule gauche et revenez au centre.\n2. Ne forcez pas sur la nuque lors du passage vers l'arrière et gardez une respiration régulière.\n3. Répétez le mouvement pour le nombre de répétitions souhaité.","region":"upper_body","setup":[],"muscles":["Cou"],"search":["Clockwise Neck Circles","clockwise-neck-circles"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1016","name":"Cercles du cou dans le sens antihoraire","description":"Position de départ :\nAsseyez-vous ou tenez-vous debout le dos droit, les épaules détendues. Amenez le menton doucement vers la poitrine.\n\nÉtapes :\n1. Décrivez un cercle lent et régulier dans le sens antihoraire : inclinez la tête vers l'épaule gauche, passez avec précaution vers l'arrière, inclinez vers l'épaule droite et ramenez au menton.\n2. Gardez les muscles détendus et respirez naturellement.\n3. Répétez le mouvement pour le nombre de répétitions prévu.","region":"upper_body","setup":[],"muscles":["Cou"],"search":["Counterclockwise Neck Circles","counterclockwise-neck-circles"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1017","name":"Demi-cercles du cou","description":"Position de départ :\nAsseyez-vous ou tenez-vous debout le dos droit, épaules basses et relâchées. Inclinez délicatement la tête vers une épaule.\n\nÉtapes :\n1. Faites rouler doucement la tête vers l'avant, le menton descendant vers la poitrine pour décrire un demi-cercle jusqu'à l'épaule opposée.\n2. Inversez le mouvement en faisant repasser le menton devant le buste pour revenir au côté initial.\n3. Répétez ce mouvement de balancier fluide sans jamais rejeter la tête en arrière.","region":"upper_body","setup":[],"muscles":["Cou"],"search":["Neck Half Circles","neck-half-circles"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1018","name":"Inclinaisons latérales de la tête","description":"Position de départ :\nAsseyez-vous ou tenez-vous debout le dos droit, les épaules basses et détendues.\n\nÉtapes :\n1. Inclinez lentement la tête sur le côté en rapprochant l'oreille de l'épaule, jusqu'à sentir un étirement modéré sur le côté opposé du cou.\n2. Maintenez la position pendant 15 à 30 secondes sans hausser les épaules.\n3. Revenez doucement au centre, puis répétez de l'autre côté.","region":"upper_body","setup":[],"muscles":["Cou"],"search":["Head Tilts (Lateral Neck Stretch)","head-tilts","Inclinaisons de la tête"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1019","name":"Planche latérale droite","description":"Position de départ :\nAllongez-vous sur le côté droit, jambes tendues et pieds superposés ou décalés. Placez votre coude droit directement sous l'épaule droite, l'avant-bras posé à plat sur le sol.\n\nÉtapes :\n1. Décollez le bassin du sol en contractant les abdominaux, les obliques et les fessiers, jusqu'à ce que votre corps forme une ligne droite de la tête aux pieds.\n2. Gardez la nuque dans l'alignement de la colonne et le regard vers l'avant.\n3. Maintenez cette position de gainage pendant la durée prévue sans laisser les hanches s'affaisser.","region":"core","setup":["Tapis de sol"],"muscles":["Bas du dos","Tronc / Sangle abdominale"],"search":["Side Plank Right","side-plank-right"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":null},
  {"id":"1020","name":"Pistol squat jambe droite","description":"Position de départ :\nTenez-vous en équilibre sur la jambe droite, la jambe gauche tendue vers l'avant au-dessus du sol. Tendez les bras devant vous pour équilibrer le corps.\n\nÉtapes :\n1. Fléchissez lentement le genou et la hanche droite pour descendre en squat complet sur une jambe.\n2. Gardez le buste fier, le dos droit et la jambe gauche tendue sans toucher le sol.\n3. Descendez de manière contrôlée aussi bas que votre mobilité le permet.\n4. Poussez fermement sur le talon droit pour remonter en position debout.","region":"lower_body","setup":[],"muscles":["Fessiers","Quadriceps"],"search":["Pistol Squats Right","pistol-squats-right","Pistol squats droites"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":null},
  {"id":"1021","name":"Élévation du mollet droit (sur une jambe)","description":"Position de départ :\nTenez-vous debout sur le pied droit, sur le sol ou sur le bord d'une marche pour augmenter l'amplitude. Le pied gauche est légèrement décollé du sol. Prenez un appui léger avec une main sur un mur pour garder l'équilibre.\n\nÉtapes :\n1. Descendez le talon droit vers le bas pour ressentir un étirement complet du mollet.\n2. Poussez puissamment sur la pointe du pied droit pour monter le plus haut possible.\n3. Marquez une pause d'une seconde en haut de la contraction.\n4. Redescendez lentement de manière contrôlée.","region":"lower_body","setup":[],"muscles":["Mollets"],"search":["Right-Leg Calf Raise","calf-raises-right-leg","Lever du mollet droit"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":null},
  {"id":"1027","name":"Étirement de la prière sur banc surélevé","description":"Position de départ :\nMettez-vous à genoux devant un banc plat ou une surface surélevée. Posez les deux coudes sur le bord du banc écartés de la largeur des épaules et joignez les paumes de mains en position de prière.\n\nÉtapes :\n1. Reculez le bassin vers les talons et laissez la poitrine descendre vers le sol, la tête passant entre les bras.\n2. Fléchissez les coudes pour amener les mains jointes vers la nuque.\n3. Maintenez l'étirement ressenti dans les grands dorsaux, les triceps et la cage thoracique pendant 20 à 40 secondes en respirant profondément.\n4. Relâchez doucement la posture.","region":"upper_body","setup":["Banc plat","Tapis de sol"],"muscles":["Dos"],"search":["Elevated Prayer Stretch","elevated-prayer-stretch","Étirement de la prière surélevé"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"tinman","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1028","name":"Rotation thoracique à quatre pattes à gauche","description":"Position de départ :\nMettez-vous à quatre pattes, les mains sous les épaules et les genoux sous les hanches. Main droite fermement appuyée au sol, placez la main gauche derrière la nuque, coude ouvert sur le côté.\n\nÉtapes :\n1. À l'inspiration, tournez le haut du buste vers le bas en amenant le coude gauche vers le bras d'appui droit.\n2. À l'expiration, ouvrez la poitrine vers la gauche en dirigeant le coude gauche vers le haut en direction du plafond.\n3. Gardez le bassin stable et horizontal sans déhancher.\n4. Répétez le mouvement avec fluidité et contrôle.","region":"full_body","setup":["Tapis de sol"],"muscles":["Dos","Tronc / Sangle abdominale"],"search":["Quadruped Thoracic Rotation Left","quadruped-thoracic-rotation-left"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"tinman","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1029","name":"Rotation thoracique à quatre pattes à droite","description":"Position de départ :\nMettez-vous à quatre pattes, genoux sous les hanches et main gauche en appui au sol sous l'épaule gauche. Placez la main droite derrière la tête, coude ouvert.\n\nÉtapes :\n1. À l'inspiration, amenez le coude droit vers le bras gauche en enroulant légèrement le torse.\n2. À l'expiration, pivotez le haut du corps vers la droite en pointant le coude droit vers le haut.\n3. Maintenez le bassin fixe et les hanches au même niveau.\n4. Répétez le mouvement pour le nombre de répétitions indiqué.","region":"full_body","setup":["Tapis de sol"],"muscles":["Dos","Tronc / Sangle abdominale"],"search":["Quadruped Thoracic Rotation Right","quadruped-thoracic-rotation-right","Rotation thoracique à quatre pattes, côté droit"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"tinman","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1080","name":"Pompes hindoues","description":"Position de départ :\nCommencez en position de 'V' inversé (chien tête en bas), fesses levées vers le haut, mains légèrement plus larges que les épaules et pieds écartés de la largeur des hanches.\n\nÉtapes :\n1. Fléchissez les coudes et plongez vers l'avant en rasant le sol avec le visage et la poitrine dans un mouvement d'arc circulaire.\n2. Repoussez le sol avec les bras pour redresser le buste en posture de cobra / chien tête en haut, la poitrine fière.\n3. Renvoyez les hanches vers l'arrière et vers le haut pour retrouver la position de départ en V inversé.\n4. Répétez ce cycle de manière fluide et rythmée.","region":"upper_body","setup":["Tapis de sol"],"muscles":["Poitrine","Épaules"],"search":["Hindu Push-Ups","hindu-pushups"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Imobard","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1082","name":"Rowing penché avec rotation externe","description":"Position de départ :\nPenchez le buste vers l'avant à partir des hanches en gardant le dos bien plat et les genoux légèrement fléchis. Laissez pendre vos bras verticalement vers le sol.\n\nÉtapes :\n1. Tirez les coudes vers le haut jusqu'à hauteur d'épaules, les avant-bras restant orientés vers le sol à angle droit.\n2. En maintenant les coudes stables à hauteur d'épaules, pivotez les avant-bras vers le haut en rotation externe jusqu'à ce que les mains soient au niveau de la tête.\n3. Marquez une brève pause pour contracter la coiffe des rotateurs et les deltoïdes postérieurs.\n4. Contrôlez la descente des avant-bras puis tendez à nouveau les bras vers le bas.","region":"upper_body","setup":["Chaise / Surface surélevée"],"muscles":["Dos","Épaules"],"search":["Bent-Over Row to External Rotation","bent-over-row-to-external-rotation","Rowing penché vers rotation externe"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"tinman","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1083","name":"Élévations au sol en Y-W-T","description":"Position de départ :\nAllongez-vous à plat ventre sur un tapis, la nuque alignée avec la colonne et le regard vers le sol.\n\nÉtapes :\n1. Position Y : Tendez les bras vers l'avant à 45 degrés pour former un 'Y', pouces vers le plafond. Décollez la poitrine et les bras du sol en resserrant les omoplates pendant 10 à 20 secondes.\n2. Position W : Tirez les coudes vers le bas et les côtes pour former un 'W', en maintenant les bras surélevés et le haut du dos contracté.\n3. Position T : Ouvrez les bras tendus sur les côtés perpendiculairement au tronc pour former un 'T', pouces vers le haut, en pinçant fortement les omoplates.\n4. Enchaînez les positions avec contrôle pour renforcer les fixateurs d'omoplates.","region":"upper_body","setup":["Tapis de sol"],"muscles":["Dos"],"search":["Prone Y-W-T Raises","ywts","YWT"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"tinman","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1086","name":"Pompes en prise serrée","description":"Position de départ :\nInstallez-vous en position de planche haute avec les mains rapprochées sous la poitrine (largeur inférieure à celle des épaules). Le corps est parfaitement aligné de la tête aux talons.\n\nÉtapes :\n1. Fléchissez les coudes en les gardant collés le long des côtes et descendez le corps de manière contrôlée.\n2. Descendez jusqu'à ce que la poitrine frôle les mains.\n3. Repoussez le sol avec force en engageant principalement les triceps pour remonter en position initiale.\n4. Conservez un gainage ferme sans cambrer le dos.","region":"upper_body","setup":[],"muscles":["Poitrine","Triceps"],"search":["Close-Grip Push-Ups","close-grip-press-ups","Pompes prise serrée"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"philip","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1090","name":"Pompes en V (V-Push-ups)","description":"Pompes avec le bassin surélevé en V inversé, focalisant la poussée sur les deltoïdes antérieurs et le haut de la poitrine.","region":"upper_body","setup":["Tapis de sol"],"muscles":["Triceps","Épaules"],"search":["Pike Push-Up (V-Push-Up)","vpushup"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"clafal","translationLicense":"CC-BY-SA-4.0","translationAuthor":"clafal"},
  {"id":"1091","name":"Touchers d'épaules en planche (Shoulder Taps)","description":"Position de départ :\nPlacez-vous en position de planche haute, mains sous les épaules et pieds écartés un peu plus largement que les hanches pour assurer une base stable.\n\nÉtapes :\n1. Verrouillez la sangle abdominale et les fessiers pour empêcher le bassin de basculer ou d'osciller.\n2. Décollez la main droite et venez toucher doucement l'épaule gauche.\n3. Reposez la main droite au sol puis touchez l'épaule droite avec la main gauche.\n4. Enchaînez les répétitions en alternant les côtés de manière fluide et contrôlée.","region":"core","setup":["Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["Plank Shoulder Taps","plank-shoulder-taps","Touchers d'épaules en planche"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"clafal","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1096","name":"Abduction de hanche debout","description":"Position de départ :\nTenez-vous debout le dos droit, une main posée sur un mur ou un support pour l'équilibre. Prenez appui fermement sur la jambe de soutien en gardant le bassin de niveau.\n\nÉtapes :\n1. Décollez la jambe active et levez-la latéralement vers l'extérieur de manière contrôlée sans pencher le buste.\n2. Gardez la pointe de pied orientée vers l'avant pour solliciter le moyen fessier.\n3. Marquez une brève pause au sommet du mouvement en serrant la partie externe de la hanche.\n4. Redescendez la jambe lentement sans reposer complètement le pied au sol.\n5. Répétez le mouvement puis changez de côté.","region":"lower_body","setup":[],"muscles":["Fessiers"],"search":["Standing Hip Abduction","abduction-while-standing","Abduction debout"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"tregga","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1101","name":"Traction isométrique (maintien statique)","description":"Position de départ :\nSaisissez une barre de traction (en pronation ou supination) ou les poignées d'un système de suspension.\n\nÉtapes :\n1. Tirez le corps vers le haut jusqu'à la position haute (menton au-dessus de la barre ou poitrine aux poignées).\n2. Bloquez la position en contraction statique en resserrant les omoplates vers le bas et l'arrière.\n3. Gardez la cage thoracique ouverte et les dorsaux engagés sans laisser les épaules remonter vers les oreilles.\n4. Maintenez ce blocage isométrique pendant la durée cible (10 à 30 secondes) en respirant régulièrement.","region":"upper_body","setup":["Barre de traction"],"muscles":["Biceps","Dos"],"search":["Isometric Pull-Up / Row Hold","horizontal-traction-isometry","Traction horizontale isométrique"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"clafal","translationLicense":"CC-BY-SA-4.0","translationAuthor":"clafal"},
  {"id":"1102","name":"Fentes arrière alternées","description":"Debout, reculez un pied vers l'arrière et fléchissez les genoux pour descendre en fente, puis repoussez sur le pied avant pour revenir en position de départ et alternez.","region":"lower_body","setup":[],"muscles":["Fessiers","Quadriceps"],"search":["Alternating Reverse Lunges","alternate-back-lunges"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"clafal","translationLicense":"CC-BY-SA-4.0","translationAuthor":"clafal"},
  {"id":"1103","name":"Walkout avec les mains (Walking Bridge)","description":"Position de départ :\nTenez-vous debout, pieds écartés de la largeur des hanches. Fléchissez légèrement les genoux et penchez-vous vers l'avant pour poser les mains au sol devant les pieds.\n\nÉtapes :\n1. Avancez pas à pas avec les mains sur le sol tout en verrouillant fermement les abdominaux et les fessiers.\n2. Poursuivez l'avancée des mains jusqu'à vous retrouver en planche allongée sans cambrer le bas du dos.\n3. Marquez un temps d'arrêt en gainage maximal.\n4. Revenez en marchant avec les mains vers l'arrière jusqu'aux pieds pour vous redresser.","region":"core","setup":["Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["Walking Bridge","walking-bridge","Pont en marche"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"clafal","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1104","name":"Marche à pied","description":"Marche active en intérieur ou en extérieur, en visant une cadence d'au moins 100 pas par minute avec les bras actifs.","region":"lower_body","setup":[],"muscles":["Mollets","Quadriceps"],"search":["Walking","walking"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":null},
  {"id":"1105","name":"Regroupement de genoux assis (Seated knee tuck)","description":"Assis au sol, mains posées en arrière pour l'équilibre, ramenez les genoux vers la poitrine tout en rapprochant légèrement le buste, puis étendez les jambes sans toucher le sol.","region":"core","setup":["Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["Seated Knee Tuck","seated-knee-tuck"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"utkb","translationLicense":"CC-BY-SA-4.0","translationAuthor":"utkb"},
  {"id":"1111","name":"Pompes inclinées avec mains surélevées","description":"Position de départ :\nPlacez les mains un peu plus larges que les épaules sur un banc, une marche ou une surface stable surélevée. Reculez les pieds de façon à ce que le corps forme une ligne droite des talons à la tête.\n\nÉtapes :\n1. Fléchissez les coudes et descendez la poitrine de manière contrôlée vers le bord de la surface surélevée.\n2. Descendez jusqu'à ce que la poitrine frôle le support en gardant les coudes orientés à 45 degrés du buste.\n3. Repoussez fermement à l'aide des pectoraux et des triceps pour revenir en position haute.\n4. Conservez un gainage abdominal solide tout au long de la répétition.","region":"upper_body","setup":["Banc plat"],"muscles":["Poitrine"],"search":["Incline Push-Ups","push-ups-incline","Pompes | Inclinées"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"anon1337","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1112","name":"Pompes déclinées avec pieds surélevés","description":"Position de départ :\nPosez les pieds sur un banc ou une boîte solide et placez les mains au sol à la largeur des épaules. Le corps forme une ligne droite inclinée de la tête aux talons.\n\nÉtapes :\n1. Fléchissez les coudes et descendez le torse de manière contrôlée vers le sol.\n2. Gardez la sangle abdominale fermement gainée pour empêcher le bassin de s'affaisser.\n3. Descendez jusqu'à ce que le haut de la poitrine frôle le sol.\n4. Repoussez puissamment avec les pectoraux et les triceps pour remonter en position haute.\n5. Cette variante cible préférentiellement le faisceau claviculaire (haut des pectoraux).","region":"upper_body","setup":["Banc plat"],"muscles":["Poitrine"],"search":["Decline Push-Ups","push-ups-decline","Pompes déclinées"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"anon1337","translationLicense":"CC-BY-SA-4.0","translationAuthor":"AlucardEvil40"},
  {"id":"1113","name":"Pompes sur parallettes","description":"Position de départ :\nDisposez deux barres parallettes parallèles au sol à la largeur des épaules. Saisissez fermement les barres en prise neutre (paumes face à face) et tendez les jambes en arrière en position de planche.\n\nÉtapes :\n1. Fléchissez les coudes et descendez profondément la poitrine entre les barres de manière contrôlée.\n2. Profitez du déficit pour obtenir un étirement optimal des pectoraux en bas du mouvement.\n3. Repoussez avec puissance pour revenir en position initiale bras tendus.\n4. La prise neutre soulage les poignets tout en accentuant le travail musculaire.","region":"upper_body","setup":["Parallettes"],"muscles":["Poitrine"],"search":["Parallette Push-Ups","push-ups-parallettes","Pompes | Parallettes"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"anon1337","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1132","name":"Extension des fessiers au GHD","description":"Position de départ :\n• Installez-vous à plat ventre sur le banc GHD (ou banc à lombaires), les chevilles fermement calées sous les rouleaux.\n• Positionnez le bassin juste au bord du coussin pour permettre une libre flexion des hanches.\n• Croisez les bras sur la poitrine ou placez les mains derrière la tête.\n\nExécution :\n• Penchez le buste vers le bas en fléchissant au niveau des hanches tout en gardant le dos droit.\n• Contractez puissamment les fessiers et les ischio-jambiers pour redresser le buste jusqu'à l'alignement avec les cuisses.\n• Marquez un temps d'arrêt en serrant les fessiers, puis redescendez de manière contrôlée.","region":"lower_body","setup":["Chaise romaine / Banc à lombaires"],"muscles":["Fessiers","Ischio-jambiers"],"search":["GHD Glute Extension","machine-glute-extension","Extension des fessiers à la machine","Extension de hanche au banc à lombaires"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Franpol","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1141","name":"Arabesque","description":"Position de départ :\n• Tenez-vous debout et reportez tout votre poids sur une jambe d'appui.\n• Gardez le genou de la jambe d'appui très légèrement déverrouillé et le bassin bien aligné à l'horizontale.\n• Maintenez la colonne vertébrale neutre et gainez la sangle abdominale.\n\nExécution :\n• Basculez le buste vers l'avant à partir des hanches tout en tendant l'autre jambe vers l'arrière et le haut.\n• Alignez le buste et la jambe levée parallèlement au sol en conservant l'équilibre.\n• Contractez fermement les fessiers et les ischio-jambiers de la jambe d'appui pour revenir lentement debout.","region":"lower_body","setup":[],"muscles":["Fessiers","Ischio-jambiers"],"search":["Arabesque","arabesque"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"cleen","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1195","name":"Pas chassés latéraux avec squats","description":"Position de départ :\n• Tenez-vous debout en position athlétique basse, pieds légèrement plus larges que les épaules.\n• Fléchissez les genoux et gardez le centre de gravité bas.\n\nExécution :\n• Effectuez trois pas chassés latéraux rapides et contrôlés vers un côté en poussant avec la jambe d'appui.\n• Bloquez la position et réalisez un squat complet en gardant le dos droit.\n• Pivotez à 180 degrés ou changez immédiatement de direction pour répéter l'exercice de l'autre côté.","region":"lower_body","setup":[],"muscles":["Fessiers","Quadriceps"],"search":["Side Slides to Squats","side-slides-squats","Pas chassés + squats"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Insight","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1196","name":"Exercices au mur (Wall Drills)","description":"Position de départ :\n• Placez-vous debout face à un mur solide à environ un grand pas de distance.\n• Posez les mains à plat sur le mur à hauteur d'épaules et inclinez votre corps vers l'avant à un angle d'environ 45 degrés.\n• Gardez le corps parfaitement aligné de la tête aux talons avec un gainage abdominal maximal.\n\nExécution :\n• Montez explosivement un genou vers la poitrine jusqu'à ce que la cuisse soit parallèle au sol, orteils relevés vers le haut.\n• Maintenez la position ou alternez rapidement les montées de genoux sur un rythme de marche ou de course athlétique.\n• Poussez fermement dans le sol avec l'avant du pied d'appui en gardant le bassin stable.","region":"full_body","setup":["Mur"],"muscles":["Quadriceps","Tronc / Sangle abdominale"],"search":["Wall Drills (Sprint Mechanics)","wall-drills","Exercices au mur"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Insight","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1198","name":"Rowing inversé","description":"Position de départ :\n• Réglez une barre à hauteur de hanches dans un rack ou utilisez un appareil guidé.\n• Placez-vous sur le dos sous la barre et saisissez-la en pronation à une largeur supérieure à celle des épaules.\n• Gardez les talons au sol et le corps parfaitement gainé et aligné de la tête aux pieds.\n\nExécution :\n• Tirez votre poitrine vers la barre en tirant les coudes vers l'arrière et en resserrant les omoplates.\n• Gardez les fessiers et les abdominaux contractés pour maintenir le corps rigide.\n• Redescendez lentement sous contrôle jusqu'à extension complète des bras.","region":"upper_body","setup":["Barre de traction"],"muscles":["Dos"],"search":["Inverted Row","inverted-rows","Tractions horizontales","Inverted row"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Gavru","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1200","name":"Relevés tibiaux (Tibialis raises)","description":"Debout ou adossé à un mur, soulevez la pointe des pieds en restant en appui sur les talons pour solliciter le muscle tibial antérieur, puis redescendez lentement.","region":"lower_body","setup":[],"muscles":["Mollets"],"search":["Tibialis Raises","tibialis-raises"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"cynomops","translationLicense":"CC-BY-SA-4.0","translationAuthor":"cynomops"},
  {"id":"1201","name":"Squat du dragon","description":"Position de départ :\n• Tenez-vous debout, les pieds écartés à la largeur des hanches, mains devant la poitrine.\n• Bombez le torse et engagez le centre du corps.\n\nExécution :\n• Croisez une jambe loin derrière la jambe opposée en diagonale tout en fléchissant les deux genoux dans un squat croisé profond.\n• Descendez le bassin tout en maintenant les épaules et les hanches orientées vers l'avant.\n• Poussez sur le talon de la jambe avant pour remonter à la position de départ, puis répétez de l'autre côté.","region":"lower_body","setup":[],"muscles":["Fessiers","Quadriceps"],"search":["Dragon Squat","dragon-squat","Dragon squat"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"cynomops","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1202","name":"Abduction de hanche en décubitus latéral","description":"Position de départ :\n• Allongez-vous sur le côté sur un tapis de sol.\n• Fléchissez légèrement la jambe du dessous pour stabiliser le corps et gardez la jambe du dessus bien tendue.\n• Posez votre tête sur votre bras inférieur et placez votre main supérieure au sol devant vous pour l'équilibre.\n\nExécution :\n• Levez la jambe supérieure vers le haut de façon contrôlée, les orteils pointant droit devant ou légèrement vers le bas.\n• Veillez à ce que le bassin reste parfaitement perpendiculaire au sol sans basculer vers l'arrière.\n• Marquez un temps d'arrêt en haut pour bien contracter le moyen fessier, puis redescendez lentement.","region":"lower_body","setup":["Tapis de sol"],"muscles":["Fessiers"],"search":["Side-Lying Hip Abduction","side-lying-hip-abduction","Élévation latérale de jambe couché"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"wakanda90","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1203","name":"Extension des mollets sur une jambe (gauche)","description":"Position de départ :\n• Tenez-vous debout sur une marche en posant l'avant-pied gauche sur le bord, le talon dans le vide.\n• Levez la jambe droite pour travailler uniquement sur la jambe gauche.\n• Tenez-vous légèrement à un mur pour stabiliser votre équilibre.\n\nExécution :\n• Laissez descendre le talon gauche sous le niveau de la marche pour bien étirer le mollet.\n• Poussez puissamment sur l'avant du pied pour monter le talon le plus haut possible sur la pointe des pieds.\n• Maintenez la contraction au sommet pendant deux à trois secondes puis redescendez lentement.","region":"lower_body","setup":[],"muscles":["Mollets"],"search":["Left-Leg Calf Raise","calf-raises-left-leg","Extensions des mollets, jambe gauche"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"wakanda90","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1207","name":"Coup de pied du scorpion","description":"Position de départ :\n• Placez-vous en planche haute, mains sous les épaules et pieds écartés à la largeur des hanches.\n• Gardez le corps bien aligné de la tête aux talons avec un bon gainage abdominal.\n\nExécution :\n• Ramenez un genou vers la poitrine puis levez la jambe fléchie vers le haut et l'arrière.\n• Pivotez le bassin pour faire passer le pied au-dessus de la jambe d'appui en direction du sol du côté opposé.\n• Conservez les épaules parallèles au sol pour obtenir une excellente rotation du tronc et étirement de la hanche.\n• Revenez sous contrôle en position de planche et changez de jambe.","region":"full_body","setup":["Tapis de sol"],"muscles":["Bas du dos","Fessiers"],"search":["Scorpion Kick","scorpion-kick","Scorpion kick"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"lxmx","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1208","name":"Squat du prisonnier","description":"Position de départ :\n• Tenez-vous debout, pieds à largeur d'épaules et pointes légèrement ouvertes.\n• Placez vos mains derrière la tête, doigts croisés, et ouvrez largement les coudes vers l'arrière.\n• Bombez le torse et maintenez les omoplates resserrées.\n\nExécution :\n• Poussez les hanches vers l'arrière et fléchissez les genoux jusqu'à ce que les cuisses soient au moins parallèles au sol.\n• Gardez le buste le plus vertical possible et les coudes ouverts sans tirer sur la nuque.\n• Poussez sur les talons pour remonter à la position de départ en contractant les fessiers.","region":"lower_body","setup":[],"muscles":["Fessiers","Quadriceps"],"search":["Prisoner Squat","prisoner-squat","Prisoner squat"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"lxmx","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1209","name":"Pompe trois points","description":"Position de départ :\n• Mettez-vous en position de pompe classique, mains à largeur d'épaules sous la poitrine.\n• Décollez un pied d'environ 5 à 10 cm du sol pour être en appui sur trois points.\n• Gardez le bassin horizontal et le tronc fermement gainé.\n\nExécution :\n• Fléchissez les coudes pour abaisser la poitrine vers le sol de manière contrôlée.\n• Résistez à la rotation du bassin en conservant une ligne parfaite de la tête au talon d'appui.\n• Poussez sur vos mains pour remonter à la position de départ puis changez de jambe.","region":"upper_body","setup":[],"muscles":["Poitrine"],"search":["Three-Point Push-Up","shoulder-width-three-point-push-up","Pompe trois points à largeur d'épaules","Pompe avec une jambe levée"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"lxmx","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1210","name":"Parachutiste bras en T","description":"Position de départ :\n• Allongez-vous à plat ventre sur un tapis avec les jambes plus écartées que la largeur des épaules.\n• Tendez les bras sur les côtés à hauteur des épaules pour former un T avec le torse.\n\nExécution :\n• Décollez simultanément la poitrine, les bras et les jambes du sol en contractant toute la chaîne postérieure.\n• Tournez les pouces vers le plafond et serrez fortement les omoplates.\n• En maintenant le torse et les membres suspendus en l'air, resserrez puis écartez les jambes de façon continue et contrôlée.\n• Reposez le corps au sol avec contrôle à la fin de la série.","region":"full_body","setup":["Tapis de sol"],"muscles":["Bas du dos","Fessiers"],"search":["Skydiver with Arms in T-Position","skydiver-with-arms-in-t-position","Superman avec bras en position T"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"lxmx","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1214","name":"Front lever groupé (Tuck)","description":"Position de départ :\n• Suspendez-vous à une barre de traction en pronation, mains écartées à la largeur des épaules.\n• Resserrez fermement les genoux contre la poitrine en position groupée (tuck) et gainez le corps.\n\nExécution :\n• Tirez vers le bas avec les bras tendus grâce à la force du grand dorsal et des rotateurs de l'épaule pour hisser le buste.\n• Amenez le torse à l'horizontale, parallèle au sol, tout en maintenant les genoux groupés sur la poitrine.\n• Maintenez la position isométrique pendant la durée cible (ex. 5 à 15 secondes).\n• Redescendez lentement sous contrôle vers la suspension complète.","region":"full_body","setup":["Barre de traction"],"muscles":["Dos","Tronc / Sangle abdominale"],"search":["Tuck Front Lever","front-lever-tuck","Front lever groupé","Tuck front lever"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"clafal","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1215","name":"Ange de neige inversé","description":"Position de départ :\n• Allongez-vous à plat ventre sur un tapis, jambes tendues et bras tendus devant vous au-dessus de la tête.\n• Gardez la tête en position neutre, regard vers le sol.\n\nExécution :\n• Décollez légèrement les bras et le haut du torse du sol en activant les muscles du haut du dos.\n• Décrivez un grand arc de cercle avec les bras sur les côtés vers l'arrière jusqu'à effleurer vos cuisses.\n• Serrez fermement les omoplates l'une contre l'autre en fin de trajectoire.\n• Ramenez lentement les bras vers l'avant au-dessus de la tête sans toucher le sol.","region":"upper_body","setup":["Tapis de sol"],"muscles":["Dos"],"search":["Reverse Snow Angel","reverse-snow-angel","Reverse snow angel"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"mike6426","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1216","name":"Tractions de recrutement sur poutre","description":"Position de départ :\n• Installez-vous sous une poutre d'escalade (hangboard) et sélectionnez une réglette adaptée.\n• Saisissez la réglette d'une seule main en gardant les pieds en appui au sol ou sur un support.\n• Adoptez un angle de coude ouvert entre 120 et 150 degrés (jamais en extension complète passive).\n\nExécution :\n• Tirez vers le haut avec un effort isométrique maximal pendant 3 à 5 secondes pour recruter un maximum de fibres motrices.\n• Gardez l'épaule fermement engagée et verrouillée.\n• Prenez un repos complet avant de répéter le tirage sur le bras opposé.","region":"upper_body","setup":[],"muscles":["Avant-bras","Dos"],"search":["Hangboard Recruitment Pulls","recruitment-pulls","Tractions de recrutement","Recruitment Pulls"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1217","name":"Pompes sur le bout des doigts","description":"Position de départ :\n• Mettez-vous en position de pompe en appui uniquement sur le bout des doigts et des pouces largement écartés.\n• Les paumes de mains restent surélevées sans toucher le sol.\n• Gardez le corps bien droit et gainé de la tête aux talons.\n\nExécution :\n• Fléchissez lentement les coudes en descendant la poitrine vers le sol de manière contrôlée.\n• Maintenez une tension solide et stable dans les doigts tout au long du mouvement.\n• Poussez fermement sur le bout des doigts pour remonter à la position de départ.","region":"upper_body","setup":[],"muscles":["Avant-bras","Poitrine"],"search":["Finger Push-Up","finger-pushup","Finger pushup","Pompes sur les doigts"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1218","name":"Pompes sur les genoux","description":"Position de départ :\n• Agenouillez-vous au sol et placez vos mains devant vous, légèrement plus larges que les épaules.\n• Alignez parfaitement votre corps des genoux à la tête avec une sangle abdominale gainée.\n• Les genoux restent fermement posés au sol tout au long de l'exercice.\n\nExécution :\n• Fléchissez les coudes pour descendre la poitrine près du sol sous contrôle.\n• Gardez les coudes orientés à environ 45 degrés par rapport au buste.\n• Poussez dans les paumes pour remonter jusqu'à extension complète des bras en contractant les pectoraux.","region":"upper_body","setup":[],"muscles":["Poitrine"],"search":["Knee Push-Up","knee-push-ups","Knee push-up"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"PaukOne","translationLicense":"CC-BY-SA-4.0","translationAuthor":"PaukOne"},
  {"id":"1219","name":"Tractions australiennes","description":"Position de départ :\n• Installez-vous sur le dos sous une barre basse réglée à hauteur de taille et saisissez-la en supination (paumes vers vous).\n• Gardez le corps bien droit et gainé de la tête aux talons.\n\nExécution :\n• Fléchissez les coudes et hissez votre poitrine vers la barre en resserrant les omoplates.\n• Maintenez la contraction au sommet une seconde pour solliciter au maximum les dorsaux et les biceps.\n• Redescendez lentement sous contrôle jusqu'à l'extension complète des bras.","region":"upper_body","setup":["Barre de traction"],"muscles":["Dos"],"search":["Australian Pull-up","australian-pull-ups","Australian pull-up","Tirage horizontal au poids de corps"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"PaukOne","translationLicense":"CC-BY-SA-4.0","translationAuthor":"PaukOne"},
  {"id":"1223","name":"Claquements de mains au-dessus de la tête","description":"Debout pieds écartés à largeur d'épaules, levez les bras tendus sur les côtés et venez frapper dans vos mains au-dessus de la tête dans un mouvement dynamique.","region":"upper_body","setup":[],"muscles":["Épaules"],"search":["Claps Over the Head","claps-over-the-head"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Lynn_McIntyre","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Lynn_McIntyre"},
  {"id":"1230","name":"Étirement du triceps au-dessus de la tête (gauche)","description":"Position de départ :\n• Tenez-vous debout ou assis, le dos bien droit.\n• Levez le bras gauche au-dessus de la tête, pliez le coude et laissez descendre la main gauche derrière la nuque entre les omoplates.\n\nExécution :\n• Avec la main droite, saisissez le coude gauche et tirez-le doucement vers l'arrière et le bas.\n• Maintenez l'étirement confortable dans le triceps gauche pendant 20 à 30 secondes.\n• Respirez régulièrement sans cambrer le bas du dos.","region":"upper_body","setup":[],"muscles":["Triceps"],"search":["Overhead Triceps Stretch (Left)","triceps-stretch-left","Étirement des triceps à gauche"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Lynn_McIntyre","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1231","name":"Étirement du triceps au-dessus de la tête (droit)","description":"Position de départ :\n• Tenez-vous debout ou assis, le dos bien droit.\n• Levez le bras droit au-dessus de la tête, pliez le coude et laissez descendre la main droite derrière la nuque entre les omoplates.\n\nExécution :\n• Avec la main gauche, saisissez le coude droit et tirez-le doucement vers l'arrière et le bas.\n• Maintenez l'étirement confortable dans le triceps droit pendant 20 à 30 secondes.\n• Respirez profondément sans cambrer la colonne vertébrale.","region":"upper_body","setup":[],"muscles":["Triceps"],"search":["Overhead Triceps Stretch (Right)","triceps-stretch-right","Étirement des triceps à droite"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Lynn_McIntyre","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1232","name":"Étirement du biceps debout au mur (gauche)","description":"Position de départ :\n• Tenez-vous debout avec le flanc gauche près d'un mur.\n• Tendez le bras gauche vers l'arrière et posez la paume de la main gauche à plat contre le mur à hauteur d'épaule.\n\nExécution :\n• Tournez doucement le torse et les pieds vers la droite en vous détournant du mur.\n• Maintenez la position dès que vous ressentez un bon étirement dans le biceps gauche et l'avant de l'épaule.\n• Gardez la posture pendant 20 à 30 secondes en respirant profondément.","region":"upper_body","setup":["Mur"],"muscles":["Biceps"],"search":["Standing Biceps Stretch (Left)","standing-biceps-stretch-left","Étirement des biceps debout à gauche"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Lynn_McIntyre","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1233","name":"Étirement du biceps debout au mur (droit)","description":"Position de départ :\n• Tenez-vous debout avec le flanc droit près d'un mur.\n• Tendez le bras droit vers l'arrière et posez la paume de la main droite à plat contre le mur à hauteur d'épaule.\n\nExécution :\n• Tournez doucement le torse et les pieds vers la gauche en vous détournant du mur.\n• Maintenez la position dès que vous ressentez un bon étirement dans le biceps droit et l'avant de l'épaule.\n• Gardez la posture pendant 20 à 30 secondes en respirant calmement.","region":"upper_body","setup":["Mur"],"muscles":["Biceps"],"search":["Standing Biceps Stretch (Right)","standing-biceps-stretch-right","Étirement des biceps debout à droite"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Lynn_McIntyre","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1238","name":"Équilibre de la grenouille (Frog Stand)","description":"Position de départ :\n• Accroupissez-vous au sol, pieds serrés, et posez les mains à plat à la largeur des épaules avec les doigts bien écartés.\n• Placez vos genoux contre l'extérieur des coudes ou en appui sur l'arrière de vos bras (triceps).\n\nExécution :\n• Transférez lentement le poids de votre corps vers l'avant sur vos mains.\n• Décollez les pieds du sol l'un après l'autre jusqu'à tenir en équilibre sur vos mains avec les coudes fléchis.\n• Gainez le tronc, fixez le sol légèrement vers l'avant et stabilisez la posture grâce à la force des épaules et des doigts.\n• Maintenez cette position isométrique pendant la durée prévue (ex. 10 à 30 secondes) puis reposez doucement les pieds.","region":"upper_body","setup":["Tapis de sol"],"muscles":["Triceps","Épaules"],"search":["Frog Stand","frog-stand","Équilibre de la grenouille","Frog stand"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"clafal","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1239","name":"Étirement des mollets debout","description":"Position de départ :\n• Tenez-vous debout face à un mur à environ une longueur de bras et posez vos mains au mur à hauteur d'épaules.\n• Reculez une jambe vers l'arrière en fente.\n\nExécution :\n• Gardez la jambe arrière parfaitement tendue avec le talon plaqué au sol.\n• Fléchissez le genou avant et avancez le bassin vers le mur jusqu'à ressentir un étirement net dans le mollet arrière (gastrocnémien).\n• Maintenez la position pendant 20 à 30 secondes puis changez de côté.","region":"lower_body","setup":["Mur"],"muscles":["Mollets"],"search":["Standing Calf Stretch","standing-calf-stretch","Étirement des mollets au mur"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"erikocobra","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1240","name":"Étirement du soléaire debout","description":"Debout face à un mur, jambe arrière légèrement fléchie au niveau du genou avec le talon bien plaqué au sol pour cibler spécifiquement le muscle soléaire.","region":"lower_body","setup":["Mur"],"muscles":["Mollets"],"search":["Standing Soleus Stretch","standing-soleus-stretch"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"erikocobra","translationLicense":"CC-BY-SA-4.0","translationAuthor":"erikocobra"},
  {"id":"1243","name":"Extension des mollets sur deux jambes","description":"Position de départ :\nTenez-vous debout, les pieds écartés de la largeur des hanches. Placez vos mains contre un mur ou un support stable pour l'équilibre si nécessaire.\n\nExécution :\n1. Poussez sur la pointe des pieds pour décoller les talons le plus haut possible.\n2. Marquez une pause d'une à deux secondes au sommet en contractant fermement les mollets.\n3. Redescendez lentement les talons au sol de manière contrôlée.","region":"lower_body","setup":[],"muscles":["Mollets"],"search":["Double Leg Calf Raise","double-leg-calf-raise"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"erikocobra","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1244","name":"Exercice de yoga : la vache et le chat","description":"Mettez-vous d'abord à quatre pattes. Les mains sont placées sous les épaules. Les doigts sont largement écartés et garantissent une position stable. L'idéal est de répartir le poids de la partie avant de votre corps sur vos pouces et vos index. Placez maintenant vos jambes écartées de la largeur des hanches sur le tapis de yoga. Vos cuisses doivent être à la verticale, sous vos hanches. Veillez à ce que votre poids soit réparti de manière égale entre vos mains et vos genoux. Votre tête est dans le prolongement de votre colonne vertébrale et votre regard est dirigé vers le tapis. Votre dos est en position neutre. Inspirez profondément et commencez par la posture du chat. Lors de l'expiration suivante, arrondissez votre dos vertèbre par vertèbre. Essayez de vous étirer le plus possible vers le plafond. Ramenez votre tête vers votre poitrine et basculez votre bassin. Inspirez maintenant profondément et passez à la position opposée, la posture de la vache. Creusez votre dos vers le bas, tirez légèrement vos épaules vers l'arrière et levez votre tête aussi haut que cela vous est confortable. Votre regard est dirigé vers le haut. Expirez consciemment et revenez à la posture du chat. Lors de l'expiration suivante, repassez à la posture de la vache. Répétez l'exercice plusieurs fois en veillant à rester dans le flux du mouvement.","region":"core","setup":["Tapis de sol"],"muscles":["Bas du dos","Tronc / Sangle abdominale"],"search":["Yoga exercise: Cow-cat","yoga-exercise-cow-cat"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"damnlost","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1245","name":"Front Lever (planche faciale)","description":"Figure de gymnastique et de callisthénie où le corps est suspendu à la barre et maintenu parfaitement à l'horizontale, parallèle au sol, les bras tendus et le tronc gainé.","region":"full_body","setup":["Barre de traction"],"muscles":["Dos","Tronc / Sangle abdominale"],"search":["Front Lever","front-lever"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"clafal","translationLicense":"CC-BY-SA-4.0","translationAuthor":"clafal"},
  {"id":"1248","name":"Ice cream maker","description":"Depuis la phase finale d'une traction, nous nous repoussons vers l'arrière avec les épaules jusqu'à atteindre la position de front lever. À partir de là, nous nous tirons de nouveau vers le haut pour revenir à la position de départ.","region":"full_body","setup":["Barre de traction"],"muscles":["Dos","Tronc / Sangle abdominale"],"search":["Ice Cream Maker","ice-cream-maker"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"clafal","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1252","name":"Tractions en Front lever","description":"En position de front lever (corps à l'horizontale face au plafond), fléchissez les bras pour hisser le torse vers la barre en maintenant le gainage complet.","region":"full_body","setup":["Barre de traction"],"muscles":["Dos","Tronc / Sangle abdominale"],"search":["Front Lever Pull-up","front-lever-pull-up"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"clafal","translationLicense":"CC-BY-SA-4.0","translationAuthor":"clafal"},
  {"id":"1263","name":"Pont arrière","description":"Allongez-vous au sol, le dos posé sur le sol et les jambes pliées, les pieds à plat sur le sol, en laissant environ 20 cm entre vos pieds et vos fessiers. Vos mains restent à plat sur le sol, pressées contre vos oreilles, les doigts pointés vers vos orteils. Vos coudes sont pliés et pointés vers le plafond. C'est la position de départ. Poussez maintenant vos hanches aussi haut que possible en décollant votre corps du sol, et continuez à pousser sur vos mains en tendant vos coudes et vos genoux, jusqu'à ce que votre dos soit entièrement cambré (pont lombaire). Votre tête se décolle également du sol et doit être au niveau de vos coudes, le regard dirigé vers l'arrière. C'est la position finale. La descente doit être lente et contrôlée. Votre colonne vertébrale doit former une courbe convexe. Il ne faut pas décoller le dos du sol de façon désordonnée ; il doit rester bien arrondi. Vous ressentirez également une sensation d'oxygénation accrue dans votre dos. Après vous être décollé du sol, vos hanches doivent être très hautes, même au-dessus du niveau de votre tête. Vos bras et vos jambes doivent rester tendus. Cela paraît facile, mais cela demande un bon niveau de souplesse. La respiration doit être profonde. Cette posture étire la cage thoracique et exerce une pression sur le diaphragme. Si la posture est réalisée correctement, la respiration sera parfaite. Ne retenez jamais votre souffle pendant l'exercice.","region":"full_body","setup":["Tapis de sol"],"muscles":["Bas du dos","Fessiers"],"search":["Back Bridge","back-bridge"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"cynomops","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1274","name":"Étirement des mollets assis (dorsiflexion)","description":"Assis au sol jambes tendues, passez une serviette ou une sangle autour de l'avant-pied et tirez vers vous en flexion dorsale pour étirer les mollets.","region":"lower_body","setup":["Tapis de sol"],"muscles":["Mollets"],"search":["Sitting Calf Stretch (Dorsiflexion)","sitting-calf-stretch-dorsiflexion"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"erikocobra","translationLicense":"CC-BY-SA-4.0","translationAuthor":"erikocobra"},
  {"id":"1282","name":"Maintien isométrique en traction supination (Chin-up hold)","description":"Maintenez la position de suspension haute en traction supination, menton au-dessus de la barre et coudes complètement fléchis, pendant le temps imparti.","region":"upper_body","setup":["Barre de traction"],"muscles":["Biceps","Dos"],"search":["Isometric Reverse-Grip Chin-Up Hold","isometria-trazioni-impugnatura-inversa"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"clafal","translationLicense":"CC-BY-SA-4.0","translationAuthor":"clafal"},
  {"id":"1284","name":"Pompe pseudo planche","description":"Vous devez avoir la ligne des épaules en avant de vos poignets et effectuer une pompe en maintenant les épaules dans la même position.","region":"upper_body","setup":["Tapis de sol"],"muscles":["Poitrine","Épaules"],"search":["Pseudo Planche Push-up","pseudo-planche-push-up"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"vdrb","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1285","name":"Talons-fesses (Butt Kicks)","description":"En marchant ou en courant sur place ou en avançant, fléchissez les genoux pour amener vigoureusement les talons vers les fessiers.","region":"lower_body","setup":[],"muscles":["Ischio-jambiers","Mollets"],"search":["Butt Kicks","talons-fesses"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"painDpice","translationLicense":"CC-BY-SA-4.0","translationAuthor":"painDpice"},
  {"id":"1286","name":"Planche dynamique","description":"Commencez en position de planche, avec vos mains directement sous vos épaules et vos pieds écartés à la largeur des hanches. 2. Contractez vos abdominaux pour maintenir votre corps en ligne droite de la tête aux pieds. 3. À partir de cette position, pliez légèrement les genoux et sautez avec les deux pieds vers l'intérieur, en les rapprochant de votre tronc autant que possible. 4. Dès que vos pieds touchent le sol, poussez avec force pour sauter à nouveau et revenir à la position de planche initiale. 5. Continuez à répéter ce mouvement de saut, en gardant le contrôle et en maintenant la stabilité de votre tronc tout au long de l'exercice. 6. Assurez-vous de garder une respiration régulière pendant que vous sautez, en respirant profondément et en contrôlant votre respiration. 7. Gardez votre regard fixé sur le sol pour maintenir un bon alignement de la colonne vertébrale. 8. Répétez les sauts pendant la durée souhaitée ou selon le nombre de répétitions recommandé pour votre programme d'entraînement. 9. Pour terminer l'exercice, reposez-vous en relâchant la position de planche, puis étirez-vous si nécessaire pour détendre vos muscles.","region":"core","setup":["Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["Plank Tuck Jump","dynamic-planche"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"painDpice","translationLicense":"CC-BY-SA-4.0","translationAuthor":"admin"},
  {"id":"1287","name":"Élévations vers le plafond","description":"Pour réaliser cet exercice, allongez-vous sur le dos, les bras tendus au-dessus de la tête. Contractez ensuite vos abdominaux et décollez votre torse du sol tout en tendant vos bras vers le plafond afin d'atteindre le plus haut possible. Revenez lentement à la position de départ en contrôlant le mouvement. Ces élévations renforcent les muscles abdominaux et améliorent la souplesse de la colonne vertébrale. Elles peuvent être intégrées à diverses routines d'entraînement pour travailler la force et la stabilité de la sangle abdominale.","region":"core","setup":["Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["Reach-up","reach-ups"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"painDpice","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1288","name":"Planche latérale dynamique","description":"La planche latérale dynamique consiste à se positionner sur le côté, en appui sur un coude et sur le côté du pied, puis à abaisser et relever les hanches tout en gardant le corps en ligne droite.","region":"core","setup":["Tapis de sol"],"muscles":["Bas du dos","Tronc / Sangle abdominale"],"search":["Dynamic Side Plank","dynamic-side-plank"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"painDpice","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1292","name":"Tractions en supination (Chin-ups)","description":"Suspendu à la barre fixe en prise supination (paumes vers vous), hissez le corps jusqu'à dépasser la barre avec le menton en sollicitant biceps et dorsaux.","region":"upper_body","setup":["Barre de traction"],"muscles":["Biceps","Dos"],"search":["Reverse-Grip Pull-Up","reverse-grip-pull-ups"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"clafal","translationLicense":"CC-BY-SA-4.0","translationAuthor":"clafal"},
  {"id":"1293","name":"Pompes sur un bras","description":"En appui sur un seul bras, pieds largement écartés pour assurer la stabilité, fléchissez le coude pour descendre la poitrine puis repoussez le sol avec puissance.","region":"upper_body","setup":["Tapis de sol"],"muscles":["Poitrine","Triceps"],"search":["One-Arm Push-Up","one-armed-push-ups"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"clafal","translationLicense":"CC-BY-SA-4.0","translationAuthor":"clafal"},
  {"id":"1294","name":"Flexion des ischios sur une jambe au sol","description":"Position de départ :\nAllongé sur le dos sur un tapis de sol, placez le talon d'une jambe sur le sol (ou sur un linge glissant) avec le genou légèrement plié, l'autre jambe étant relevée.\n\nExécution :\n1. Décollez le bassin du sol en position de pont fessier unipodal.\n2. Tirez vigoureusement le talon vers les fessiers en fléchissant le genou pour contracter l'ischio-jambier.\n3. Revenez lentement à la position de départ en contrôlant l'extension de la jambe.","region":"lower_body","setup":["Tapis de sol"],"muscles":["Ischio-jambiers"],"search":["Single-Leg Hamstring Curl","single-leg-hamstring-curl","Leg curl unilatéral pour ischios"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"clafal","translationLicense":"CC-BY-SA-4.0","translationAuthor":"clafal"},
  {"id":"1307","name":"Planche frontale","description":"La planche est un exercice au poids du corps. Mouvement polyvalent, la planche ne cible pas seulement vos abdominaux, mais aussi la colonne vertébrale et les hanches. La planche renforce et raffermit l'ensemble de votre corps, améliore votre posture et votre équilibre, réduit la masse grasse et peut contribuer à stimuler votre métabolisme.\nDes exercices comme la « position de la planche » aident à renforcer l'endurance des muscles abdominaux stabilisateurs. Elle peut également aider à soulager les douleurs dorsales liées à un affaiblissement de la fonction des muscles stabilisateurs du corps.\nLa planche est un exercice polyvalent qui sollicite un grand nombre des principaux groupes musculaires du corps, si bien que tout le monde peut l'utiliser pour améliorer son endurance et sa force générale.","region":"core","setup":["Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["Plank","front-plank","Gainage"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"hektkaso","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1312","name":"Squat au poids du corps","description":"Le squat est un type d'exercice au poids du corps. C'est l'un des exercices les plus populaires pour la force et la prise de muscle. Le squat est particulièrement efficace pour cibler les muscles des jambes et des hanches.\nLe squat est un exercice facile à réaliser pour les débutants. Il peut aider à renforcer les muscles des jambes, à raffermir les muscles des hanches et à brûler des calories pour perdre du poids.\nIl raffermit les fessiers et les jambes. Les squats sont très efficaces pour tonifier et renforcer vos jambes en agissant sur les fessiers, les fléchisseurs de hanche, les quadriceps, les ischio-jambiers et les muscles de l'intérieur de la cuisse. De plus, les squats au poids du corps peuvent aider à galber vos fessiers.","region":"lower_body","setup":[],"muscles":["Fessiers","Quadriceps"],"search":["Bodyweight Squat","bodyweight-squat-hd","Squat au poids du corps HD"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"admin","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1314","name":"Jumping Jack","description":"Le jumping jack est un exercice pliométrique. La pliométrie regroupe des mouvements aérobiques explosifs qui augmentent la vitesse, la rapidité et la puissance, et qui sollicitent l'ensemble du corps.\nLe jumping jack cible les bras, les épaules, les abdominaux, les muscles des hanches et les fléchisseurs de hanche, et fait aussi travailler les cuisses, les tendons du genou et les quadriceps.\nLes sauts sont bénéfiques pour la santé car ils associent travail cardiovasculaire et renforcement musculaire. Comme les sauts font monter le rythme cardiaque, ils peuvent aussi améliorer votre condition cardiovasculaire.","region":"lower_body","setup":[],"muscles":["Mollets","Quadriceps"],"search":["Jumping Jack","jumping-jack-hd","Jumping jack HD"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"hektkaso","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1318","name":"Montées de genoux sautées","description":"Vous pouvez utiliser cet exercice aussi bien comme échauffement dynamique avant l'entraînement que l'ajouter à votre routine de cardio pour brûler des graisses.\nLes montées de genoux sautées sont un exercice pliométrique. La pliométrie regroupe des mouvements aérobiques explosifs qui augmentent la vitesse, la rapidité et la puissance, et qui sollicitent l'ensemble du corps.\nLes montées de genoux sautées ciblent les obliques, les muscles des jambes, les muscles des hanches et les fléchisseurs de hanche, et font aussi travailler les cuisses, les tendons du genou, les quadriceps et les épaules.\nLes sauts sont bénéfiques pour la santé car ils associent travail cardiovasculaire et renforcement musculaire. Comme les sauts font monter le rythme cardiaque, ils peuvent aussi améliorer votre condition cardiovasculaire.","region":"full_body","setup":[],"muscles":["Quadriceps","Tronc / Sangle abdominale"],"search":["High Knee Skips","high-knee-skips-hd","Montées de genoux sautées HD"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"hektkaso","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1320","name":"Dips triceps au sol","description":"Les dips triceps au sol sont un exercice polyarticulaire car ils sollicitent plusieurs groupes musculaires simultanément. Bien que cet exercice au poids du corps cible principalement les triceps, il fait aussi travailler vos pectoraux et l'avant de vos épaules.\nLes dips triceps au sol sont l'un des exercices les plus efficaces pour augmenter la force des bras et développer une musculature sèche au niveau des bras.\nLes dips triceps au sol sont un exercice en chaîne cinétique fermée, ce qui signifie que vous effectuez les mouvements autour d'un point fixe. Cela augmente la force de compression sur vos articulations et améliore ainsi la stabilité.","region":"upper_body","setup":[],"muscles":["Triceps"],"search":["Bench Dips On Floor","bench-dips-on-floor-hd","Dips sur banc au sol HD"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"hektkaso","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1324","name":"Fentes au poids du corps","description":"Les fentes au poids du corps sont un exercice de callisthénie efficace pour renforcer le bas du corps, améliorer l'équilibre et la stabilité, et développer une force fonctionnelle. Elles constituent un choix populaire pour les séances au poids du corps, les entraînements à la maison, et peuvent aussi s'intégrer à un programme de renforcement musculaire plus complet.","region":"lower_body","setup":[],"muscles":["Fessiers","Quadriceps"],"search":["Bodyweight Lunge","bodyweight-lunge-hd","Fente au poids du corps HD"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"hektkaso","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1325","name":"Poussée latérale explosive","description":"En appui unipodal, poussez latéralement de manière explosive sur la jambe d'appui pour projeter le corps sur le côté et stabiliser la réception.","region":"lower_body","setup":[],"muscles":["Fessiers","Quadriceps"],"search":["Lateral Push Off","lateral-push-off"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"cleen","translationLicense":"CC-BY-SA-4.0","translationAuthor":"cleen"},
  {"id":"1348","name":"Extensions du dos au banc à lombaires","description":"Position de départ :\nInstallez-vous face contre le banc à lombaires (chaise romaine), le haut des cuisses en appui sur les coussins et le bassin libre pour permettre la flexion. Calez bien vos chevilles sous les boudins. Croisez les bras sur la poitrine ou placez vos mains près des oreilles.\n\nMouvement :\nFléchissez le buste vers l'avant à partir des hanches en gardant la colonne vertébrale neutre. Redressez le buste de façon contrôlée en contractant les lombaires, les fessiers et les ischio-jambiers jusqu'à ce que votre corps forme une ligne droite.\n\nConseils :\nN'hypercambrisez pas le dos en fin de mouvement. Effectuez la répétition sans à-coup.","region":"full_body","setup":["Tapis de sol"],"muscles":["Bas du dos","Fessiers"],"search":["Back Extension","lower-back-extensions","Banc à lombaire","Hyperextensions"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Anastasious","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1363","name":"Automassage au rouleau de mousse (Blackroll)","description":"Séance globale d'automassage myo-fascial au rouleau de mousse pour relâcher les tensions musculaires et accélérer la récupération.","region":"core","setup":["Rouleau de massage (Foam roller)","Tapis de sol"],"muscles":["Bas du dos"],"search":["Foam Rolling (Blackroll)","blackroll"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Anastasious","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Anastasious"},
  {"id":"1373","name":"Sauts sur boîte pliométrique (Box jump)","description":"Depuis la station debout face à une boîte pliométrique, fléchissez les genoux et sautez des deux pieds pour atterrir souplement en demi-squat sur le dessus de la boîte.","region":"lower_body","setup":["Boîte de pliométrie (Plyo box) / Step"],"muscles":["Fessiers","Quadriceps"],"search":["Box Jump","box-jumps"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"tekknokrat","translationLicense":"CC-BY-SA-4.0","translationAuthor":"tekknokrat"},
  {"id":"1377","name":"Rotation du buste debout","description":"Position de départ :\nDebout, pieds écartés de la largeur des épaules et genoux légèrement déverrouillés. Gardez le bassin stable face vers l'avant et croisez les bras sur la poitrine ou placez les mains derrière la tête.\n\nMouvement :\nFaites pivoter votre buste de manière fluide d'un côté en engageant les obliques, tout en maintenant les hanches et le bas du corps immobiles. Marquez un temps d'arrêt en fin de course, revenez au centre, puis pivotez du côté opposé à un rythme régulier.\n\nConseils :\nLa rotation doit être guidée par la cage thoracique et les abdominaux, sans torsion excessive de la colonne lombaire ni mouvement des hanches.","region":"core","setup":[],"muscles":["Tronc / Sangle abdominale"],"search":["Standing Torso Twist","torso-twist","Rotation du torse"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"brucem","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1387","name":"Battements de jambe tendue","description":"Tenez-vous debout, les pieds écartés de la largeur des hanches, et tendez un bras devant vous. Balancez cette jambe vers le haut devant vous puis ramenez-la vers le bas en la gardant aussi tendue que possible et les orteils pointés vers le haut. Répétez avec l'autre jambe.","region":"lower_body","setup":[],"muscles":["Ischio-jambiers"],"search":["Hamstring Kicks","hamstring-kicks"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"captive0592","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1388","name":"Soulevé de terre roumain sur une jambe","description":"Tenez-vous droit et tenez des charges dans les deux mains si vous utilisez du poids.\nGainez vos abdominaux et décollez une jambe du sol.\nGardez le dos droit, basculez au niveau des hanches en abaissant votre torse vers l'avant, en veillant à ne pas faire pivoter vos hanches.\nDescendez jusqu'à sentir un étirement dans l'ischio-jambier de votre jambe d'appui, puis revenez en position debout. Répétez des deux côtés.","region":"lower_body","setup":[],"muscles":["Fessiers","Ischio-jambiers"],"search":["Single Leg RDL","single-leg-rdl"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"admin","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1390","name":"Toucher des orteils","description":"Tenez-vous debout, les pieds rapprochés. Fléchissez au niveau des hanches et abaissez le haut du corps vers vos orteils. Tendez les mains vers vos pieds et essayez de toucher vos orteils, le sol, ou de descendre aussi bas que possible le long de vos jambes sans forcer.","region":"lower_body","setup":[],"muscles":["Ischio-jambiers"],"search":["Toe Touch","toe-touch"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"captive0592","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1391","name":"Marche de l'éléphant","description":"Fléchissez au niveau des hanches jusqu'à ressentir un étirement à l'arrière des genoux. Pliez une jambe pendant que l'autre reste tendue, puis pliez l'autre genou de manière fluide tout en tendant le premier.","region":"lower_body","setup":[],"muscles":["Ischio-jambiers"],"search":["Elephant Walks","elephant-walks"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"captive0592","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1392","name":"Good morning au poids du corps","description":"Tenez-vous debout, les pieds écartés au-delà de la largeur des épaules (position large), et placez vos mains sur vos hanches. Fléchissez au niveau des hanches et abaissez le haut du corps vers le sol en gardant le dos droit, puis redressez-vous.","region":"lower_body","setup":[],"muscles":["Fessiers","Ischio-jambiers"],"search":["Bodyweight Good Morning","good-morning","Good morning"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"captive0592","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1393","name":"Étirement des ischio-jambiers sur une jambe","description":"Asseyez-vous au sol, une jambe tendue devant vous et l'autre repliée vers vous. Tendez les deux mains vers l'avant en essayant de toucher les orteils de votre jambe tendue.","region":"lower_body","setup":["Tapis de sol"],"muscles":["Ischio-jambiers"],"search":["Single Leg Hamstring Stretch","single-leg-hamstring-stretch"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"captive0592","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1394","name":"Flexion assise (sit & reach)","description":"Asseyez-vous au sol, les jambes tendues devant vous. Tendez les deux mains vers l'avant en essayant de dépasser vos orteils ou d'aller aussi loin que possible. Revenez à la position de départ et répétez.","region":"lower_body","setup":["Tapis de sol"],"muscles":["Ischio-jambiers"],"search":["Sit & Reach","sit-reach"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"captive0592","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1395","name":"Balancements de jambe croisés","description":"Tenez-vous à un mur ou à un appui à proximité pour vous stabiliser. Balancez une jambe devant votre corps en la croisant, puis ramenez-la vers l'arrière et sur le côté. Répétez en augmentant progressivement votre amplitude de mouvement.","region":"lower_body","setup":["Mur"],"muscles":["Adducteurs","Fessiers"],"search":["Crossbody Leg Swings","crossbody-leg-swings"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"captive0592","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1396","name":"Pancake debout","description":"Tenez-vous debout et écartez les jambes le plus possible en position de grand écart facial. Fléchissez ensuite au niveau des hanches en les poussant vers l'arrière tout en gardant le dos droit.","region":"lower_body","setup":[],"muscles":["Adducteurs","Ischio-jambiers"],"search":["Standing Pancake","standing-pancake"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"captive0592","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1397","name":"Good morning jambes écartées debout","description":"Tenez-vous debout, les pieds écartés au-delà de la largeur des épaules et les orteils légèrement tournés vers l'extérieur. Placez vos mains derrière la tête. Effectuez une bascule à partir des hanches et abaissez le haut du corps vers le sol, en gardant le dos droit et la poitrine ouverte.","region":"lower_body","setup":[],"muscles":["Adducteurs","Ischio-jambiers"],"search":["Standing Pancake Good Morning","standing-pancake-good-morning"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"captive0592","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1398","name":"Étirement actif de l'ischio-jambier assis","description":"Asseyez-vous au sol et pliez une jambe en ramenant le genou vers vous. Placez votre main derrière l'ischio-jambier et tirez doucement votre jambe vers la poitrine, en ressentant un étirement à l'arrière de la cuisse. Tendez ensuite votre jambe en la dépliant vers le plafond.","region":"lower_body","setup":["Tapis de sol"],"muscles":["Ischio-jambiers"],"search":["Seated Hamstring Choke Stretch","hamstring-chokes","Étirement de l'ischio-jambier vers la poitrine","Hamstring Chokes"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"captive0592","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1399","name":"Déroulé du buste (roll down)","description":"Tenez-vous debout, les pieds écartés de la largeur des hanches, et déroulez lentement le haut du corps vers l'avant, une vertèbre à la fois, jusqu'à ce que vos mains touchent le sol ou aussi bas que vous le pouvez sans forcer. Remontez à la position de départ avec le même contrôle.","region":"core","setup":["Tapis de sol"],"muscles":["Bas du dos","Tronc / Sangle abdominale"],"search":["Roll Down","roll-down"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"captive0592","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1400","name":"Étirement des ischio-jambiers jambes croisées","description":"Debout, croisez une jambe derrière l'autre (gardez cette jambe tendue). Penchez-vous vers le bas et essayez de toucher les orteils de cette jambe. Fléchissez légèrement l'autre jambe afin de pouvoir vous pencher.","region":"lower_body","setup":[],"muscles":["Ischio-jambiers"],"search":["Crossbody Hamstring Stretch","crossbody-hamstring-stretch"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"captive0592","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1406","name":"Gainage planche vers extension des coudes","description":"Depuis la position de planche sur les avant-bras, poussez sur vos mains l'une après l'autre pour monter en planche haute bras tendus, puis redescendez de manière contrôlée sur les coudes. Maintenez le bassin stable sans balancer les hanches.","region":"full_body","setup":["Tapis de sol"],"muscles":["Triceps","Tronc / Sangle abdominale"],"search":["Plank-to-Elbow Extension (Plank to Push-Up)","plank-to-elbow-extension"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"clafal","translationLicense":"CC-BY-SA-4.0","translationAuthor":"clafal"},
  {"id":"1407","name":"Squat cosaque","description":"Le squat cosaque est un exercice pluri-articulaire qui sollicite principalement les jambes et les fessiers, mais qui fait aussi intervenir les muscles stabilisateurs. C'est un excellent exercice pour améliorer la force, la mobilité et la stabilité de manière fonctionnelle.","region":"lower_body","setup":[],"muscles":["Fessiers","Quadriceps"],"search":["Cossack squat","cossack-squat"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"clafal","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1408","name":"Chaise (wall-sit)","description":"La chaise (ou wall sit) est un exercice isométrique qui sollicite principalement les muscles des jambes, en améliorant l'endurance musculaire et la stabilité. Voici les muscles principaux et secondaires activés pendant l'exercice.","region":"lower_body","setup":["Mur"],"muscles":["Fessiers","Quadriceps"],"search":["Wall-sit","wall-sit","Chaise contre le mur"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"clafal","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1409","name":"Dragon flag","description":"Gardez le corps complètement gainé tout au long du mouvement, en évitant de creuser le bas du dos.\nUtilisez une prise ferme pour stabiliser le haut du corps.\nCommencez par des versions plus simples (par exemple avec les genoux fléchis) afin de développer la force et le contrôle.","region":"core","setup":["Banc plat"],"muscles":["Tronc / Sangle abdominale"],"search":["Dragon-flag","dragon-flag"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"clafal","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1410","name":"Planche avec élévation alternée des jambes","description":"En position de planche, levez une jambe de manière contrôlée en contractant le fessier, reposez-la, puis répétez avec l'autre jambe en maintenant le bassin immobile.","region":"full_body","setup":["Tapis de sol"],"muscles":["Fessiers","Tronc / Sangle abdominale"],"search":["Plank with Alternating Leg Lift","plank-with-alternating-leg-lift"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"hpmbala","translationLicense":"CC-BY-SA-4.0","translationAuthor":"hpmbala"},
  {"id":"1411","name":"Toucher des talons","description":"Position de départ :\n\nAllongez-vous sur le dos sur un tapis de sport.\nFléchissez les genoux en gardant les pieds à plat au sol et écartés de la largeur des hanches.\nPlacez vos bras le long du corps, paumes tournées vers l'intérieur, légèrement décollées du sol.\n\n\n\nGainez le tronc :\n\nDécollez légèrement la tête, les épaules et le haut du dos du sol.\nGardez la nuque neutre et le menton légèrement rentré.\n\n\n\nRéalisez le mouvement :\n\nInclinez-vous latéralement vers la droite en tendant votre main droite vers votre talon droit.\nRevenez au centre, puis inclinez-vous vers la gauche en tendant votre main gauche vers votre talon gauche.\nContinuez en alternant les côtés de façon contrôlée.\n\n\n\nRespiration :\n\nExpirez lorsque vous tendez la main vers le talon et inspirez lorsque vous revenez au centre.","region":"core","setup":["Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["Heel Touches","heel-touches"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"hpmbala","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1412","name":"Crunchs bicyclette","description":"Les crunchs bicyclette sont un exercice de gainage réalisé au sol. Allongez-vous sur le dos, les mains derrière la tête et les jambes tendues. Décollez les épaules du sol, ramenez un genou vers la poitrine et faites pivoter le torse de sorte que le coude opposé rejoigne le genou. Alternez les côtés dans un mouvement de pédalage, en veillant à garder des mouvements contrôlés et à solliciter la sangle abdominale tout au long de l'exercice.","region":"core","setup":["Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["Bicycle Crunch","bicycle-crunches"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"hpmbala","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1425","name":"Toe taps","description":"Les toe taps sont un exercice de gainage réalisé allongé sur le dos. Allongez-vous à plat, les bras le long du corps et les jambes levées en position de table (genoux fléchis à 90 degrés). Abaissez lentement un pied pour toucher délicatement le sol, en gardant la sangle abdominale gainée et le bas du dos plaqué contre le sol. Revenez à la position de départ et alternez les jambes. Cet exercice renforce la sangle abdominale tout en minimisant les tensions sur le bas du dos.","region":"core","setup":["Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["Toe Taps","toe-taps"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"hpmbala","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1426","name":"Crunchs latéraux debout","description":"Les crunchs latéraux debout sont un exercice dynamique qui cible les obliques tout en améliorant l'équilibre et la stabilité. Tenez-vous bien droit, les pieds écartés de la largeur des épaules et les mains derrière la tête, ou un haltère dans une main. Inclinez le torse d'un côté en contractant les obliques, tout en ramenant le coude vers la hanche (ou en crunchant vers la charge si vous utilisez un haltère). Revenez à la position de départ et alternez les côtés, ou effectuez toutes les répétitions d'un côté avant de changer.","region":"core","setup":[],"muscles":["Bas du dos","Tronc / Sangle abdominale"],"search":["Standing Side Crunches","standing-side-crunches"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"hpmbala","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1435","name":"Tractions scapulaires","description":"Suspendu à la barre bras tendus, rétractez et abaissez les omoplates pour remonter le corps de quelques centimètres sans plier les coudes.","region":"upper_body","setup":["Barre de traction"],"muscles":["Dos"],"search":["Scapular Pull-Ups","scapula-pulls"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"M9","translationLicense":"CC-BY-SA-4.0","translationAuthor":"M9"},
  {"id":"1450","name":"Étirement du cobra (Cobra Stretch)","description":"Position de départ :\n• Allongez-vous à plat ventre sur un tapis, jambes tendues vers l'arrière et dessus des pieds au sol.\n• Placez vos mains à plat sous les épaules, coudes serrés le long du buste.\n\nExécution :\n• Poussez doucement sur vos paumes pour redresser le buste et décoller la poitrine, tout en gardant le bassin et les cuisses plaqués au sol.\n• Baissez les épaules vers l'arrière, loin des oreilles, en ouvrant la cage thoracique.\n• Maintenez la position pendant 15 à 30 secondes en respirant profondément.\n• Redescendez lentement la poitrine sur le tapis avec contrôle.","region":"core","setup":["Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["Cobra Stretch","cobra-stretch","Étirement du cobra"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"hpmbala","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1451","name":"Étirement en rotation du tronc","description":"Position de départ :\n• Tenez-vous debout, pieds à la largeur des épaules et genoux déverrouillés (ou assis le dos bien droit).\n• Croisez les bras sur la poitrine ou posez les mains sur les hanches.\n\nExécution :\n• Tournez lentement le haut du corps vers un côté en maintenant le bassin et les hanches orientés droit devant.\n• Maintenez la rotation pendant 15 à 30 secondes en respirant calmement.\n• Revenez au centre avec contrôle et répétez de l'autre côté.","region":"core","setup":[],"muscles":["Tronc / Sangle abdominale"],"search":["Torso Rotation Stretch","torso-rotation-stretch"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"hpmbala","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1452","name":"Étirement genou-poitrine","description":"Position de départ :\n• Allongez-vous sur le dos sur un tapis de sol, jambes étendues et tête relâchée.\n\nExécution :\n• Fléchissez un genou, saisissez le tibia ou l'arrière de la cuisse à deux mains et ramenez doucement le genou vers la poitrine.\n• Gardez l'autre jambe allongée au sol pour ressentir l'étirement au niveau du fessier et du bas du dos.\n• Maintenez la position pendant 20 à 30 secondes en respirant profondément, puis changez de jambe.","region":"lower_body","setup":["Tapis de sol"],"muscles":["Fessiers"],"search":["Knee-to-Chest Stretch","knee-to-chest-stretch"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"hpmbala","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1455","name":"Superman avec serviette","description":"Position de départ :\n• Allongez-vous à plat ventre sur un tapis de sol, les jambes tendues vers l'arrière.\n• Tenez une serviette bien tendue entre vos deux mains, bras tendus devant vous à la largeur des épaules.\n\nExécution :\n• Décollez simultanément la poitrine, les bras et les jambes du sol en contractant les fessiers et les érecteurs du rachis.\n• En maintenant la serviette sous tension, fléchissez les coudes pour amener la serviette vers le haut de la poitrine.\n• Tendez à nouveau les bras vers l'avant de manière contrôlée sans reposer complètement le torse au sol.\n• Répétez le mouvement avec fluidité.","region":"full_body","setup":["Tapis de sol"],"muscles":["Bas du dos","Dos"],"search":["Towel Superman","towel-superman"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Yderkone","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1462","name":"Coups de poing directs (Punches)","description":"Debout en garde stable, décochez des frappes directes rapides et rythmées en engageant la rotation des hanches et le gainage abdominal.","region":"upper_body","setup":[],"muscles":["Épaules"],"search":["Punches","punches"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"lh1701","translationLicense":"CC-BY-SA-4.0","translationAuthor":"lh1701"},
  {"id":"1474","name":"Relevé en W (W-Raise)","description":"Position de départ :\nAllongez-vous sur le dos sur un tapis, les bras le long du corps pour la stabilité. Gardez les jambes tendues et légèrement décollées du sol.\n\nExécution :\n1. En maintenant le gainage abdominal, levez les jambes en diagonale vers la gauche en décollant le bassin du sol (première branche du W inversé).\n2. Redescendez les jambes à mi-hauteur de manière contrôlée, amenez-les au centre et levez-les droit vers le haut en soulevant à nouveau les hanches.\n3. Redescendez à mi-hauteur puis levez les jambes en diagonale vers la droite.\n4. Inversez le parcours pour revenir au point de départ et continuez la séquence.\n\nConseils :\nGardez les abdominaux sous tension continue et évitez tout élan des jambes pour protéger le bas du dos.","region":"core","setup":["Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["W-Raise","w-raise","W-Raise"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Moffi","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1475","name":"Glissements de genoux Black Widow","description":"Position de départ :\nCommencez en position de planche haute, les mains directement sous les épaules et le corps formant une ligne droite de la tête aux talons.\n\nExécution :\n1. Amenez un genou en diagonale sous le tronc en direction du coude opposé.\n2. Faites glisser le genou vers le haut le long de l'avant-bras tout en accentuant la bascule postérieure du bassin pour contracter fortement les obliques et les abdominaux.\n3. Revenez avec contrôle en position de planche de départ.\n4. Répétez le mouvement avec le genou opposé, en alternant les côtés.\n\nConseils :\nGardez le bassin stable et le ventre rentré sans laisser le bas du dos se creuser.","region":"core","setup":["Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["Black Widow Knee Slides","black-widow-knee-slides","Black widow knee slides (glissements de genou)","Black Widow Knee Slides"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Moffi","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1476","name":"Sit-up papillon (Butterfly Sit-up)","description":"Position de départ :\nAllongez-vous sur le dos sur un tapis, les plantes de pieds l'une contre l'autre et les genoux ouverts vers l'extérieur en papillon. Tendez les bras derrière la tête en touchant le sol avec les mains.\n\nExécution :\n1. Contractez les abdominaux et utilisez un léger élan contrôlé des bras pour relever le torse.\n2. Montez jusqu'à la position assise complète en venant toucher le sol avec les mains devant vos pieds.\n3. Redescendez lentement en déroulant la colonne vertébrale jusqu'à retrouver la position de départ au sol.\n\nConseils :\nL'ouverture des hanches désactive en partie les fléchisseurs de la hanche, concentrant ainsi l'effort sur les abdominaux.","region":"core","setup":["Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["Butterfly Sit-up","butterfly-sit-up","Relevé de buste papillon","Butterfly Sit-up"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Moffi","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1477","name":"Tire-bouchon assis (Seated Corkscrew)","description":"Position de départ :\nAsseyez-vous au sol en plaçant vos mains derrière vous pour vous stabiliser. Inclinez légèrement le buste vers l'arrière, décollez les pieds du sol et fléchissez légèrement les genoux.\n\nExécution :\n1. Ramenez les genoux vers la poitrine tout en effectuant une rotation vers un côté pour engager intensément les obliques.\n2. Tendez à nouveau les jambes vers l'avant sans poser les pieds au sol.\n3. Ramenez ensuite les genoux vers la poitrine en effectuant la rotation vers le côté opposé.\n4. Alternez ainsi de manière fluide et rythmée.\n\nConseils :\nGardez le gainage abdominal actif pendant toute la série et contrôlez l'extension des jambes.","region":"core","setup":["Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["Seated Corkscrew","seated-corkscrew","Tire-bouchon assis","Seated Corkscrew"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Moffi","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1478","name":"Crunch en lévitation","description":"Position de départ :\nAllongez-vous sur le dos, les genoux fléchis et les pieds à plat sur le sol. Croisez les bras sur la poitrine ou placez les mains légèrement derrière la tête sans tirer sur la nuque.\n\nExécution :\n1. Décollez le haut du torse et les omoplates du sol en contractant intensément le haut des abdominaux.\n2. Maintenez le bas du tronc et le bassin parfaitement immobiles et plaqués au sol.\n3. Marquez une pause en contraction maximale au sommet pendant 1 à 2 temps.\n4. Redescendez lentement avec contrôle avant d'enchaîner la répétition suivante.\n\nConseils :\nLe mouvement doit être court et vertical, sans tirer avec le cou, en concentrant tout l'effort sur les abdominaux.","region":"core","setup":["Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["Levitation Crunch","levitation-crunch","Levitation Crunch"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Moffi","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1479","name":"Sit-up avec coup de coude (Sit Up Elbow Thrust)","description":"Position de départ :\nAllongez-vous sur le dos sur un tapis, genoux fléchis, pieds au sol et mains en garde près du visage.\n\nExécution :\n1. Relevez le buste de manière dynamique et explosive grâce à la contraction des abdominaux.\n2. Au sommet du relevé, effectuez une rotation du tronc et projetez énergiquement le coude vers l'avant et en diagonale.\n3. Revenez au centre et redescendez le dos au sol avec contrôle.\n4. Répétez en alternant le coup de coude du côté opposé à chaque répétition.\n\nConseils :\nLiez la montée du buste à la frappe du coude pour combiner flexion et rotation du tronc.","region":"core","setup":["Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["Sit Up Elbow Thrust","sit-up-elbow-thrust","Relevé de buste avec poussée du coude","Sit Up Elbow Thrust"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Moffi","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1489","name":"Plank Jacks (gainage avec sauts de jambes)","description":"En position de planche haute, effectuez des sauts d'écartement et de rapprochement des pieds (jumping jacks) tout en gardant le buste et le bassin parfaitement stables.","region":"core","setup":["Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["Plank Jacks","plank-jacks"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"jayninja","translationLicense":"CC-BY-SA-4.0","translationAuthor":"jayninja"},
  {"id":"1514","name":"Marche latérale","description":"La marche latérale, également appelée pas de côté ou marche en squat, est un type d'exercice où vous vous déplacez sur le côté en position de squat. Elle peut se pratiquer avec ou sans élastique de résistance. Ces exercices renforcent les abducteurs de la hanche, les fessiers et d'autres muscles stabilisateurs.","region":"lower_body","setup":[],"muscles":["Fessiers"],"search":["Lateral Walk","lateral-walk"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"cozyGalvinism","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1516","name":"Équilibre sur les mains libre (Handstand)","description":"Équilibre libre sur les mains sans support mural : verrouillez les coudes, engagez les deltoïdes et maintenez l'alignement par des micro-ajustements des doigts au sol.","region":"upper_body","setup":["Tapis de sol"],"muscles":["Épaules"],"search":["Handstand","handstand"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Fittness69","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Fittness69"},
  {"id":"1529","name":"Pointes de pieds à la barre (toes to bar)","description":"Le nom « toes to bar » (pointes de pieds à la barre) dit tout : cet exercice, dans lequel vous êtes suspendu à une barre de traction, consiste à amener vos pointes de pieds vers la barre, en direction de votre visage. Cela sollicite vraiment vos abdominaux. Le « toes to bar » est populaire dans les programmes de fitness fonctionnel comme Freeletics et CrossFit, et c'est un exercice efficace pour travailler la tablette de chocolat.","region":"core","setup":["Barre de traction"],"muscles":["Tronc / Sangle abdominale"],"search":["Toes-to-Bar","toes-to-bar"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"florian.bussmann","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1536","name":"Étirement des deltoïdes","description":"Amenez un bras tendu en travers de la poitrine à hauteur d'épaules et utilisez l'autre bras pour exercer une pression douce et étirer le deltoïde postérieur.","region":"upper_body","setup":[],"muscles":["Épaules"],"search":["Cross-Body Shoulder Stretch","delt-stretch"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Expenses7000","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Expenses7000"},
  {"id":"1537","name":"Suspension isométrique en haut de traction","description":"Maintenez la position haute ou médiane d'une traction à la barre fixe de façon statique pendant la durée indiquée.","region":"upper_body","setup":["Barre de traction"],"muscles":["Biceps","Dos"],"search":["Pull-Up Isometric Hold","pull-up-isometric-hold"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"DiscoCop","translationLicense":"CC-BY-SA-4.0","translationAuthor":"DiscoCop"},
  {"id":"1545","name":"Traction de l'archer","description":"La traction de l'archer est un exercice avancé au poids du corps qui renforce votre dos et vos biceps, servant de progression vers la traction à un bras. Elle tient son nom de la position de « tir à l'arc » que prend votre corps en haut du mouvement. Voici comment la réaliser :\n\nPrise : Saisissez une barre de traction avec une prise en pronation plus large que la largeur des épaules.\nPosition de départ : Suspendez-vous, bras complètement tendus, en gainant la sangle abdominale et en gardant vos omoplates abaissées.\nLe tirage : Tirez votre corps vers une main, comme pour une traction classique. En même temps, tendez l'autre bras sur le côté, en le gardant aussi droit que possible. Votre menton doit venir vers la main qui tire.\nMaintien et descente : Maintenez brièvement la position haute où un bras est fléchi et tire, et l'autre est tendu. Redescendez lentement à la position de départ, en gardant le contrôle.\nAlternez : Répétez le mouvement en tirant vers la main opposée. La clé de cet exercice est de garder le bras d'assistance aussi droit que possible afin de maximiser la charge sur le bras qui travaille. Cela en fait un exercice exigeant mais efficace pour la force de tirage unilatérale.","region":"upper_body","setup":["Barre de traction"],"muscles":["Dos"],"search":["Archer Pull-Up","archer-pull-up"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Antsy6277","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1551","name":"Pompe","description":"La pompe est un exercice fondamental au poids du corps qui sollicite les pectoraux, les bras et les épaules tout en mobilisant la sangle abdominale pour la stabilité. Elle ne nécessite aucun matériel et est excellente pour développer la force du haut du corps.\nInstructions :\n\nCommencez en position de planche, les mains placées légèrement plus écartées que la largeur des épaules, les pieds joints et le corps aligné de la tête aux talons.\nEngagez votre sangle abdominale et abaissez votre corps en pliant les coudes, en les gardant près du corps ou légèrement écartés vers l'extérieur.\nDescendez jusqu'à ce que votre poitrine touche presque le sol, tout en maintenant une colonne vertébrale neutre.\nPoussez sur vos paumes pour revenir à la position de départ en tendant complètement les bras.","region":"upper_body","setup":[],"muscles":["Poitrine"],"search":["Push-Up","push-up"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Settebello","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1554","name":"Pompe avec applaudissement","description":"La pompe avec applaudissement est un mouvement explosif du haut du corps qui développe la puissance et la force des fibres rapides. Elle ajoute un défi pliométrique à la pompe classique en exigeant que les mains quittent le sol au milieu de la répétition.\n\nCommencez dans une solide position de pompe, les mains légèrement plus écartées que la largeur des épaules et la sangle abdominale gainée\nAbaissez votre corps puis poussez de manière explosive contre le sol avec assez de force pour décoller vos mains.\nTapez rapidement vos mains l'une contre l'autre à hauteur de poitrine avant de les replacer au sol.\nRéceptionnez-vous avec les coudes souples pour absorber l'impact et enchaînez immédiatement avec la répétition suivante","region":"upper_body","setup":[],"muscles":["Poitrine"],"search":["Clap Push-Up","clap-push-up","Clap Push-Up","Pompe claquée"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Settebello","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1572","name":"Bird Dog","description":"Le Bird Dog est un exercice de stabilité du tronc qui améliore l'équilibre, la coordination et l'alignement de la colonne vertébrale. C'est un mouvement à faible impact, idéal pour renforcer la chaîne postérieure et améliorer le contrôle fonctionnel global.\n\nCommencez à quatre pattes, les mains sous les épaules et les genoux sous les hanches, en gardant la colonne en position neutre.\nTendez simultanément le bras droit vers l'avant et la jambe gauche vers l'arrière, en gardant les hanches bien parallèles.\nMarquez une courte pause en pleine extension tout en engageant les abdominaux et les fessiers.\nRevenez à la position de départ et répétez du côté opposé","region":"full_body","setup":["Tapis de sol"],"muscles":["Bas du dos","Fessiers"],"search":["Bird Dog","bird-dog"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Settebello","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1573","name":"Roue abdominale","description":"Position de départ : Agenouillez-vous au sol avec la roue abdominale placée devant vous.\nSaisissez la roue : Tenez fermement les poignées.\nDéroulez : Faites rouler lentement la roue vers l'avant en tendant le corps tout en gardant les abdominaux contractés.\nRevenez : Ramenez la roue vers vos genoux en maintenant la tension dans les abdominaux.","region":"core","setup":["Roue abdominale (Ab wheel)","Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["Ab Wheel Rollout","ab-wheel","Roulette abdominale"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"lhegedus","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1574","name":"Natation libre","description":"Position de départ :\nMettez-vous à l'eau et préparez-vous pour une séance de natation en continu dans la nage de votre choix (crawl, brasse).\n\nExécution :\n1. Nagez à une cadence régulière et soutenue sur la distance ou durée programmée.\n2. Engagez les grands dorsaux, les épaules et la sangle abdominale pour propulser le corps vers l'avant.\n3. Maintenez un alignement hydrodynamique constant et une respiration rythmée.","region":"upper_body","setup":[],"muscles":["Dos","Épaules"],"search":["Swimming","schwimmen"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"delta@romeo","translationLicense":"CC-BY-SA-4.0","translationAuthor":"delta@romeo"},
  {"id":"1576","name":"Snap Down","description":"Position de départ :\nDebout, tendez les deux bras au-dessus de la tête et montez sur la pointe des pieds en vous grandissant au maximum.\n\nExécution :\n1. Abaissez les bras de façon explosive tout en fléchissant instantanément hanches et genoux pour vous immobiliser en position athlétique basse.\n2. Amortissez la réception sur toute la surface des pieds, torse droit et abdominaux gainés.\n3. Marquez un temps d'arrêt stable avant de vous redresser.","region":"lower_body","setup":[],"muscles":["Fessiers","Quadriceps"],"search":["Snap Down","snap-down"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"mountain.potato","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1577","name":"Étirement Bretzel","description":"Position de départ :\nAllongez-vous sur le côté sur un tapis. Fléchissez la jambe supérieure à 90 degrés vers l'avant au sol et maintenez-la plaquée avec la main inférieure.\n\nExécution :\n1. Pliez le genou inférieur vers l'arrière et attrapez la cheville ou le pied avec la main supérieure.\n2. En expirant, faites pivoter lentement les épaules et le haut du dos vers le sol pour ouvrir la cage thoracique.\n3. Gardez le genou supérieur en contact permanent avec le sol.\n4. Maintenez la position 20 à 30 secondes en respirant profondément, puis changez de côté.","region":"lower_body","setup":["Tapis de sol"],"muscles":["Fessiers","Quadriceps"],"search":["Bretzel Stretch","bretzel-stretch"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"mountain.potato","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1578","name":"Charnière de hanche (Hip Hinge)","description":"Description de l'exercice de charnière de hancheLa charnière de hanche est un schéma de mouvement fondamental qui consiste à se pencher au niveau des hanches tout en gardant la colonne en position neutre. Elle est couramment utilisée dans des exercices comme le soulevé de terre, le swing avec kettlebell et le good morning. Pour effectuer une charnière de hanche :    Position de départ : Tenez-vous debout, les pieds écartés de la largeur des hanches et les genoux légèrement fléchis.    Basculez au niveau des hanches : Poussez les hanches vers l'arrière tout en gardant le dos droit. Votre buste doit s'incliner vers l'avant et votre poitrine doit rester relevée.    Phase de descente : Continuez à basculer jusqu'à ce que votre buste soit presque parallèle au sol, ou jusqu'à ce que vous ressentiez un étirement dans les ischio-jambiers.    Retour à la position debout : Poussez dans les talons et propulsez les hanches vers l'avant pour revenir à la position de départ.","region":"lower_body","setup":[],"muscles":["Fessiers","Ischio-jambiers"],"search":["Hip Hinge","hip-hinge","Charnière de hanche","Hip Hinge"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"mountain.potato","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1579","name":"Test Bronco (course navette)","description":"Test de condition physique pour le rugby. 5 séries de courses navettes de 20 m, 40 m et 60 m (20 yd, 45 yd, 65 yd / repère lointain à 45 yd)\nÀ réaliser le plus vite possible","region":"lower_body","setup":[],"muscles":["Mollets","Quadriceps"],"search":["Bronco Test","bronco","Bronco","Test Bronco"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"MU5H","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1584","name":"Marche ou course sur place","description":"Position de départ:\nTenez-vous debout, pieds écartés de la largeur des hanches, genoux souples, buste droit et sangle abdominale légèrement engagée. Pliez les coudes à 90 degrés le long du corps.\n\nExécution:\nMontez un genou vers la hauteur des hanches puis reposez le pied en douceur tout en montant le genou opposé. Coordonnez vos bras de manière rythmée et opposée aux jambes (mouvement naturel de course). Conservez un rythme régulier de marche ou accélérez progressivement en un trot léger sur place.\n\nConseils:\n- Atterrissez en douceur sur l'avant du pied en déroulant vers le talon pour amortir les chocs.\n- Gardez le dos droit sans vous pencher en avant ou en arrière.","region":"lower_body","setup":[],"muscles":["Mollets","Quadriceps"],"search":["March or Jog in Place","march-or-jog-in-place"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"MrAlfaRobot","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1589","name":"Étirement des jambes et des hanches","description":"Routine d'étirements doux ciblant les ischio-jambiers, les quadriceps et les fléchisseurs de la hanche pour améliorer la souplesse du bas du corps.","region":"lower_body","setup":["Tapis de sol"],"muscles":["Fessiers","Ischio-jambiers"],"search":["Leg and hip stretch","leg-and-hip-stretch"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"MrAlfaRobot","translationLicense":"CC-BY-SA-4.0","translationAuthor":"MrAlfaRobot"},
  {"id":"1590","name":"Étirement des bras et de la nuque","description":"Debout ou assis, étirez les bras au-dessus de la tête puis inclinez doucement la tête sur le côté pour détendre la nuque, les trapèzes et les épaules.","region":"upper_body","setup":[],"muscles":["Cou","Dos"],"search":["Arm and neck stretch","arm-and-neck-stretch"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"MrAlfaRobot","translationLicense":"CC-BY-SA-4.0","translationAuthor":"MrAlfaRobot"},
  {"id":"1591","name":"Respiration diaphragmatique profonde","description":"Assis ou debout dans une posture relâchée, inspirez profondément par le nez en gonflant le ventre, puis expirez lentement par la bouche pour abaisser le niveau de stress.","region":"core","setup":[],"muscles":["Tronc / Sangle abdominale"],"search":["Deep breathing (standing or seated)","deep-breathing-standing-or-seated"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"MrAlfaRobot","translationLicense":"CC-BY-SA-4.0","translationAuthor":"MrAlfaRobot"},
  {"id":"1592","name":"Méditation guidée ou libre","description":"Pratique de méditation guidée ou silencieuse en posture assise confortable, axée sur la respiration consciente et le relâchement mental.","region":"core","setup":[],"muscles":["Bas du dos"],"search":["Guided or free meditation","guided-or-free-meditation"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"MrAlfaRobot","translationLicense":"CC-BY-SA-4.0","translationAuthor":"MrAlfaRobot"},
  {"id":"1605","name":"Exercice d'adduction de Copenhague","description":"Allongez-vous sur le côté, le coude placé directement sous l'épaule, comme dans une position de planche latérale. Posez la jambe supérieure sur un banc, l'intérieur du pied ou de la cheville reposant dessus. Soulevez les hanches et maintenez le corps en ligne droite tout en gardant la jambe inférieure décollée du sol. Cet exercice active fortement les adducteurs de la jambe supérieure tout en sollicitant également le tronc et les stabilisateurs de la hanche.","region":"lower_body","setup":["Banc plat"],"muscles":["Adducteurs"],"search":["Copenhagen Adduction Exercise","copenhagen-adduction-exercise"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"RiccaBaro","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1606","name":"Élévations de bras (T/Y/I)","description":"Tenez-vous debout, bien droit, les pieds écartés de la largeur des hanches, les abdominaux engagés et les bras relâchés le long du corps. À partir de cette position, effectuez trois élévations de bras différentes pour cibler les épaules et le haut du dos :\n\nÉlévation en T : Levez les bras tendus sur les côtés jusqu'à ce qu'ils soient parallèles au sol, en formant un « T ».\nÉlévation en Y : Levez les bras vers le haut à un angle d'environ 45° par rapport au corps pour former un « Y ».\nÉlévation en I : Levez les bras tendus au-dessus de la tête, rapprochés l'un de l'autre, en formant un « I ».\n\nGardez la colonne en position neutre, évitez de cambrer le bas du dos et bougez lentement et de manière contrôlée. Concentrez-vous sur le rapprochement des omoplates et gardez les épaules basses, éloignées des oreilles.","region":"upper_body","setup":[],"muscles":["Dos","Épaules"],"search":["Arm Raises (T/Y/I)","arm-raises-t-y-i"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"WiNNiE","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1607","name":"Tractions typewriter","description":"Suspendez-vous à une barre de traction en prise pronation, légèrement plus large que la largeur des épaules. Tirez-vous vers le haut jusqu'à ce que votre menton dépasse la barre. En position haute, au lieu de redescendre tout droit, déplacez votre corps d'un côté en tendant un bras tout en gardant l'autre bras fléchi. Passez en douceur d'un côté à l'autre, comme le mouvement d'une machine à écrire, avant de redescendre. Cet exercice augmente le temps sous tension et renforce le grand dorsal, les biceps et les épaules tout en développant la force de tirage unilatérale.","region":"upper_body","setup":["Barre de traction"],"muscles":["Dos"],"search":["Typewriter Pull-Up","typewriter-pull-ups"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"tenebrizz","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1608","name":"Curl biceps au poids du corps","description":"Placez-vous sous une barre droite (à hauteur de taille ou de poitrine environ). Saisissez la barre paumes tournées vers vous (prise supination), les mains écartées d'environ la largeur des épaules. Penchez-vous en arrière, bras tendus, de sorte que votre corps forme un angle avec le sol. En gardant les coudes hauts et près de la barre, tirez le haut du corps vers la barre en fléchissant les coudes, comme pour un curl biceps. Redescendez de manière contrôlée. Gardez les abdominaux contractés et le mouvement lent pour maximiser la tension sur les biceps.","region":"upper_body","setup":["Barre de traction"],"muscles":["Biceps"],"search":["Bodyweight Biceps Curl","bodyweight-biceps-curl"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"tenebrizz","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1670","name":"Balancements de jambe (avant-arrière)","description":"Tenez-vous bien droit à côté d'un mur ou d'un support stable. Balancez une jambe vers l'avant et vers l'arrière dans un mouvement contrôlé, en gardant le torse droit et les abdominaux gainés. Alternez les jambes après avoir terminé les répétitions.","region":"full_body","setup":["Mur"],"muscles":["Ischio-jambiers","Tronc / Sangle abdominale"],"search":["Leg Swings (Front–Back)","leg-swings-frontback"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Jhonatan","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1679","name":"Wall angels (anges au mur)","description":"L'exercice des wall angels cible principalement les muscles du haut du dos et des épaules, ce qui aide à améliorer la posture, la mobilité des épaules et le contrôle des omoplates.","region":"upper_body","setup":["Mur"],"muscles":["Dos"],"search":["Wall Angels","wall-angels"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"bbayuwega","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1680","name":"Étirement en figure quatre assis","description":"Asseyez-vous sur un banc. Les pieds à plat sur le sol. Placez votre cheville gauche sur votre genou droit. Votre genou droit reste à plat. Gardez le dos droit. Poussez doucement votre genou gauche vers le bas.","region":"lower_body","setup":["Chaise / Surface surélevée"],"muscles":["Fessiers"],"search":["Seated Figure Four","seated-figure-four"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"ricardodavidrd","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1695","name":"Tractions (prise large)","description":"Exécution\n\nPhase de tirage (concentrique) :\n\nTirez vos coudes vers le bas et légèrement en arrière, en amenant votre poitrine vers la barre.\nConcentrez-vous sur le fait de mener le mouvement avec la poitrine, pas avec le menton.\nGardez vos épaules abaissées (évitez de hausser les épaules).\n\nPosition haute :\n\nLe menton doit dépasser la barre (ou au moins atteindre son niveau).\nMarquez une brève pause avec une contraction du grand dorsal.","region":"upper_body","setup":["Barre de traction"],"muscles":["Dos"],"search":["Wide-Grip Pull-Up","pull-ups-wide-grip"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"daiben","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1696","name":"Tractions (prise neutre)","description":"Exécution\n\nPhase de traction (concentrique) :\n\nTirez vos coudes vers le bas et l'arrière, en amenant votre poitrine vers vos mains.\nGardez les épaules basses et rétractées (évitez de hausser les épaules).\nConcentrez-vous sur la contraction du grand dorsal et du haut du dos en position haute.\n\nPosition haute :\n\nLe menton doit dépasser ou atteindre le niveau de vos mains.\nMarquez une courte pause et contractez fortement le grand dorsal.","region":"upper_body","setup":["Barre de traction"],"muscles":["Dos"],"search":["Neutral-Grip Pull-Up","pull-ups-neutral-grip"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"daiben","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1704","name":"L-sit groupé (tuck L-sit)","description":"Le tuck L-sit est un maintien au poids du corps où vous vous soutenez sur des barres parallèles, des parallettes ou le sol avec les bras tendus, tout en ramenant vos genoux vers votre poitrine. Vos hanches restent levées, votre colonne reste droite et vos pieds flottent au-dessus du sol. L'objectif est de garder la sangle abdominale gainée, les épaules abaissées et les bras verrouillés tout en maintenant la position groupée. C'est un maintien statique très exigeant pour les abdominaux et stabilisateur pour les épaules, souvent utilisé comme progression vers le L-sit complet.","region":"core","setup":["Parallettes"],"muscles":["Tronc / Sangle abdominale"],"search":["Tuck L-sit","tuck-l-sit"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"clafal","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1710","name":"Étirement du billot de boucher (butcher's block)","description":"Agenouillez-vous, les mains jointes\nPosez les coudes sur un banc devant vous et abaissez la poitrine vers le bas\nGardez les coudes fléchis avec une bonne posture et maintenez la position","region":"upper_body","setup":["Banc plat","Tapis de sol"],"muscles":["Dos"],"search":["Butchers Block Stretch","butchers-block-stretch"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Croak6728","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1711","name":"Étirement du dormeur (sleeper stretch)","description":"Allongez-vous sur le côté de façon à reposer un peu de poids sur votre omoplate pour la maintenir immobile\nTendez votre bras à 90 degrés devant vous, reposant sur le sol ou le tapis\nLevez votre main avec votre coude de sorte que vos doigts pointent vers le plafond et votre paume vers vos pieds\nEn gardant votre coude immobile, abaissez doucement votre paume vers le sol","region":"upper_body","setup":["Tapis de sol"],"muscles":["Épaules"],"search":["Sleeper Stretch","sleeper-stretch"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Croak6728","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1712","name":"Étirement en flexion horizontale de l'épaule","description":"Levez le bras sur le côté en posant la main sur un mur ou un encadrement de porte à côté de vous, à hauteur d'épaule\nTournez le corps à l'opposé du bras pour étirer les pectoraux, aussi loin que possible sans inconfort","region":"upper_body","setup":["Mur"],"muscles":["Poitrine"],"search":["Horizontal Shoulder Flexion Stretch","horizontal-shoulder-flexion-stretch"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Croak6728","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1713","name":"Étirement des pectoraux dans l'encadrement de porte","description":"Placez l'avant-bras à la verticale contre un encadrement de porte ou un objet fixe, à hauteur de la tête\nAvancez d'un pas au-delà du bras, en le maintenant immobile contre l'objet, afin d'étirer les pectoraux","region":"upper_body","setup":["Mur"],"muscles":["Poitrine"],"search":["Doorway Pectoral Stretch","doorway-pectoral-stretch"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Croak6728","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1716","name":"Pompe scapulaire inclinée","description":"Placez vos mains sur le banc en position de pompe\nÉloignez votre poitrine du banc pour écarter vos omoplates\nEn gardant les coudes tendus, abaissez votre poitrine vers le banc de sorte que vos omoplates se rapprochent\nÉloignez de nouveau votre poitrine du banc","region":"upper_body","setup":["Banc plat"],"muscles":["Poitrine"],"search":["Incline Scapular Push-Up","incline-shoulder-press-up","Pompe inclinée pour les épaules"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Croak6728","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1733","name":"Squat isométrique jusqu'à l'échec","description":"Squat isométrique jusqu'à l'échec : une technique d'entraînement en force\nDéfinition\nLe squat isométrique jusqu'à l'échec est une variante de l'exercice du squat dans laquelle vous maintenez une position de squat statique à un angle précis, en conservant la position jusqu'à ce que vos muscles ne puissent plus soutenir la contraction.","region":"lower_body","setup":[],"muscles":["Fessiers","Quadriceps"],"search":["Isometric Squat to Failure","isometric-squat-to-failure"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Tierrasverdes","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1738","name":"Tractions en prise neutre ou rowings TRX","description":"Traction : tirage vertical — sollicite davantage le grand dorsal (largeur du dos).\nRowing TRX : tirage horizontal — sollicite davantage les rhomboïdes et les trapèzes (épaisseur du milieu du dos et posture).","region":"upper_body","setup":["Barre de traction"],"muscles":["Dos"],"search":["Neutral-grip pull-ups or TRX rows","neutral-grip-pull-ups-or-trx-rows"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"54str","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1739","name":"Shrimp squat","description":"Squat unilatéral au poids du corps où une jambe est fléchie vers l'arrière, pied tenu par la main, en descendant sur l'autre jambe jusqu'à effleurer le sol du genou libre.","region":"lower_body","setup":[],"muscles":["Fessiers","Quadriceps"],"search":["Shrimp Squat","shrimp-squad"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Happy","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Happy"},
  {"id":"1740","name":"Pont fessier sur une jambe","description":"Allongé sur le dos, un pied à plat au sol et l'autre jambe tendue, montez les hanches en poussant sur le talon pour contracter le fessier unilatéralement.","region":"lower_body","setup":["Tapis de sol"],"muscles":["Fessiers"],"search":["Single-Leg Glute Bridge","single-leg-glute-bridge"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Happy","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Happy"},
  {"id":"1741","name":"Tractions en L-Sit","description":"Maintenez les jambes tendues à l'horizontale en L-sit tout en effectuant des tractions à la barre fixe, combinant force de tirage et gainage intense.","region":"full_body","setup":["Barre de traction"],"muscles":["Dos","Tronc / Sangle abdominale"],"search":["L-Sit Pull-Ups","l-sit-pull-ups"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Happy","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Happy"},
  {"id":"1742","name":"Back Lever (planche dorsale)","description":"Figure de callisthénie suspendue à la barre ou aux anneaux : le corps est maintenu tendu à l'horizontale, face tournée vers le sol, bras tendus derrière le buste.","region":"full_body","setup":["Barre de traction"],"muscles":["Bas du dos","Dos"],"search":["Back Lever","back-lever"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Happy","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Happy"},
  {"id":"1743","name":"Essuie-glaces suspendu","description":"Position de départ :\nSuspendez-vous à une barre de traction avec une prise en pronation à la largeur des épaules. Engagez les dorsaux et la sangle abdominale, puis levez les jambes tendues jusqu'à ce que vos pieds pointent vers la barre ou le plafond.\n\nExécution :\n1. En gardant les jambes jointes et tendues, faites-les pivoter lentement vers la gauche selon un arc de cercle contrôlé, à la manière d'un essuie-glace.\n2. Revenez au centre vertical en contractant puissamment les obliques et les abdominaux.\n3. Basculez ensuite les jambes vers la droite avec le même contrôle et continuez d'alterner de façon rythmée.\n\nConseils :\nContrôlez chaque répétition sans utiliser d'élan ; fléchissez légèrement les genoux si la version jambes tendues est trop difficile.","region":"core","setup":["Barre de traction"],"muscles":["Tronc / Sangle abdominale"],"search":["Hanging Windshield Wipers","windshield-wipers","Essuie-glaces","Hanging Windshield Wipers"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Happy","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1766","name":"Planche avec extension du bras","description":"Position de départ :\nInstallez-vous en planche sur les avant-bras, les coudes sous les épaules et les pieds légèrement plus écartés que les hanches pour assurer une base stable. Gainez fermement la sangle abdominale et les fessiers pour maintenir le corps en ligne droite.\n\nExécution :\n1. Décollez un bras du sol lentement et tendez-le droit devant vous à hauteur d'épaule.\n2. Maintenez l'extension pendant 1 à 2 secondes en empêchant toute rotation ou inclinaison du bassin.\n3. Reposez l'avant-bras avec contrôle et répétez immédiatement avec l'autre bras en alternance.\n\nConseils :\nCet exercice cible l'anti-rotation : conservez les hanches et les épaules parfaitement parallèles au sol.","region":"core","setup":["Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["Plank Reach","plank-reach","Plank Reach","Gainage avec bras tendu"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1772","name":"Crunch inversé","description":"Position de départ :\nAllongez-vous sur le dos sur un tapis, les bras le long du corps et les paumes au sol pour vous stabiliser. Levez les jambes avec les genoux et les hanches fléchis à 90 degrés.\n\nExécution :\n1. Contractez les abdominaux pour ramener les genoux vers la poitrine.\n2. En fin de mouvement, enroulez le bassin pour décoller les fessiers et le bas du dos de quelques centimètres du sol.\n3. Marquez une pause d'une à deux secondes en contraction maximale en haut.\n4. Redescendez lentement et avec contrôle le bassin jusqu'à la position de départ.\n\nConseils :\nN'utilisez aucun élan des jambes ; concentrez-vous sur l'enroulement de la colonne par les abdominaux.","region":"core","setup":["Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["Reverse Crunch","reverse-crunch","Crunch inversé","Crunch renversé"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"eufvksruh","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1774","name":"Dips sur chaise","description":"Position de départ :\nAsseyez-vous sur le bord avant d'une chaise robuste ou d'un banc. Placez vos mains de part et d'autre des hanches en agrippant le bord, doigts vers l'avant. Tendez les bras et avancez le bassin dans le vide devant l'assise. Gardez les genoux pliés (facile) ou les jambes tendues devant vous (plus difficile).\n\nExécution :\n1. Fléchissez les coudes vers l'arrière pour descendre lentement le corps verticalement.\n2. Descendez jusqu'à ce que les bras forment un angle d'environ 90 degrés, en gardant le dos très proche de la chaise.\n3. Poussez sur la paume des mains avec la force des triceps pour remonter en extension complète.\n\nConseils :\nGardez le dos près du bord de la chaise pour éviter une contrainte excessive sur les épaules.","region":"upper_body","setup":["Chaise / Surface surélevée"],"muscles":["Triceps"],"search":["Chair Dips","chair-dips","Dips sur chaise","Dips triceps sur banc","Chair dips"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"tinman","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1777","name":"Pompes en déficit","description":"Pompes réalisées avec les mains surélevées sur des blocs ou des poignées, permettant à la poitrine de descendre plus bas que le niveau des mains pour un étirement maximal.","region":"upper_body","setup":["Parallettes"],"muscles":["Poitrine"],"search":["Deficit Push-Ups","deficit-push-ups"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Rottekongen","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Rottekongen"},
  {"id":"1804","name":"Bascules en dorsiflexion de la cheville","description":"Position de départ :\nPlacez-vous en position de fente basse (un genou au sol et le pied avant bien à plat sur le sol).\n\nExécution :\n1. Poussez lentement le genou avant vers l'avant au-dessus des orteils en veillant à garder le talon fermement collé au sol.\n2. Atteignez l'amplitude maximale de flexion de la cheville et maintenez la position pendant 2 à 3 secondes.\n3. Revenez doucement en arrière et répétez ce mouvement de balancement avant de changer de jambe.\n\nConseils :\nLe talon ne doit jamais décoller du sol pour garantir une véritable mobilisation de l'articulation de la cheville.","region":"lower_body","setup":["Tapis de sol"],"muscles":["Mollets"],"search":["Ankle Dorsiflexion Rocks","ankle-dorsiflexion-rocks","Bascules en dorsiflexion","Mobilité cheville","Ankle Dorsiflexion Rocks"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Davidgj32","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1808","name":"Maintien en appui aux barres parallèles","description":"Position de départ :\nPlacez-vous entre les barres parallèles. Saisissez les barres en prise neutre et poussez sur les bras pour vous soulever en appui, bras tendus.\n\nExécution :\n1. Poussez activement dans les barres pour abaisser les épaules loin des oreilles (dépression des omoplates).\n2. Gainez les abdominaux et les fessiers, jambes tendues et jointes.\n3. Maintenez cette position isométrique stable pendant la durée requise avec une respiration contrôlée.\n4. Redescendez au sol avec précaution une fois le temps écoulé.\n\nConseils :\nNe vous affaissez pas dans les épaules ; maintenez un verrouillage solide des triceps et une posture fière.","region":"upper_body","setup":["Barres parallèles à dips"],"muscles":["Triceps","Épaules"],"search":["Parallel Bar Support Hold","parallel-bar-hold","Maintien aux barres parallèles","Support hold barres parallèles","Parallel Bar Hold"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Croak6728","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1809","name":"Hyperextension inversée","description":"Position de départ :\nAllongez-vous à plat ventre sur un banc plat ou une machine à hyperextensions inversées, les hanches au bord du banc et les jambes pendantes vers le sol. Tenez fermement le banc avec les mains pour stabiliser le haut du corps.\n\nExécution :\n1. Contractez les fessiers et les ischio-jambiers pour soulever les jambes vers l'arrière et le haut avec contrôle.\n2. Montez jusqu'à ce que les jambes soient alignées avec le tronc en serrant fort les fessiers en haut.\n3. Redescendez lentement les jambes vers la position de départ sans à-coups.\n\nConseils :\nNe cambrez pas exagérément les lombaires ; le mouvement doit résulter d'une pure extension de hanche.","region":"lower_body","setup":["Chaise romaine / Banc à lombaires"],"muscles":["Fessiers","Ischio-jambiers"],"search":["Reverse Hyperextension","reverse-hyperextension","Hyperextension inversée","Reverse Hyper","Reverse Hyperextension"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Croak6728","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1810","name":"Posture du sphinx","description":"Position de départ :\nAllongez-vous à plat ventre sur un tapis, jambes tendues à la largeur des hanches et dessus des pieds au sol. Placez vos avant-bras parallèles au sol, les coudes alignés directement sous les épaules et les paumes vers le bas.\n\nExécution :\n1. Pressez délicatement les avant-bras dans le sol pour décoller la poitrine et la tête dans une douce extension dorsale.\n2. Rapprochez les omoplates vers l'arrière et le bas, ouvrez la cage thoracique et regardez devant vous.\n3. Ancrez le pubis dans le sol et respirez profondément et calmement.\n4. Maintenez la posture pendant plusieurs respirations complètes avant de vous allonger doucement.\n\nConseils :\nCherchez l'ouverture et l'extension au niveau de la colonne thoracique plutôt qu'un pincement lombaire.","region":"core","setup":["Tapis de sol"],"muscles":["Bas du dos"],"search":["Sphinx Pose","sphinx","Sphinx","Posture du sphinx","Sphinx Pose"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Joculari","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1822","name":"Exercice du livre ouvert (Open Book)","description":"Position de départ :\nAllongez-vous sur le côté sur un tapis de sol, les hanches et les genoux fléchis à 90 degrés l'un sur l'autre pour verrouiller le bassin. Tendez les deux bras droit devant vous à hauteur de poitrine, paumes l'une contre l'autre.\n\nExécution :\n1. Inspirez et levez le bras supérieur vers le haut et l'arrière en décrivant un large arc de cercle, comme pour ouvrir un livre.\n2. Faites pivoter la colonne thoracique en suivant la main du regard, sans décoller les genoux l'un de l'autre.\n3. Expirez en fin de course pour ressentir l'ouverture de la cage thoracique et de l'épaule pendant 1 à 2 secondes.\n4. Inspirez et ramenez lentement le bras vers l'avant jusqu'à réunir les paumes.\n\nConseils :\nLa rotation doit s'effectuer exclusivement au niveau du haut du dos sans mouvement du bassin.","region":"full_body","setup":["Mur","Tapis de sol"],"muscles":["Dos","Tronc / Sangle abdominale"],"search":["Open Book Thoracic Mobility Stretch","open-book","Livre ouvert","Le livre ouvert","Open Book"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"teus_ergaster","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1823","name":"Coquille (Clamshell)","description":"Position de départ :\nAllongez-vous sur le côté sur un tapis, les hanches fléchies à 45 degrés et les genoux pliés à 90 degrés l'un sur l'autre, talons joints. Reposez votre tête sur le bras du bas et placez la main du haut sur votre hanche.\n\nExécution :\n1. En gardant les talons collés ensemble, ouvrez lentement le genou supérieur vers le haut comme une coquille qui s'ouvre.\n2. Montez le genou au maximum sans laisser le bassin basculer vers l'arrière.\n3. Contractez le moyen fessier pendant 1 à 2 secondes au sommet.\n4. Redescendez lentement le genou jusqu'à la position de départ.\n\nConseils :\nGardez le bassin bien vertical et perpendiculaire au sol tout au long du mouvement.","region":"lower_body","setup":["Tapis de sol"],"muscles":["Fessiers"],"search":["Clamshell","clamshell","Coquille","Clamshell","Coquille fessiers"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"teus_ergaster","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1827","name":"Pression abdominale à deux jambes","description":"Position de départ :\nAllongez-vous sur le dos, les hanches et les genoux fléchis à 90 degrés en position de table. Plaquez fermement le bas du dos contre le sol. Posez vos paumes de mains sur vos cuisses, juste au-dessus des genoux.\n\nExécution :\n1. Poussez de toutes vos forces avec vos mains contre vos cuisses tout en poussant simultanément vos cuisses contre vos mains.\n2. Créez un gainage isométrique intense sur l'ensemble de la sangle abdominale.\n3. Maintenez cette poussée maximale pendant 10 à 15 secondes sans bloquer votre respiration.\n4. Relâchez doucement la pression avant d'enchaîner la répétition suivante.\n\nConseils :\nLe bas du dos doit rester en contact continu avec le tapis tout au long de l'effort.","region":"core","setup":["Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["Double-Leg Abdominal Press","double-leg-abdominal-press","Pression abdominale à deux jambes","Double-Leg Abdominal Press"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"beagle","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1828","name":"Rentrée du ventre (Stomach Vacuum)","description":"Position de départ :\nAllongez-vous sur le dos, genoux pliés et pieds à plat sur le tapis. Posez vos doigts sur le bas-ventre pour ressentir le travail musculaire profond.\n\nExécution :\n1. Expirez complètement par la bouche pour vider l'air des poumons.\n2. Rentrez doucement votre nombril vers l'intérieur et le haut en direction de la colonne vertébrale.\n3. Gardez le bassin neutre et respirez superficiellement tout en maintenant le ventre rentré pendant 10 à 15 secondes.\n4. Relâchez progressivement et inspirez normalement avant de répéter.\n\nConseils :\nCe mouvement isole le muscle transverse de l'abdomen, garantissant un maintien viscéral optimal et un gainage profond.","region":"core","setup":["Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["Abdominal Draw-In Maneuver (ADIM)","abdominal-draw-in","Rentrée du ventre","Stomach Vacuum","Abdominal Draw-In"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"beagle","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1833","name":"Curl des ischio-jambiers avec sliders au sol","description":"Position de départ :\nAllongez-vous sur le dos, les talons posés sur des disques glissants (sliders) ou des serviettes. Montez le bassin en pont fessier pour aligner les genoux, le bassin et les épaules.\n\nExécution :\n1. En gardant le bassin surélevé, faites glisser lentement les talons vers l'avant jusqu'à ce que les jambes soient presque entièrement tendues.\n2. Sans poser les fessiers au sol, tirez vigoureusement sur les talons pour les ramener vers les fessiers en contractant les ischio-jambiers.\n3. Poussez le bassin vers le haut au retour sous les genoux.\n\nConseils :\nConservez les hanches hautes tout au long du mouvement pour maintenir une tension constante sur les ischio-jambiers.","region":"lower_body","setup":["Disques de glisse (Sliders)","Tapis de sol"],"muscles":["Ischio-jambiers"],"search":["Floor Glider Hamstring Curls","floor-glider-hamstring-curls","Curl ischio-jambiers sliders","Slider leg curl","Floor Glider Hamstring Curls"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1834","name":"Élévation trapèze inférieur (Trap-3)","description":"Position de départ :\nPenchez le buste en avant depuis les hanches à environ 45 degrés avec le dos plat. Posez une main sur votre genou ou un banc d'appui. Laissez pendre le bras actif vers le bas, pouce vers le haut, omoplate abaissée.\n\nExécution :\n1. En gardant le coude verrouillé tendu, levez le bras en diagonale vers l'avant et le haut à environ 15 à 30 degrés au-dessus de la tête.\n2. Gardez l'épaule basse loin de l'oreille pour recruter spécifiquement le trapèze inférieur (Trap-3).\n3. Marquez une pause d'une à deux secondes en contraction maximale en haut.\n4. Redescendez le bras lentement et avec contrôle à la position de départ.\n\nConseils :\nNe haussez pas l'épaule ; le mouvement doit cibler l'abaissement et la rotation supérieure de l'omoplate.","region":"upper_body","setup":[],"muscles":["Dos"],"search":["Trap-3 Raise","trap-3-raise","Élévation trapèze inférieur","Trap-3 Raise","Trap 3"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Croak6728","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1839","name":"Étirement autonome des fléchisseurs de hanche","description":"Un genou au sol en fente chevalier servant, avancez légèrement le bassin vers l'avant tout en contractant le fessier arrière pour étirer le psoas et les fléchisseurs de hanche.","region":"core","setup":["Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["Solo Hip Flexor Stretch","solo-hip-flexor-stretch"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Croak6728","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Croak6728"},
  {"id":"1840","name":"Étirement des ischios jambe fléchie","description":"Allongé sur le dos, attrapez l'arrière de la cuisse avec le genou légèrement fléchi et tendez progressivement la jambe vers le plafond pour étirer les ischio-jambiers en douceur.","region":"lower_body","setup":["Tapis de sol"],"muscles":["Ischio-jambiers"],"search":["Bent-Leg Hamstring Stretch","bent-leg-hamstring-stretch"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Croak6728","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Croak6728"},
  {"id":"1841","name":"Étirement des épaules en extension assis","description":"Position de départ : Asseyez-vous au sol avec les mains posées derrière vous, écartées de la largeur des épaules, doigts pointant vers l'arrière ou légèrement vers l'extérieur.\nExécution : Gardez les bras tendus et faites glisser le bassin et les pieds vers l'avant, amenant les épaules en extension jusqu'à ressentir un étirement confortable dans les deltoïdes antérieurs et la poitrine.\nConseils : Avancez uniquement jusqu'à une amplitude confortable sans douleur. Maintenez la position pendant 20 à 30 secondes en respirant calmement.","region":"upper_body","setup":["Tapis de sol"],"muscles":["Épaules"],"search":["Seated Shoulder Extension Stretch","seated-shoulder-extension-stretch"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Croak6728","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1843","name":"Étirement du papillon","description":"Position de départ : Asseyez-vous sur le sol le dos droit et joignez la plante de vos pieds, en laissant les genoux s'ouvrir sur les côtés.\nExécution : Tenez vos pieds avec les mains et rapprochez délicatement les talons vers votre bassin. Laissez vos genoux descendre vers le sol en expirant.\nConseils : Maintenez l'étirement pendant 20 à 30 secondes avec le dos droit, sans à-coups ni rebonds.","region":"lower_body","setup":["Tapis de sol"],"muscles":["Adducteurs"],"search":["Butterfly Stretch","butterfly-stretch"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Croak6728","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1844","name":"Étirement de la grenouille","description":"Position de départ : Mettez-vous à quatre pattes et écartez les genoux vers l'extérieur autant que possible. Descendez en appui sur les avant-bras, dos droit.\nExécution : En gardant la colonne vertébrale neutre, balancez lentement le bassin vers l'arrière en direction des talons jusqu'à ressentir un étirement profond dans les adducteurs.\nConseils : Effectuez un mouvement d'oscillation lent et contrôlé ou maintenez la position basse pendant 20 à 30 secondes en respirant calmement.","region":"lower_body","setup":["Tapis de sol"],"muscles":["Adducteurs"],"search":["Frog Stretch","frog-stretch"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Croak6728","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1845","name":"Good morning jambes écartées assis","description":"Position de départ : Asseyez-vous au sol en grand écart facial (position pancake), jambes tendues et orteils vers le plafond. Placez les mains derrière la tête.\nExécution : En gardant le dos droit, basculez le buste vers l'avant à partir des hanches en direction du sol jusqu'à ressentir un étirement marqué dans les adducteurs et les ischio-jambiers.\nConseils : Redressez-vous en contrôlant le mouvement avec les fessiers. Évitez d'arrondir exagérément la colonne.","region":"lower_body","setup":["Tapis de sol"],"muscles":["Adducteurs","Ischio-jambiers"],"search":["Seated Pancake Good Morning","seated-pancake-good-morning"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Croak6728","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1846","name":"Posture du cavalier (grand écart latéral)","description":"Placez-vous comme pour un squat, les pieds largement écartés et les orteils légèrement tournés vers l'extérieur.\nDescendez doucement dans un squat profond et large : vos hanches doivent passer sous le niveau de vos genoux.\nMaintenez la position pendant 3 à 5 secondes.\nRemontez de façon contrôlée et répétez autant de fois que nécessaire.","region":"lower_body","setup":[],"muscles":["Adducteurs","Quadriceps"],"search":["Horse Stance (Side Splits)","horse-stance-side-splits"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Croak6728","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1847","name":"L-sit jambes écartées","description":"Les jambes en position de selle assise, poussez votre corps vers le haut pour décoller du sol. Vos jambes doivent être horizontales et pointer droit vers l'extérieur. Vos bras doivent se trouver entre vos jambes.\nMaintenez la position de manière isométrique aussi longtemps que nécessaire.","region":"core","setup":["Parallettes"],"muscles":["Tronc / Sangle abdominale"],"search":["Straddle L-Sit","straddle-l-sit"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Croak6728","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1852","name":"L-sit","description":"Asseyez-vous au sol, les jambes serrées et les bras le long du corps. Poussez sur vos mains pour décoller votre corps du sol, en conservant la même position assise de sorte que vos jambes soient tendues et que vos pieds ne touchent pas le sol.\nMaintenez la position aussi longtemps que nécessaire.","region":"core","setup":["Parallettes"],"muscles":["Tronc / Sangle abdominale"],"search":["L-sit","l-sit","Équerre"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Croak6728","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1853","name":"L-Sit avec pieds au sol en appui","description":"Assis au sol ou en appui sur des barres parallèles, soulevez le bassin en gardant les talons au sol pour délester une partie du poids corporel, tout en maintenant un gainage actif du tronc.","region":"core","setup":["Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["L-Sit (Foot Supported)","l-sit-foot-supported"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Croak6728","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Croak6728"},
  {"id":"1854","name":"Automassage des mollets au rouleau","description":"Assis au sol, placez le rouleau de massage sous les mollets et faites rouler lentement de la cheville jusqu'au dessous du genou pour relâcher les tensions.","region":"lower_body","setup":["Rouleau de massage (Foam roller)","Tapis de sol"],"muscles":["Mollets"],"search":["Calves foam roller","calves-foam-roller"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Davidgj32","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Davidgj32"},
  {"id":"1855","name":"Automassage des ischios au rouleau","description":"Assis au sol, placez le rouleau de massage sous l'arrière des cuisses et faites rouler le corps des ischions jusqu'à l'arrière des genoux.","region":"lower_body","setup":["Rouleau de massage (Foam roller)","Tapis de sol"],"muscles":["Ischio-jambiers"],"search":["Hamstring Foam roller","hamstring-foam-roller"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Davidgj32","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Davidgj32"},
  {"id":"1856","name":"Automassage du jambier antérieur au rouleau","description":"En appui sur les mains et les genoux, placez le rouleau sous la face antérieure de la jambe et massez délicatement le long du muscle tibial antérieur.","region":"lower_body","setup":["Rouleau de massage (Foam roller)","Tapis de sol"],"muscles":["Mollets"],"search":["Foam Roller Anterior Tibialis","foam-roller-anterior-tibialis"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Davidgj32","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Davidgj32"},
  {"id":"1857","name":"Automassage de la bandelette ilio-tibiale au rouleau","description":"Allongé sur le côté, faites glisser le rouleau le long de la face externe de la cuisse entre la hanche et le genou pour relâcher le fascia lata et la bandelette ilio-tibiale.","region":"lower_body","setup":["Rouleau de massage (Foam roller)","Tapis de sol"],"muscles":["Fessiers"],"search":["Foam Roller Iliotibial band","foam-roller-iliotibial-band"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Davidgj32","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Davidgj32"},
  {"id":"1858","name":"Automassage des quadriceps au rouleau","description":"Allongé sur le ventre en appui sur les avant-bras, faites rouler le foam roller le long de la face antérieure des cuisses pour masser les quadriceps.","region":"lower_body","setup":["Rouleau de massage (Foam roller)","Tapis de sol"],"muscles":["Quadriceps"],"search":["Foam Roller Quadriceps","foam-roller-quadriceps"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Davidgj32","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Davidgj32"},
  {"id":"1859","name":"Automassage des fessiers au rouleau","description":"Assis sur le rouleau de massage, croisez une cheville sur le genou opposé et massez la zone fessière ciblée en effectuant de petits allers-retours lents.","region":"lower_body","setup":["Rouleau de massage (Foam roller)","Tapis de sol"],"muscles":["Fessiers"],"search":["Foam Roller Gluteus","foam-roller-gluteus"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Davidgj32","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Davidgj32"},
  {"id":"1860","name":"Automassage des adducteurs au rouleau","description":"Allongé sur le ventre, placez le rouleau de massage sous l'intérieur de la cuisse et roulez lentement du genou vers l'aine pour masser les adducteurs.","region":"lower_body","setup":["Rouleau de massage (Foam roller)","Tapis de sol"],"muscles":["Adducteurs"],"search":["Foam Roller Adductors","foam-roller-adductors"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Davidgj32","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Davidgj32"},
  {"id":"1861","name":"Étirement latéral du buste","description":"Debout, levez un bras au-dessus de la tête et inclinez le buste du côté opposé pour étirer la chaîne latérale, les obliques et les muscles intercostaux.","region":"full_body","setup":[],"muscles":["Dos","Tronc / Sangle abdominale"],"search":["Side stretch","side-stretch"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Davidgj32","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Davidgj32"},
  {"id":"1862","name":"Rotations articulaires des hanches","description":"Debout les mains sur les hanches, décrivez de grands cercles lents avec le bassin dans le sens horaire puis antihoraire pour déverrouiller les hanches.","region":"lower_body","setup":[],"muscles":["Fessiers"],"search":["Hip Circles","hip-circles"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Davidgj32","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Davidgj32"},
  {"id":"1863","name":"Croisement de hanche au sol","description":"Allongé sur le dos, bras en croix, basculez les deux jambes fléchies ou tendues d'un côté vers le sol tout en gardant les deux épaules plaquées pour détendre le bassin.","region":"lower_body","setup":["Tapis de sol"],"muscles":["Fessiers"],"search":["Hip Crossover","hip-crossover"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Davidgj32","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Davidgj32"},
  {"id":"1864","name":"Rotations de cheville","description":"Assis ou debout sur un pied, effectuez de lentes rotations circulaires complètes de la cheville dans les deux sens pour lubrifier l'articulation.","region":"lower_body","setup":[],"muscles":["Mollets"],"search":["Ankle Roll","ankle-roll"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Davidgj32","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Davidgj32"},
  {"id":"1867","name":"Étirement du psoas et des fléchisseurs de hanche","description":"En fente basse avec le genou arrière posé sur un tapis, maintenez le torse droit et poussez doucement la hanche vers l'avant pour ressentir l'étirement du fléchisseur de hanche.","region":"core","setup":["Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["Hip Flexor Stretch","hip-flexor-stretch"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Davidgj32","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Davidgj32"},
  {"id":"1868","name":"Fente avec rotation du buste","description":"En fente avant avec le genou arrière au sol, levez les bras et effectuez une rotation lente du torse vers le côté de la jambe avant pour ouvrir la cage thoracique.","region":"full_body","setup":["Tapis de sol"],"muscles":["Fessiers","Tronc / Sangle abdominale"],"search":["Lunge with Twist Stretch","lunge-with-twist-stretch"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Davidgj32","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Davidgj32"},
  {"id":"1869","name":"Étirement du fessier en quatre au sol (Figure four)","description":"Allongé sur le dos, posez la cheville droite sur le genou gauche et tirez la cuisse gauche vers la poitrine avec les mains pour étirer le grand et moyen fessier.","region":"lower_body","setup":["Tapis de sol"],"muscles":["Fessiers"],"search":["Lying Figure Four Stretch","lying-figure-four-stretch"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Davidgj32","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Davidgj32"},
  {"id":"1872","name":"Posture du pigeon (Pigeon stretch)","description":"En fente avant au sol, repliez la jambe avant sous le bassin avec le genou tourné vers l'extérieur et tendez la jambe arrière pour étirer les fessiers profonds et le piriforme.","region":"lower_body","setup":["Tapis de sol"],"muscles":["Fessiers"],"search":["Pigeon Stretch","pigeon-stretch"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Davidgj32","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Davidgj32"},
  {"id":"1873","name":"Étirement des quadriceps debout","description":"Debout sur une jambe, attrapez le cou-de-pied opposé et ramenez le talon vers le fessier en maintenant les genoux serrés et le bassin rétroversé.","region":"lower_body","setup":[],"muscles":["Quadriceps"],"search":["Quad Stretch","quad-stretch"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Davidgj32","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Davidgj32"},
  {"id":"1874","name":"Étirement du coureur en fente avant","description":"En position de fente du coureur, mains posées au sol de part et d'autre du pied avant, tendez la jambe arrière pour étirer la chaîne antérieure de la hanche.","region":"full_body","setup":["Tapis de sol"],"muscles":["Fessiers","Tronc / Sangle abdominale"],"search":["Runners Lunge Stretch","runners-lunge-stretch"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Davidgj32","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Davidgj32"},
  {"id":"1875","name":"Étirement debout de la bandelette ilio-tibiale","description":"Debout, croisez la jambe à étirer derrière l'autre jambe et inclinez le buste latéralement pour ressentir l'étirement sur la face externe de la cuisse et de la hanche.","region":"lower_body","setup":[],"muscles":["Fessiers"],"search":["Standing IT Band Stretch","standing-it-band-stretch"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Davidgj32","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Davidgj32"},
  {"id":"1876","name":"Étirement du mollet en appui contre le mur","description":"Les deux mains appuyées contre un mur, reculez une jambe tendue avec le talon plaqué au sol et avancez le bassin pour étirer le gastrocnémien.","region":"lower_body","setup":["Mur"],"muscles":["Mollets"],"search":["Supported Calf Stretch","supported-calf-stretch"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Davidgj32","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Davidgj32"},
  {"id":"1884","name":"Étirement en rotation interne en position shinbox","description":"Position de départ : Asseyez-vous au sol, les hanches et les genoux fléchis à un angle de 90 degrés.\nPlacement des jambes :\nPlacez une jambe devant vous (rotation externe) et l'autre jambe sur le côté ou derrière vous (rotation interne). Les tibias et les genoux doivent rester à plat sur le sol.\nLe mouvement :\nEn gardant les hanches bien parallèles, basculez le torse vers l'avant ou inclinez-le latéralement (d'un côté à l'autre) vers la jambe avant pour approfondir l'étirement.\nZones ciblées :\nÉtire les fessiers et le piriforme (jambe avant) ainsi que les fléchisseurs de la hanche et les quadriceps (jambe arrière). Sollicite la sangle abdominale et les obliques pendant la flexion latérale.\nObjectif : Améliore la mobilité de la hanche, en particulier les rotations interne et externe, et soulage les tensions dans le bas du dos.","region":"lower_body","setup":["Tapis de sol"],"muscles":["Fessiers"],"search":["Shinbox IR Stretch","shinbox-ir-stretch"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"teus_ergaster","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1886","name":"Abduction de hanche en décubitus dorsal","description":"Position de départ :\nAllongez-vous sur le dos (décubitus dorsal) sur un tapis, les jambes tendues et détendues. Les bras peuvent être placés le long du corps ou écartés sur les côtés pour plus de stabilité.\nLe mouvement :\nSoulevez légèrement une jambe du sol (en la gardant tendue ou avec une légère flexion). Déplacez-la latéralement vers l'extérieur, en l'éloignant de l'autre jambe, comme si vous enjambiez un petit obstacle.\nAmplitude de mouvement :\nDéplacez la jambe aussi loin que possible sans soulever le bassin ni faire tourner le torse, en ressentant un étirement à l'intérieur de la cuisse et de la hanche.\nRetour : Ramenez lentement la jambe à la position de départ par un mouvement contrôlé.\nObjectif : Améliore la mobilité latérale de la hanche (abduction) et renforce les muscles stabilisateurs du bassin.","region":"lower_body","setup":["Tapis de sol"],"muscles":["Fessiers"],"search":["Supine Hip Abduction","supine-hip-abduction"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"teus_ergaster","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1889","name":"Relevé de jambes sur banc décliné","description":"Installation : Allongez-vous sur un banc décliné, la tête en haut, et saisissez les poignées.\nLe départ : Tendez complètement les jambes en les gardant légèrement surélevées pour engager la sangle abdominale.\nLa montée : Soulevez vos jambes vers le plafond à l'aide des abdominaux, sans utiliser l'élan.\nLa contraction : Marquez une pause et contractez le bas des abdominaux en position haute.\nLe retour : Abaissez lentement vos jambes vers la position de départ en gardant le contrôle.","region":"core","setup":["Banc décliné"],"muscles":["Tronc / Sangle abdominale"],"search":["Decline Bench Leg Raise","decline-bench-leg-raise"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"nishant0712","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1902","name":"Pompes lestées","description":"Mise en place : Commencez en position de planche classique avec un disque de poids posé de façon stable sur le haut du dos.\nAlignement : Maintenez une ligne droite de la tête aux talons, en engageant la sangle abdominale pour éviter que le dos ne s'affaisse.\nExécution : Abaissez votre corps jusqu'à ce que la poitrine touche presque le sol, en gardant les coudes à quarante-cinq degrés.\nMontée : Poussez à travers les paumes pour revenir à la position de départ, en tendant complètement les bras.","region":"upper_body","setup":[],"muscles":["Poitrine"],"search":["Weighted push-ups","weighted-push-ups"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"nishant0712","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1906","name":"Pont fessier avec extension alternée des jambes","description":"Position de départ :\nAllongez-vous sur le dos sur un tapis, les genoux fléchis et les pieds posés sur les talons à la largeur du bassin. Placez les bras le long du corps.\n\nExécution :\nPoussez sur les talons pour soulever le bassin jusqu'à aligner les cuisses et le tronc. En maintenant le bassin en position haute, tendez une jambe vers l'avant dans le prolongement de la cuisse. Reposez le pied au sol et effectuez immédiatement la même extension avec l'autre jambe.\n\nConseils :\nGardez les fessiers et les abdominaux contractés en continu pour éviter que le bassin ne s'affaisse ou ne pivote lors des changements de jambe.","region":"lower_body","setup":["Tapis de sol"],"muscles":["Fessiers"],"search":["Glute Bridge with Alternating Leg Extension","hip-bridge","Pont fessier","Glute Bridge"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"cybro","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1907","name":"Fentes unilatérales (Split Squats)","description":"Position de départ :\nPlacez-vous en fente avec le pied avant à plat sur le sol et le pied arrière en appui sur la pointe des pieds. Mains sur les hanches, buste bien droit.\n\nExécution :\nFléchissez les deux genoux pour descendre verticalement jusqu'à ce que le genou arrière effleure le sol. Poussez sur le talon du pied avant pour remonter de manière fluide sans verrouiller l'articulation en haut. Enchaînez toutes les répétitions sur une jambe avant de changer de côté.\n\nConseils :\nGardez la sangle abdominale gainée et le buste vertical; le genou avant doit rester aligné avec la pointe du pied.","region":"lower_body","setup":[],"muscles":["Fessiers","Quadriceps"],"search":["Unilateral Lunges (Split Squats)","unilateral-lunges","Fentes unilatérales","Split Squats"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"cybro","translationLicense":"CC-BY-SA-4.0","translationAuthor":"cybro"},
  {"id":"1908","name":"Superman papillon au sol","description":"Position de départ :\nAllongez-vous à plat ventre sur un tapis de sol, jambes tendues. Entrecroisez les doigts derrière la tête en ouvrant largement les coudes vers l'extérieur.\n\nExécution :\nDécollez simultanément la tête, la poitrine et les coudes du sol en contractant les érecteurs du rachis et le haut du dos. Rapprochez activement les omoplates et montez les coudes le plus haut possible. Maintenez la contraction pendant 1 à 2 secondes, puis redescendez lentement avec contrôle.\n\nConseils :\nGardez le regard vers le sol pour maintenir la nuque alignée avec la colonne sans forcer sur les cervicales.","region":"core","setup":["Tapis de sol"],"muscles":["Bas du dos"],"search":["Butterfly Superman","butterfly-superman","Superman papillon","Butterfly Superman"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"cybro","translationLicense":"CC-BY-SA-4.0","translationAuthor":"cybro"},
  {"id":"1909","name":"Cercles avec les jambes au sol","description":"Position de départ :\nAllongez-vous sur le dos sur un tapis et levez les jambes à la verticale en gardant les genoux et les pieds serrés. Bras posés au sol le long du corps.\n\nExécution :\nDessinez de petits cercles réguliers et contrôlés dans une direction avec les deux jambes réunies, sur une amplitude modérée en sollicitant intensément les abdominaux. Réalisez les répétitions prévues puis inversez le sens de rotation.\n\nConseils :\nGardez le bas du dos fermement plaqué contre le sol tout au long de l'exercice pour protéger les lombaires.","region":"core","setup":["Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["Lying Leg Circles","leg-wheel","Roue avec les jambes","Lying Leg Circles"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"cybro","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1910","name":"Superman à genoux (Bird Dog)","description":"Position de départ :\nPlacez-vous à quatre pattes sur un tapis, mains sous les épaules et genoux sous les hanches. Dos plat et sangle abdominale engagée.\n\nExécution :\nTendez simultanément un bras vers l'avant et la jambe opposée vers l'arrière jusqu'à ce qu'ils soient alignés avec le tronc. Maintenez la position pendant 2 à 3 secondes en stabilisant le bassin. Revenez avec contrôle puis répétez du côté opposé.\n\nConseils :\nNe cambrez pas le bas du dos et veillez à ce que les hanches restent bien parallèles au sol.","region":"full_body","setup":["Tapis de sol"],"muscles":["Bas du dos","Fessiers"],"search":["Kneeling Superman (Bird Dog)","kneeling-superman","Superman à genoux","Bird Dog"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"cybro","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1911","name":"Planche du chat (Cat Plank)","description":"Position de départ :\nPlacez-vous à quatre pattes en appui sur les mains et les orteils. Décollez légèrement les genoux de quelques centimètres du sol.\n\nExécution :\nPoussez fort dans le sol avec les épaules pour arrondir le haut et le milieu du dos vers le plafond, à la manière d'un chat qui fait le gros dos. Rentrez le nombril et serrez puissamment la sangle abdominale. Maintenez cette position isométrique pendant la durée requise.\n\nConseils :\nGardez les genoux au ras du sol pendant tout le maintien et conservez une poussée constante des omoplates.","region":"full_body","setup":["Tapis de sol"],"muscles":["Quadriceps","Tronc / Sangle abdominale"],"search":["Cat Plank","cat-plank","Planche du chat","Cat Plank"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"cybro","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1912","name":"Rotation du tronc assis (Russian Twist)","description":"Position de départ :\nAsseyez-vous sur un tapis, genoux pliés. Penchez le torse vers l'arrière à environ 45 degrés en gardant le dos droit, puis décollez légèrement les pieds du sol pour trouver l'équilibre sur les fessiers.\n\nExécution :\nPivotez le buste de manière fluide d'un côté à l'autre en touchant le sol avec les mains près des hanches à chaque mouvement.\n\nConseils :\nGardez la poitrine haute et engagez les obliques à chaque torsion en évitant d'arrondir la colonne lombaire.","region":"core","setup":["Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["Seated Core Rotation (Russian Twist)","core-rotation","Rotation du tronc","Russian Twist"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"cybro","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1913","name":"Pont fessier à une jambe (Single-Leg Glute Bridge)","description":"Position de départ :\nAllongez-vous sur le dos sur un tapis. Fléchissez un genou et posez fermement le pied au sol près des fessiers. Tendez l'autre jambe vers l'avant dans l'alignement de la cuisse ou vers le plafond. Bras au sol le long du corps.\n\nExécution :\nPoussez fortement sur le talon d'appui pour monter le bassin jusqu'à aligner le torse et la cuisse. Serrez fort le grand fessier en haut pendant 1 seconde, puis redescendez avec contrôle sans poser complètement les fesses avant la répétition suivante. Réalisez toutes les répétitions d'un côté avant de changer.\n\nConseils :\nVeillez à garder le bassin bien horizontal sans laisser la hanche du côté libre s'affaisser.","region":"lower_body","setup":["Tapis de sol"],"muscles":["Fessiers"],"search":["Single-Leg Glute Bridge (Unilateral Hip Thrust)","unilateral-hip-thrust","Hip thrust unilatéral","Single-Leg Glute Bridge"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"cybro","translationLicense":"CC-BY-SA-4.0","translationAuthor":"cybro"},
  {"id":"1914","name":"Maintien isométrique aux barres parallèles (Support Hold)","description":"Position de départ :\nPlacez-vous entre les barres parallèles à dips. Saisissez les poignées et poussez fermement vers le bas pour tendre les bras et décoller les pieds du sol.\n\nExécution :\nMaintenez cette position de suspension statique les bras tendus sans verrouillage excessif des coudes. Abaissez activement les épaules en les éloignant des oreilles, bombez le torse et gainez les abdominaux et les fessiers. Tenez la position pendant la durée prévue.\n\nConseils :\nNe laissez pas les épaules remonter vers les oreilles; gardez une dépression scapulaire forte et continue.","region":"upper_body","setup":["Barres parallèles à dips"],"muscles":["Poitrine","Triceps"],"search":["Parallel Bar Support Hold","isometria-alle-parallele","Maintien isométrique aux barres parallèles","Support Hold barres parallèles"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1916","name":"Tuck planche (gainage planche groupée)","description":"Figure de gymnastique : en appui sur les mains bras tendus, soulevez le corps du sol avec les genoux groupés contre la poitrine en arrondissant le haut du dos.","region":"upper_body","setup":["Tapis de sol"],"muscles":["Poitrine","Épaules"],"search":["Tuck Planche","tuck-planche"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"ISSACS","translationLicense":"CC-BY-SA-4.0","translationAuthor":"ISSACS"},
  {"id":"1919","name":"Étirement intense des pectoraux","description":"L'avant-bras appuyé contre le montant d'une porte ou un poteau, pivotez le torse vers l'extérieur pour ouvrir la cage thoracique et étirer les fibres pectorales.","region":"upper_body","setup":["Banc plat"],"muscles":["Poitrine"],"search":["Extreme Chest Stretch","extreme-pec-stretch"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":null},
  {"id":"1920","name":"Étirement intense des épaules","description":"En appui bras tendu contre une surface ou suspendu, pivotez le buste pour créer un étirement profond et prolongé des faisceaux antérieurs et latéraux de l'épaule.","region":"upper_body","setup":[],"muscles":["Épaules"],"search":["Extreme Shoulder Stretch","extreme-shoulder-stretch"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":null},
  {"id":"1921","name":"Étirement intense du grand dorsal","description":"Saisissez un point d'ancrage fixe au-dessus de la tête, reculez les hanches et laissez tomber la poitrine vers le sol pour étirer intensément le grand dorsal.","region":"upper_body","setup":["Barre de traction"],"muscles":["Dos"],"search":["Extreme Lat Stretch","extreme-lat-stretch"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":null},
  {"id":"1933","name":"Crunch inversé","description":"Position de départ :\nAllongez-vous sur le dos sur un tapis de sol avec les bras le long du corps pour stabiliser la posture. Levez les jambes avec les hanches et les genoux fléchis à 90 degrés.\n\nExécution :\nContractez la sangle abdominale pour décoller le bassin du sol et enrouler les genoux vers la poitrine avec fluidité. Marquez un temps d'arrêt en haut pour accentuer la contraction, puis redescendez le bassin lentement sous contrôle sans poser les pieds par terre.\n\nConseils :\nEnroulez la colonne vertébrale sans donner d'à-coups avec les jambes et sans pousser excessivement sur les mains.","region":"core","setup":["Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["Reverse Crunch","abdominal-crunch","Crunch","Crunch abdominal","Crunch inversé","Reverse Crunch"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"amaesc","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1938","name":"Posture du chat-vache (Cat-Cow)","description":"Position de départ :\nInstallez-vous à quatre pattes sur un tapis de sol, mains sous les épaules et genoux sous les hanches. Colonne vertébrale en position neutre.\n\nExécution :\nInspirez en laissant le ventre descendre doucement vers le sol, relevez la poitrine et le regard vers l'avant dans la posture de la vache. Expirez profondément en rentrant le coccyx et en arrondissant tout le dos vers le plafond comme un chat qui s'étire, menton vers la poitrine. Alternez avec fluidité pendant 8 à 12 respirations.\n\nConseils :\nCoordonnez chaque mouvement avec le souffle et mobilisez la colonne vertébrale vertèbre par vertèbre.","region":"core","setup":["Tapis de sol"],"muscles":["Bas du dos","Tronc / Sangle abdominale"],"search":["Cat-Cow Stretch","cat-cow","Posture du chat-vache","Cat-Cow"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":null},
  {"id":"1939","name":"Rotations articulaires contrôlées du cou (Neck CARs)","description":"Position de départ :\nDebout ou assis bien droit, abaissez activement les épaules vers l'arrière et gainez le buste pour éviter toute compensation corporelle.\n\nExécution :\nRentrez le menton vers la poitrine. Faites glisser le menton le long de la clavicule droite, inclinez l'oreille droite vers l'épaule droite, puis basculez la tête vers l'arrière en décrivant un arc fluide sans pincer les cervicales. Poursuivez vers l'épaule gauche, ramenez le menton le long de la clavicule gauche et terminez au centre. Faites 3 cercles lents d'un côté puis inversez.\n\nConseils :\nRestez strictement dans une amplitude non douloureuse et veillez à ne bouger que le cou sans bouger le buste.","region":"upper_body","setup":[],"muscles":["Cou"],"search":["Controlled Articular Rotations for Neck (Neck CARs)","neck-cars","Neck CARs","Rotations articulaires contrôlées du cou"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":null},
  {"id":"1940","name":"Respiration diaphragmatique au sol","description":"Position de départ :\nAllongez-vous confortablement sur le dos sur un tapis, genoux pliés et pieds à plat. Posez une main sur la poitrine et l'autre sur l'abdomen juste sous les côtes.\n\nExécution :\nInspirez lentement et profondément par le nez en gonflant le ventre, de sorte que la main sur l'abdomen se soulève tandis que la main sur la poitrine reste quasiment immobile. Marquez une courte pause, puis expirez calmement et complètement par la bouche ou le nez en laissant le ventre redescendre. Effectuez 8 à 10 cycles respiratoires lents.\n\nConseils :\nRelâchez totalement les tensions dans les épaules et le cou; cette respiration active le système nerveux parasympathique et favorise la récupération.","region":"core","setup":["Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["Diaphragmatic Breathing (Belly Breathing)","diaphragmatic-breathing","Respiration diaphragmatique","Diaphragmatic Breathing"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":null},
  {"id":"1948","name":"Squat cosaque (Cossack Squat)","description":"Position de départ :\nÉcartez largement les jambes bien au-delà de la largeur des épaules, pointes de pieds légèrement tournées vers l'extérieur. Buste droit et mains jointes devant la poitrine.\n\nExécution :\nTransférez le poids du corps sur une jambe et descendez en squat profond tout en gardant l'autre jambe tendue sur le côté. Faites pivoter le pied de la jambe tendue pour orienter les orteils vers le plafond en appui sur le talon. Descendez le plus bas possible en gardant le talon d'appui au sol et le dos droit. Poussez sur la jambe pour revenir au centre et enchaînez directement de l'autre côté.\n\nConseils :\nFait partie de la routine Limber 11 (5 à 10 répétitions de chaque côté). Développe la mobilité des hanches, des chevilles et la souplesse des adducteurs.","region":"lower_body","setup":["Boîte de pliométrie (Plyo box) / Step"],"muscles":["Fessiers","Quadriceps"],"search":["Cossack Squat","1-leg-box-squat","Squat sur boîte à une jambe","Squat cosaque","Cossack Squats"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"jesusd","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1949","name":"Routine de mobilité Limber 11","description":"La routine Limber 11 conçue par le coach Joe DeFranco est un circuit complet d'échauffement et de mobilité pour le bas du corps combinant automassage et étirements ciblés :\n\n1. Rouleau de massage sur le tractus ilio-tibial (10 à 15 passages)\n2. Rouleau de massage sur les adducteurs (10 à 15 passages)\n3. Automassage des fessiers à la balle de crosse (30 s à 2 min)\n4. Croix de fer genoux fléchis (5 à 10 répétitions par côté)\n5. Roulades vers le V-sit (10 répétitions)\n6. Étirement de la grenouille avec balancement (10 répétitions)\n7. Cercles de hanche à quatre pattes / Fire Hydrant (10 vers l'avant / 10 vers l'arrière)\n8. Mountain climbers (10 répétitions par jambe)\n9. Squats cosaques (5 à 10 répétitions par côté)\n10. Étirement du piriforme assis (20 à 30 s par côté)\n11. Étirement des fléchisseurs de hanche pied arrière surélevé (5 à 10 répétitions avec maintien de 3 s)","region":"full_body","setup":["Rouleau de massage (Foam roller)","Tapis de sol"],"muscles":["Adducteurs","Fessiers","Ischio-jambiers","Tronc / Sangle abdominale"],"search":["Limber 11 Mobility Routine","limber-11","Limber 11","Joe DeFranco Limber 11"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Pete-E automation probe","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1950","name":"Automassage au rouleau de la bandelette ilio-tibiale","description":"Allongé sur le côté, positionnez le rouleau sous la bandelette ilio-tibiale et massez lentement de la crête iliaque jusqu'au-dessus du genou.","region":"lower_body","setup":["Rouleau de massage (Foam roller)","Tapis de sol"],"muscles":["Fessiers"],"search":["Foam Roll IT Band","foam-roll-it-band"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Pete-E automation","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Pete-E automation"},
  {"id":"1952","name":"Automassage des fessiers à la balle de crosse","description":"Assis sur une balle de crosse ou de massage, ciblez les points de tension dans la musculature fessière et effectuez de petites rotations circulaires.","region":"lower_body","setup":["Balle de crosse / Balle de massage","Tapis de sol"],"muscles":["Fessiers"],"search":["SMR Glutes with Lacrosse Ball","smr-glutes-lax-ball"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Pete-E automation","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Pete-E automation"},
  {"id":"1953","name":"Croix de fer jambes fléchies au sol","description":"Allongé sur le dos avec les genoux pliés à 90 degrés, laissez tomber lentement les jambes d'un côté puis de l'autre en contrôlant avec les abdominaux obliques.","region":"full_body","setup":["Tapis de sol"],"muscles":["Fessiers","Tronc / Sangle abdominale"],"search":["Bent-Knee Iron Cross","bent-knee-iron-cross"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Pete-E automation","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Pete-E automation"},
  {"id":"1954","name":"Roulades au sol vers le V-Sit","description":"Allongé sur le dos, roulez vers l'arrière pour amener les jambes derrière la tête puis revenez dynamiquement vers l'avant en position de V-sit jambes écartées.","region":"lower_body","setup":["Tapis de sol"],"muscles":["Adducteurs","Ischio-jambiers"],"search":["Roll-Overs into V-Sits","roll-overs-into-v-sits"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Pete-E automation","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Pete-E automation"},
  {"id":"1956","name":"Rotations de la hanche à quatre pattes (Fire hydrant)","description":"À quatre pattes, levez un genou fléchi sur le côté comme pour un hidrant, puis effectuez de grands cercles d'avant en arrière avec la hanche.","region":"lower_body","setup":["Tapis de sol"],"muscles":["Fessiers"],"search":["Fire Hydrant Circles","fire-hydrant-circles"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Pete-E automation","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Pete-E automation"},
  {"id":"1959","name":"Étirement du piriforme assis","description":"Position de départ :\nAsseyez-vous bien droit sur le bord d'une chaise ou d'un banc, pieds à plat sur le sol. Posez la cheville d'une jambe sur le genou opposé en formant un quatre.\n\nExécution :\nEn gardant le dos bien droit et la poitrine fière, penchez-vous lentement vers l'avant à partir des hanches jusqu'à ressentir un étirement profond dans le fessier et le muscle piriforme. Maintenez la position de manière statique pendant 20 à 30 secondes en respirant calmement, puis changez de côté.\n\nConseils :\nFait partie de la routine Limber 11. Ne courbez pas le bas du dos; l'inclinaison doit se faire depuis le bassin pour cibler efficacement les rotateurs profonds de hanche.","region":"lower_body","setup":["Chaise / Surface surélevée","Tapis de sol"],"muscles":["Fessiers"],"search":["Seated Piriformis Stretch","seated-piriformis-stretch","Étirement du piriforme assis","Seated Piriformis Stretch"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Pete-E automation","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1960","name":"Étirement des fléchisseurs de hanche avec pied arrière surélevé","description":"Position de départ :\nPlacez-vous en fente devant un banc ou un support, le cou-de-pied de la jambe arrière posé sur le support et le genou au sol sur un tapis. La jambe avant est fléchie à 90 degrés, buste droit.\n\nExécution :\nBasculez le bassin en rétroversion et contractez puissamment le fessier de la jambe arrière en avançant légèrement les hanches. Maintenez l'étirement intense du psoas et du quadriceps pendant 3 secondes, relâchez légèrement et répétez 5 à 10 fois par côté de manière dynamique.\n\nConseils :\nFait partie de la routine Limber 11. Ne cambrez pas le bas du dos; l'activation du grand fessier est indispensable pour étirer les fléchisseurs de hanche en toute sécurité.","region":"full_body","setup":["Banc plat","Tapis de sol"],"muscles":["Quadriceps","Tronc / Sangle abdominale"],"search":["Rear-Foot-Elevated Hip Flexor Stretch","rear-foot-elevated-hip-flexor-stretch","Étirement des fléchisseurs de la hanche, pied arrière surélevé","Rear-foot-elevated Hip Flexor Stretch"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Pete-E automation","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1962","name":"Step Jack (Jumping jack à faible impact)","description":"Position de départ :\nDebout, pieds joints et bras relâchés le long du corps, sangle abdominale légèrement engagée.\n\nExécution :\nFaites un pas latéral sur la droite tout en levant simultanément les deux bras en arc de cercle au-dessus de la tête. Ramenez le pied au centre en abaissant les bras, puis enchaînez immédiatement en faisant un pas latéral sur la gauche. Poursuivez en alternant de façon rythmée.\n\nConseils :\nExcellente alternative sans saut aux jumping jacks traditionnels; stimule le système cardiovasculaire sans choc articulaire.","region":"lower_body","setup":[],"muscles":["Mollets","Quadriceps"],"search":["Step Jack (Low-Impact Jumping Jack)","step-jack","Step Jack","Side Step Jack"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Anon#2","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1963","name":"Squat lent au tempo (Tempo Squat)","description":"Position de départ :\nDebout, pieds écartés à la largeur des épaules, pointes légèrement ouvertes vers l'extérieur. Buste droit et bras tendus devant vous pour l'équilibre.\n\nExécution :\nDescendez lentement en squat pendant 3 secondes en poussant les fesses vers l'arrière jusqu'à ce que les cuisses soient parallèles au sol. Marquez une pause isométrique de 2 secondes en bas sans relâcher la tension, puis remontez avec puissance en 1 seconde en poussant sur les talons.\n\nConseils :\nCe tempo strict (3 secondes de descente, 2 de pause, 1 de montée) décuple le temps sous tension et renforce la stabilité articulaire.","region":"lower_body","setup":[],"muscles":["Fessiers","Quadriceps"],"search":["Slow Squat","slow-squat","Squat lent","Tempo Squat"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Anon#2","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1964","name":"Pompes prise large (Wide Push-Up)","description":"Position de départ :\nPlacez-vous en planche haute, les mains écartées plus largement que la largeur des épaules (environ 1,5 fois la largeur des épaules), doigts légèrement orientés vers l'extérieur. Corps parfaitement aligné de la tête aux talons.\n\nExécution :\nDescendez la poitrine vers le sol de façon contrôlée en fléchissant les coudes jusqu'à ce que le torse frôle le sol. Marquez une courte pause, puis poussez puissamment sur les paumes pour remonter en position initiale.\n\nConseils :\nCette prise large accentue le recrutement du grand pectoral et des épaules antérieures tout en diminuant l'intervention des triceps. Gardez le bassin gainé.","region":"upper_body","setup":[],"muscles":["Poitrine"],"search":["Wide Push-Up","wide-push-up","Pompe écartée","Pompe prise large","Wide Push-Up"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Anon#2","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1965","name":"Montées de genou debout","description":"Position de départ :\nDebout, pieds écartés à la largeur du bassin, buste droit et bras fléchis à 90 degrés devant vous.\n\nExécution :\nMontez un genou vers la poitrine jusqu'à ce que la cuisse soit au moins parallèle au sol, en restant stable sur la jambe d'appui. Redescendez le pied sous contrôle et montez aussitôt l'autre genou de manière alternée et rythmée.\n\nConseils :\nNe penchez pas le buste vers l'arrière lors de la montée du genou; engagez les fléchisseurs de la hanche et les abdominaux pour guider l'élévation.","region":"full_body","setup":[],"muscles":["Quadriceps","Tronc / Sangle abdominale"],"search":["Standing Knee Raise","marching-high-knees","Montées de genoux sur place","Montée de genou debout","Standing Knee Raise"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Anon#2","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"1966","name":"Rotation thoracique en fente basse contre un mur","description":"Position de départ :\nPlacez-vous en position de chevalier servant (un genou au sol) à côté d'un mur, la jambe avant fléchie à 90 degrés du côté du mur. Vous pouvez coincer un ballon en mousse entre votre genou avant et le mur pour stabiliser le bassin. Tendez les deux bras devant vous à hauteur d'épaules.\n\nExécution :\nOuvrez le bras extérieur vers l'arrière dans un grand mouvement circulaire en tournant le haut du buste et le regard. Gardez le genou avant et les hanches orientés droit devant sans bouger. Maintenez l'ouverture maximale pendant 1 à 2 secondes puis ramenez le bras vers l'avant.\n\nConseils :\nCe calage contre le mur isole la rotation dans la colonne thoracique sans laisser la région lombaire compenser.","region":"core","setup":["Mur","Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["Half-Kneeling Thoracic Rotation","1-2-kneeling-thoracic-rotation","Rotation thoracique à demi-genou","Rotation thoracique en demi-chevalier","Half-Kneeling Thoracic Rotation"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"amwang4","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"2447","name":"Hip Airplane (rotation de hanche)","description":"Position de départ :\nMettez-vous en équilibre sur une jambe (aidez-vous d'un appui fixe avec la main si nécessaire). Penchez le buste vers l'avant avec le dos droit tout en tendant l'autre jambe derrière vous, jusqu'à ce que le torse et la jambe soient parallèles au sol.\n\nExécution :\n1. Faites pivoter lentement le bassin vers l'intérieur (rotation interne de hanche), en refermant la hanche libre vers le sol.\n2. Pivotez ensuite le bassin vers l'extérieur et le haut (rotation externe de hanche), en ouvrant largement la hanche vers le plafond.\n3. Revenez en position neutre de manière fluide et contrôlée, puis enchaînez les répétitions avant de changer de jambe.\n\nConseils :\nLe mouvement doit provenir exclusivement de la hanche de la jambe d'appui. Gardez le pied bien ancré et le genou d'appui stable sans affaissement intérieur.","region":"lower_body","setup":[],"muscles":["Fessiers"],"search":["Hip Airplane","hip-airplane","Hip Airplane","Rotation de hanche sur une jambe"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"TobiasFalk","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"2448","name":"Clamshell inversé","description":"Position de départ :\nAllongez-vous sur le côté, les hanches et les genoux fléchis à environ 90 degrés, les jambes superposées. Reposez votre tête sur votre bras inférieur.\n\nExécution :\n1. En maintenant les genoux collés l'un contre l'autre, levez le pied supérieur vers le haut en rotation interne de la hanche.\n2. Marquez un arrêt d'une seconde en haut du mouvement pour bien ressentir la contraction des fessiers et rotateurs profonds.\n3. Redescendez lentement le pied jusqu'à la position de départ.\n4. Effectuez toutes les répétitions puis changez de côté.\n\nConseils :\nGardez le bassin bien fixe et perpendiculaire au sol ; ne laissez pas les hanches basculer vers l'avant ou l'arrière.","region":"lower_body","setup":["Tapis de sol"],"muscles":["Fessiers"],"search":["Reverse Clamshell","reverse-clamshell","Clamshell inversé","Reverse Clamshell","Rotation interne hanche couché"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"TobiasFalk","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"2449","name":"Clamshell combiné avec clamshell inversé","description":"Position de départ :\nAllongez-vous sur le côté, hanches et genoux fléchis à 90 degrés. Gardez la jambe supérieure légèrement surélevée tout au long du mouvement.\n\nExécution :\n1. En gardant les talons en contact, ouvrez le genou supérieur vers le haut en rotation externe (clamshell standard).\n2. Refermez le genou, collez les deux genoux et levez le pied supérieur vers le haut en rotation interne (clamshell inversé).\n3. Enchaînez les deux mouvements en alternance de façon fluide et rythmée sans reposer la jambe.\n\nConseils :\nGardez le bassin verrouillé pour que le mouvement vienne exclusivement de la hanche.","region":"lower_body","setup":["Tapis de sol"],"muscles":["Fessiers"],"search":["Clamshell to Reverse Clamshell","clamshell-to-reverse-clamshell","Clamshell vers clamshell inversé","Clamshell to Reverse Clamshell"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"TobiasFalk","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wger.de"},
  {"id":"2454","name":"Élévations Y-T-W au sol","description":"Allongé sur le ventre au sol ou sur un banc, levez les bras en formant successivement les lettres Y, T et W pour renforcer la rétraction scapulaire et les rotateurs d'épaule.","region":"upper_body","setup":["Tapis de sol"],"muscles":["Dos"],"search":["YTW Raises","ytw-raises"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"probablyforging","translationLicense":"CC-BY-SA-4.0","translationAuthor":"probablyforging"},
  {"id":"2480","name":"Nage continue allure modérée (crawl)","description":"Nagez le crawl à une allure souple, détendue et continue sans vous arrêter, équivalente à une intensité où vous seriez capable de tenir une conversation.","region":"upper_body","setup":[],"muscles":["Dos","Épaules"],"search":["Easy Continuous Swim (Freestyle)","easy-continuous-swim-freestyle"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":"Imported from swim plan"},
  {"id":"2482","name":"Exercice respiratoire d'immersion (Bobbing)","description":"Dans l'eau en position verticale, immergez la tête en soufflant continuellement par le nez et la bouche pour vider les poumons, puis remontez prendre une inspiration rythmée.","region":"core","setup":[],"muscles":["Tronc / Sangle abdominale"],"search":["Bobbing Exhale Drill","bobbing-exhale-drill"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":"Imported from swim plan"},
  {"id":"2483","name":"Rotation du buste en maintien au mur (piscine)","description":"Dans le bassin, tenez fermement le bord d'une main et effectuez des rotations contrôlées du buste et du bassin pour délier la ceinture scapulaire et le tronc.","region":"core","setup":["Mur"],"muscles":["Tronc / Sangle abdominale"],"search":["Wall-Hold Head Rotation Drill","wall-hold-rotation"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":"Imported from swim plan"},
  {"id":"2485","name":"Mouvements de bras et roulis (natation)","description":"Poussez sur le mur, nagez quelques mouvements puis roulez complètement sur le côté ou le dos pour prendre 2 à 3 respirations calmes avant de reprendre le crawl.","region":"upper_body","setup":[],"muscles":["Dos","Épaules"],"search":["Stroke-and-Roll Drill","stroke-and-roll-drill"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":"Imported from swim plan"},
  {"id":"2486","name":"Récupération active par immersion (Bobbing)","description":"Exercice de récupération active dans l'eau : enchaînez des immersions douces et rythmées avec expiration sous l'eau pour détendre les muscles et réguler le souffle.","region":"core","setup":[],"muscles":["Tronc / Sangle abdominale"],"search":["Deep-Water Recovery Bobbing","recovery-bobbing"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":"Imported from swim plan"},
  {"id":"2487","name":"Retour au calme en natation","description":"Nagez à un rythme très lent et relâché (crawl, dos ou flottaison active) sans pression de vitesse pour faire redescendre la fréquence cardiaque.","region":"upper_body","setup":[],"muscles":["Dos","Épaules"],"search":["Cool-Down Swim","cool-down-swim"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":null,"translationLicense":"CC-BY-SA-4.0","translationAuthor":"Imported from swim plan"},
  {"id":"2488","name":"Rétroversion du bassin au sol","description":"Allongé sur le dos genoux pliés et pieds à plat, basculez le bassin vers l'arrière pour plaquer complètement le bas du dos contre le sol en activant les abdominaux profonds.","region":"core","setup":["Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["Posterior Pelvic Tilt","posterior-pelvic-tilt"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Raj","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Raj"},
  {"id":"2493","name":"Gainage latéral pour adducteurs (Copenhague)","description":"En position de planche latérale, posez le pied supérieur sur un banc et soulevez le bassin en décollant le pied inférieur pour solliciter intensément les adducteurs.","region":"full_body","setup":["Banc plat","Tapis de sol"],"muscles":["Adducteurs","Tronc / Sangle abdominale"],"search":["Adductor Side Plank (Copenhagen Plank)","adductor-side-plank"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"hurr99","translationLicense":"CC-BY-SA-4.0","translationAuthor":"hurr99"},
  {"id":"2496","name":"Pompes contre le mur","description":"Pompes d'initiation réalisées contre un mur, idéales pour apprendre le gainage du corps et la poussée des bras en douceur.","region":"upper_body","setup":["Mur"],"muscles":["Poitrine"],"search":["Wall Push-Ups","wall-push-ups-vasco-l1"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Vasco Custom","translationLicense":"CC-BY-SA-4.0","translationAuthor":null},
  {"id":"2498","name":"Pompes en pique (Pike push-ups)","description":"Variante de pompe pour débutants avec le bassin levé vers le haut, permettant d'apprendre la poussée verticale au poids du corps avec une charge adaptée.","region":"upper_body","setup":["Tapis de sol"],"muscles":["Triceps","Épaules"],"search":["Pike Push-Ups","pike-push-ups-vasco-l1"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Vasco Custom","translationLicense":"CC-BY-SA-4.0","translationAuthor":null},
  {"id":"2499","name":"Pompes inclinées mains surélevées","description":"Pompes réalisées les mains surélevées sur une table ou un banc solide, réduisant la charge corporelle tout en habituant au schéma moteur complet des pompes.","region":"upper_body","setup":["Chaise / Surface surélevée"],"muscles":["Poitrine"],"search":["Incline Push-Ups","incline-push-ups-vasco-l2"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Vasco Custom","translationLicense":"CC-BY-SA-4.0","translationAuthor":null},
  {"id":"2501","name":"Rowing inversé sous une table","description":"Allongé sous une table solide, saisissez le rebord avec les mains et tirez la poitrine vers le plateau en gardant le corps gainé et les talons au sol.","region":"upper_body","setup":[],"muscles":["Dos"],"search":["Inverted Table Row","table-bodyweight-rows-vasco-l1"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Vasco Custom","translationLicense":"CC-BY-SA-4.0","translationAuthor":null},
  {"id":"2503","name":"Face pull au chambranle de porte avec serviette","description":"Pieds calés près du chambranle d'une porte, tenez une serviette passée autour du cadre et tirez le visage vers les mains en écartant les coudes vers l'arrière.","region":"upper_body","setup":[],"muscles":["Dos","Épaules"],"search":["Doorframe Bodyweight Face Pull","face-pulls-bodyweight-doorframe-towel"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Vasco Custom","translationLicense":"CC-BY-SA-4.0","translationAuthor":null},
  {"id":"2505","name":"Dead Bug au sol","description":"Allongé sur le dos, genoux à 90° et bras tendus vers le plafond, tendez simultanément un bras vers l'arrière et la jambe opposée vers l'avant sans cambrer le bas du dos. Revenez au centre et alternez.","region":"core","setup":["Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["Dead Bug","dead-bug-core-l1"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Vasco Custom","translationLicense":"CC-BY-SA-4.0","translationAuthor":null},
  {"id":"2507","name":"Gainage sur les avant-bras","description":"En appui sur les avant-bras et les orteils, maintenez un alignement parfait de la tête aux talons. Contractez les abdominaux, les fessiers et les quadriceps pour stabiliser le bassin.","region":"core","setup":["Tapis de sol"],"muscles":["Tronc / Sangle abdominale"],"search":["Forearm Plank","forearm-plank-core-l1"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Vasco Custom","translationLicense":"CC-BY-SA-4.0","translationAuthor":null},
  {"id":"2508","name":"Bird Dog à quatre pattes","description":"À quatre pattes, le dos plat, tendez simultanément un bras devant vous et la jambe opposée derrière vous à l'horizontale. Maintenez brièvement puis revenez en contrôlant le mouvement avant d'alterner.","region":"full_body","setup":["Tapis de sol"],"muscles":["Bas du dos","Fessiers"],"search":["Bird Dog","bird-dog-core-l1"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Vasco Custom","translationLicense":"CC-BY-SA-4.0","translationAuthor":null},
  {"id":"2509","name":"Gainage latéral (Planche latérale)","description":"En appui sur un avant-bras et la tranche des pieds, maintenez le corps parfaitement aligné de profil. Contractez les obliques et les fessiers pour ne pas laisser tomber la hanche.","region":"core","setup":["Tapis de sol"],"muscles":["Bas du dos","Tronc / Sangle abdominale"],"search":["Side Plank","side-plank-core-l1"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Vasco Custom","translationLicense":"CC-BY-SA-4.0","translationAuthor":null},
  {"id":"2510","name":"Maintien en hollow body (Bateau)","description":"Allongé sur le dos, plaquez les lombaires au sol et décollez légèrement les épaules et les jambes tendues. Maintenez cette position en berceau (hollow body) en respirant calmement.","region":"core","setup":[],"muscles":["Tronc / Sangle abdominale"],"search":["Hollow Body Hold","hollow-body-hold-core-l1"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Vasco Custom","translationLicense":"CC-BY-SA-4.0","translationAuthor":null},
  {"id":"2523","name":"Glissement contre le mur pour le dentelé antérieur","description":"Face à un mur, avant-bras plaqués verticalement contre la paroi, glissez les bras vers le haut en poussant sur les coudes pour activer et étirer le dentelé antérieur.","region":"upper_body","setup":["Mur"],"muscles":["Poitrine"],"search":["Serratus Wall Slide","serratus-wall-slide-stretch"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Croak6728","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Croak6728"},
  {"id":"2525","name":"Couch stretch (étirement sur canapé/mur)","description":"Un genou posé au sol tout près d'un mur avec le coup-de-pied dressé contre la paroi, redressez le buste pour un étirement très intense du quadriceps et du psoas.","region":"full_body","setup":["Banc plat","Tapis de sol"],"muscles":["Quadriceps","Tronc / Sangle abdominale"],"search":["Couch Stretch","couch-stretch"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Croak6728","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Croak6728"},
  {"id":"2526","name":"Fente longue avec pulsations","description":"En fente avant très profonde, genou arrière presque au sol ou posé, effectuez de petites pulsations douces de haut en bas pour étirer les fléchisseurs de la hanche et les quadriceps.","region":"full_body","setup":["Tapis de sol"],"muscles":["Fessiers","Tronc / Sangle abdominale"],"search":["Long Lunge Pulse Stretch","long-lunge-pulse-stretch"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Croak6728","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Croak6728"},
  {"id":"2527","name":"Étirement du grand écart facial/sagittal","description":"En position de grand écart antéro-postérieur avec ou sans blocs de soutien, descendez le bassin de manière progressive en maintenant le buste droit pour étirer les ischios et le psoas.","region":"full_body","setup":["Tapis de sol"],"muscles":["Ischio-jambiers","Tronc / Sangle abdominale"],"search":["Front Split Stretch","front-split-stretch"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Croak6728","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Croak6728"},
  {"id":"2528","name":"Squat profond avec extension d'un bras vers le ciel","description":"En position de squat complet profond, posez une main au sol entre les pieds et tendez l'autre bras vers le plafond en tournant le regard vers le haut pour ouvrir le haut du dos.","region":"core","setup":[],"muscles":["Tronc / Sangle abdominale"],"search":["Squat Sky Reach Stretch","squat-sky-reach-stretch"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Croak6728","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Croak6728"},
  {"id":"2529","name":"Pompes explosives (pliométriques)","description":"En position de pompe, descendez la poitrine puis poussez sur le sol avec une explosivité maximale de façon à décoller les mains de la surface à chaque répétition.","region":"upper_body","setup":[],"muscles":["Poitrine"],"search":["Explosive Push-Ups","explosive-push-ups"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"ege","translationLicense":"CC-BY-SA-4.0","translationAuthor":"ege"},
  {"id":"2530","name":"Pompes russes sur les avant-bras","description":"Depuis la pompe, descendez la poitrine puis glissez vers l'arrière pour poser les avant-bras au sol, repartez vers l'avant sur les mains et repoussez le sol.","region":"upper_body","setup":[],"muscles":["Poitrine"],"search":["Russian Push-Ups","russian-push-ups"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"ege","translationLicense":"CC-BY-SA-4.0","translationAuthor":"ege"},
  {"id":"2531","name":"Levier sur les coudes (Elbow Lever)","description":"Figure d'équilibre de callisthénie où le corps est maintenu à l'horizontale au-dessus du sol en appui sur les mains, les coudes calés contre l'abdomen ou les crêtes iliaques.","region":"full_body","setup":["Tapis de sol"],"muscles":["Bas du dos","Fessiers"],"search":["Elbow Lever","elbow-lever"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"ege","translationLicense":"CC-BY-SA-4.0","translationAuthor":"ege"},
  {"id":"2532","name":"Maintien penché en planche (Planche lean)","description":"En position de planche haute bras tendus, avancez les épaules bien en avant des poignets en maintenant le corps parfaitement rigide pour habituer les épaules à la planche.","region":"upper_body","setup":["Tapis de sol"],"muscles":["Poitrine","Épaules"],"search":["Planche Lean Hold","planche-lean-hold"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"ege","translationLicense":"CC-BY-SA-4.0","translationAuthor":"ege"},
  {"id":"2533","name":"Suspension en arche (Arch hang)","description":"Suspendu à la barre bras tendus, creusez le haut du dos en engageant fortement les omoplates et les dorsaux vers l'arrière sans plier les bras.","region":"upper_body","setup":["Barre de traction"],"muscles":["Dos"],"search":["Arch Hang","arch-hang"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"wintercyan","translationLicense":"CC-BY-SA-4.0","translationAuthor":"wintercyan"},
  {"id":"2534","name":"Pont de fessiers au sol (Glute Bridge)","description":"Allongé sur le dos, genoux fléchis et pieds à plat, poussez sur les talons pour monter les hanches vers le plafond jusqu'à aligner genoux, bassin et épaules.","region":"lower_body","setup":["Tapis de sol"],"muscles":["Fessiers"],"search":["Glute Bridge","d-puente-de-gluteos"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"dvdfernandez95","translationLicense":"CC-BY-SA-4.0","translationAuthor":"dvdfernandez95"},
  {"id":"2543","name":"Rotations articulaires des poignets","description":"Position de départ :\nTenez-vous debout ou assis le dos droit, les épaules détendues. Entrelacez les doigts devant la poitrine, ou formez deux poings souples tenus devant vous avec les coudes fléchis.\n\nExécution :\n1. Faites tourner lentement les poignets en décrivant des cercles amples et réguliers dans le sens des aiguilles d'une montre sur toute l'amplitude articulaire confortable.\n2. Inversez le sens de rotation (sens antihoraire) à mi-parcours de la série (environ 15 à 30 secondes).\n3. Maintenez une cadence douce pour échauffer progressivement les fléchisseurs et extenseurs du carpe.\n\nConseils :\nÉvitez tout à-coup ou mouvement brusque douloureux. Cet exercice est particulièrement recommandé comme échauffement articulaire avant les pompes, tractions ou appuis sur les mains.","region":"upper_body","setup":[],"muscles":["Avant-bras"],"search":["Wrist Circles","wrist-circles","Cercles de poignets","Mobilisation des poignets","Wrist circles","Rotations des poignets"],"sourceLicense":"CC-BY-SA-4.0","sourceAuthor":"Awlex","translationLicense":"CC-BY-SA-4.0","translationAuthor":"Awlex"}
];
